window.__INFINITY_DSA_GUIDES__ = {"data/guides/1-two-sum.json":{"number":1,"slug":"two-sum","title":"Two Sum","difficulty":"Easy","topics":["Array","Hash Table"],"access":"Free","url":"https://leetcode.com/problems/two-sum/","jsFunctionName":"twoSum","pyMethodName":"twoSum","verification":{"verifiedLanguages":["Java","Python3","Python","JavaScript","TypeScript","C#","PHP"],"untestedLanguages":["C++","C","Go","Kotlin","Swift","Rust","Ruby","Dart","Scala","Elixir","Erlang","Racket"]},"understand":{"question":"Given a list of whole numbers and a target total, which two different positions in the list add up to that exact target?","plainExplanation":"Imagine checking receipts to find two items whose prices add up to an exact gift-card balance. You cannot count the same receipt twice, and you must report the positions (indices) of the two chosen numbers, not the numbers themselves.","inputMeaning":"An integer array nums (for example [4, 9, 1, 7]) and an integer target (for example 10).","outputMeaning":"A two-element array [i, j] holding the 0-based positions of the two numbers where nums[i] + nums[j] == target and i != j.","rules":["You must pick two distinct positions (you cannot reuse the same index twice, even if nums[i] * 2 == target).","The same numeric value can appear at two different positions and still be valid (e.g., [5, 5] with target 10 returns [0, 1]).","Every valid input has exactly one solution, and indices may be returned in any order."],"terms":[{"term":"Index","definition":"A 0-based position in the array. The first number sits at index 0, the second at index 1, and so on."},{"term":"Complement","definition":"The missing partner needed to reach target: complement = target - current_number."},{"term":"Hash Map","definition":"A lookup table that stores key -> value pairs (here, number -> index) so we can check in roughly constant time whether a needed partner appeared earlier."}],"example1":{"input":"nums = [4, 9, 1, 7], target = 10","output":"[1, 2]","whyValid":"At index 1 we have 9 and at index 2 we have 1. Since 1 != 2 and 9 + 1 = 10, [1, 2] is the unique valid pair of indices.","diagram":{"type":"array","items":[{"index":0,"value":4,"state":"default"},{"index":1,"value":9,"state":"match","label":"9"},{"index":2,"value":1,"state":"match","label":"+ 1 = 10"},{"index":3,"value":7,"state":"default"}],"pointers":[{"index":1,"name":"i"},{"index":2,"name":"j"}],"caption":"Positions 1 and 2 hold 9 and 1, which sum to target = 10."}},"example2":{"input":"nums = [-3, 5, 5, 12], target = 10","output":"[1, 2]","whyEdgeCase":"Duplicate values and negative numbers! Notice 5 appears twice at indices 1 and 2. You cannot pair index 1 with itself, so a hash map must avoid matching an element against its own index, and negative numbers like -3 can be present."}},"dryRun":{"approachId":"one-pass-hash","algorithmName":"One-Pass Hash Map","steps":[{"title":"Initialize empty lookup table","description":"Start at index 0 with an empty hash map seen = {}. For each number x, we only need to check if target - x (10 - x) is already inside seen.","state":{"type":"hash","items":[{"index":0,"value":4,"state":"active"},{"index":1,"value":9,"state":"default"},{"index":2,"value":1,"state":"default"},{"index":3,"value":7,"state":"default"}],"pointers":[{"index":0,"name":"i"}],"aux":{"title":"Seen Map (value -> index)","entries":[{"key":"empty","value":"no entries yet"}]},"caption":"Target = 10. Need 10 - 4 = 6."}},{"title":"Index 0 (value 4): store in map","description":"Complement 10 - 4 = 6 is not in seen. Store 4 -> 0 so future elements can pair with it, then advance i to 1.","state":{"type":"hash","items":[{"index":0,"value":4,"state":"skip"},{"index":1,"value":9,"state":"active"},{"index":2,"value":1,"state":"default"},{"index":3,"value":7,"state":"default"}],"pointers":[{"index":1,"name":"i"}],"aux":{"title":"Seen Map (value -> index)","entries":[{"key":"4","value":"idx 0"}]},"caption":"At i = 1 (value 9): need 10 - 9 = 1."}},{"title":"Index 1 (value 9): store in map","description":"Complement 10 - 9 = 1 is not in seen yet. Store 9 -> 1 and advance i to 2.","state":{"type":"hash","items":[{"index":0,"value":4,"state":"skip"},{"index":1,"value":9,"state":"default"},{"index":2,"value":1,"state":"active"},{"index":3,"value":7,"state":"default"}],"pointers":[{"index":2,"name":"i"}],"aux":{"title":"Seen Map (value -> index)","entries":[{"key":"4","value":"idx 0"},{"key":"9","value":"idx 1"}]},"caption":"At i = 2 (value 1): need 10 - 1 = 9."}},{"title":"Index 2 (value 1): complement 9 found!","description":"10 - 1 = 9 IS in seen at index 1! Because we check seen BEFORE inserting nums[2], indices 1 and 2 are guaranteed to be distinct. Return [1, 2].","state":{"type":"hash","items":[{"index":0,"value":4,"state":"skip"},{"index":1,"value":9,"state":"match"},{"index":2,"value":1,"state":"match"},{"index":3,"value":7,"state":"default"}],"pointers":[{"index":1,"name":"seen[9]"},{"index":2,"name":"i"}],"aux":{"title":"Seen Map (value -> index)","entries":[{"key":"4","value":"idx 0"},{"key":"9","value":"idx 1","highlight":true}]},"caption":"Match found! Return [1, 2]."}}]},"approaches":[{"id":"brute-force","name":"Brute Force Nested Loops","recommended":false,"coreIdeaSummary":"Check every distinct pair (i, j) with i < j.","coreIdea":"Try every pair of distinct positions (i, j) with j > i and return as soon as nums[i] + nums[j] equals target.","steps":["Loop i from 0 to n - 2.","For each i, loop j from i + 1 to n - 1.","If nums[i] + nums[j] == target, return [i, j]."],"whyItWorks":"Iterating over all pairs with i < j checks every valid two-index combination exactly once without ever pairing an index with itself.","whenToUse":"Use as a baseline sanity check or when memory is tightly constrained (O(1) extra space) and n is small.","complexity":{"time":"O(n^2)","space":"O(1)","variables":"n = length of nums","boundType":"Worst-case"},"code":{"C++":"#include <vector>\nusing namespace std;\n\nclass Solution {\npublic:\n    vector<int> twoSum(vector<int>& nums, int target) {\n        int n = (int)nums.size();\n        for (int i = 0; i < n; ++i) {\n            for (int j = i + 1; j < n; ++j) {\n                if (nums[i] + nums[j] == target) return {i, j};\n            }\n        }\n        return {};\n    }\n};","Java":"class Solution {\n    public int[] twoSum(int[] nums, int target) {\n        for (int i = 0; i < nums.length; i++) {\n            for (int j = i + 1; j < nums.length; j++) {\n                if (nums[i] + nums[j] == target) {\n                    return new int[] { i, j };\n                }\n            }\n        }\n        return new int[0];\n    }\n}","Python3":"class Solution:\n    def twoSum(self, nums: List[int], target: int) -> List[int]:\n        n = len(nums)\n        for i in range(n):\n            for j in range(i + 1, n):\n                if nums[i] + nums[j] == target:\n                    return [i, j]\n        return []","Python":"class Solution(object):\n    def twoSum(self, nums, target):\n        n = len(nums)\n        for i in range(n):\n            for j in range(i + 1, n):\n                if nums[i] + nums[j] == target:\n                    return [i, j]\n        return []","JavaScript":"function twoSum(nums, target) {\n  for (let i = 0; i < nums.length; i++) {\n    for (let j = i + 1; j < nums.length; j++) {\n      if (nums[i] + nums[j] === target) {\n        return [i, j];\n      }\n    }\n  }\n  return [];\n}","TypeScript":"function twoSum(nums: number[], target: number): number[] {\n  for (let i = 0; i < nums.length; i++) {\n    for (let j = i + 1; j < nums.length; j++) {\n      if (nums[i] + nums[j] === target) {\n        return [i, j];\n      }\n    }\n  }\n  return [];\n}","C#":"public class Solution {\n    public int[] TwoSum(int[] nums, int target) {\n        for (int i = 0; i < nums.Length; i++) {\n            for (int j = i + 1; j < nums.Length; j++) {\n                if (nums[i] + nums[j] == target) {\n                    return new int[] { i, j };\n                }\n            }\n        }\n        return new int[0];\n    }\n}","PHP":"class Solution {\n    function twoSum($nums, $target) {\n        $n = count($nums);\n        for ($i = 0; $i < $n; $i++) {\n            for ($j = $i + 1; $j < $n; $j++) {\n                if ($nums[$i] + $nums[$j] === $target) {\n                    return [$i, $j];\n                }\n            }\n        }\n        return [];\n    }\n}"}},{"id":"two-pass-hash","name":"Two-Pass Hash Map","recommended":false,"coreIdeaSummary":"Index all values first, then look up each element's complement.","coreIdea":"Build a value-to-index map in a first pass, then scan the array a second time checking whether target - nums[i] exists at a different index.","steps":["Pass 1: insert every nums[i] -> i into a hash map.","Pass 2: for each index i, compute complement = target - nums[i].","If complement is in the map and map[complement] != i, return [i, map[complement]]."],"whyItWorks":"Even if duplicates exist, Pass 1 stores the latest index for a value while Pass 2 starts from index 0, so map[complement] != i still finds the second copy cleanly.","whenToUse":"Helpful when separating index construction from querying makes code easier to reason about.","complexity":{"time":"O(n)","space":"O(n)","variables":"n = length of nums","boundType":"Expected (hash table)"},"code":{"Java":"import java.util.HashMap;\nimport java.util.Map;\n\nclass Solution {\n    public int[] twoSum(int[] nums, int target) {\n        Map<Integer, Integer> indexByVal = new HashMap<>();\n        for (int i = 0; i < nums.length; i++) {\n            indexByVal.put(nums[i], i);\n        }\n        for (int i = 0; i < nums.length; i++) {\n            int need = target - nums[i];\n            Integer j = indexByVal.get(need);\n            if (j != null && j != i) {\n                return new int[] { i, j };\n            }\n        }\n        return new int[0];\n    }\n}","Python3":"class Solution:\n    def twoSum(self, nums: List[int], target: int) -> List[int]:\n        index_by_val = {val: i for i, val in enumerate(nums)}\n        for i, val in enumerate(nums):\n            need = target - val\n            if need in index_by_val and index_by_val[need] != i:\n                return [i, index_by_val[need]]\n        return []","Python":"class Solution(object):\n    def twoSum(self, nums, target):\n        index_by_val = {val: i for i, val in enumerate(nums)}\n        for i, val in enumerate(nums):\n            need = target - val\n            if need in index_by_val and index_by_val[need] != i:\n                return [i, index_by_val[need]]\n        return []","JavaScript":"function twoSum(nums, target) {\n  const indexByVal = new Map();\n  for (let i = 0; i < nums.length; i++) {\n    indexByVal.set(nums[i], i);\n  }\n  for (let i = 0; i < nums.length; i++) {\n    const need = target - nums[i];\n    if (indexByVal.has(need) && indexByVal.get(need) !== i) {\n      return [i, indexByVal.get(need)];\n    }\n  }\n  return [];\n}","TypeScript":"function twoSum(nums: number[], target: number): number[] {\n  const indexByVal = new Map<number, number>();\n  for (let i = 0; i < nums.length; i++) {\n    indexByVal.set(nums[i], i);\n  }\n  for (let i = 0; i < nums.length; i++) {\n    const need = target - nums[i];\n    const j = indexByVal.get(need);\n    if (j !== undefined && j !== i) {\n      return [i, j];\n    }\n  }\n  return [];\n}","C#":"using System.Collections.Generic;\n\npublic class Solution {\n    public int[] TwoSum(int[] nums, int target) {\n        var map = new Dictionary<int, int>();\n        for (int i = 0; i < nums.Length; i++) {\n            map[nums[i]] = i;\n        }\n        for (int i = 0; i < nums.Length; i++) {\n            int need = target - nums[i];\n            int j;\n            if (map.TryGetValue(need, out j) && j != i) {\n                return new int[] { i, j };\n            }\n        }\n        return new int[0];\n    }\n}","PHP":"class Solution {\n    function twoSum($nums, $target) {\n        $map = [];\n        foreach ($nums as $i => $val) {\n            $map[$val] = $i;\n        }\n        foreach ($nums as $i => $val) {\n            $need = $target - $val;\n            if (isset($map[$need]) && $map[$need] !== $i) {\n                return [$i, $map[$need]];\n            }\n        }\n        return [];\n    }\n}"}},{"id":"sort-two-pointers","name":"Sort + Two Pointers","recommended":false,"coreIdeaSummary":"Sort (value, originalIndex) pairs and walk inward from both ends.","coreIdea":"Pair each value with its original index, sort by value, and move left/right pointers inward based on whether the current sum is too small or too large.","steps":["Build pairs (nums[i], i) for all i.","Sort the pairs in non-decreasing order by value.","Set left = 0, right = n - 1. While left < right, compute sum = pairs[left].val + pairs[right].val.","If sum == target, return the two original indices; if sum < target, increment left; else decrement right."],"whyItWorks":"Because the pairs are sorted by value, increasing left strictly cannot decrease the sum and decreasing right strictly cannot increase it, guaranteeing we never skip the valid pair.","whenToUse":"Great when the input is already sorted (eliminating the O(n log n) sort and O(n) pairing) or as the foundation for 3Sum and 4Sum.","complexity":{"time":"O(n log n)","space":"O(n)","variables":"n = length of nums","boundType":"Worst-case (comparison sort)"},"code":{"Java":"import java.util.Arrays;\nimport java.util.Comparator;\n\nclass Solution {\n    public int[] twoSum(int[] nums, int target) {\n        int n = nums.length;\n        int[][] pairs = new int[n][2];\n        for (int i = 0; i < n; i++) {\n            pairs[i][0] = nums[i];\n            pairs[i][1] = i;\n        }\n        Arrays.sort(pairs, Comparator.comparingInt(a -> a[0]));\n        int left = 0, right = n - 1;\n        while (left < right) {\n            int sum = pairs[left][0] + pairs[right][0];\n            if (sum == target) {\n                return new int[] { pairs[left][1], pairs[right][1] };\n            } else if (sum < target) {\n                left++;\n            } else {\n                right--;\n            }\n        }\n        return new int[0];\n    }\n}","Python3":"class Solution:\n    def twoSum(self, nums: List[int], target: int) -> List[int]:\n        pairs = sorted((val, idx) for idx, val in enumerate(nums))\n        left, right = 0, len(pairs) - 1\n        while left < right:\n            total = pairs[left][0] + pairs[right][0]\n            if total == target:\n                return [pairs[left][1], pairs[right][1]]\n            if total < target:\n                left += 1\n            else:\n                right -= 1\n        return []","Python":"class Solution(object):\n    def twoSum(self, nums, target):\n        pairs = sorted((val, idx) for idx, val in enumerate(nums))\n        left, right = 0, len(pairs) - 1\n        while left < right:\n            total = pairs[left][0] + pairs[right][0]\n            if total == target:\n                return [pairs[left][1], pairs[right][1]]\n            if total < target:\n                left += 1\n            else:\n                right -= 1\n        return []","JavaScript":"function twoSum(nums, target) {\n  const pairs = nums.map((val, idx) => [val, idx]).sort((a, b) => a[0] - b[0]);\n  let left = 0;\n  let right = pairs.length - 1;\n  while (left < right) {\n    const sum = pairs[left][0] + pairs[right][0];\n    if (sum === target) return [pairs[left][1], pairs[right][1]];\n    if (sum < target) left++;\n    else right--;\n  }\n  return [];\n}","TypeScript":"function twoSum(nums: number[], target: number): number[] {\n  const pairs: [number, number][] = nums\n    .map((val, idx): [number, number] => [val, idx])\n    .sort((a, b) => a[0] - b[0]);\n  let left = 0;\n  let right = pairs.length - 1;\n  while (left < right) {\n    const sum = pairs[left][0] + pairs[right][0];\n    if (sum === target) return [pairs[left][1], pairs[right][1]];\n    if (sum < target) left++;\n    else right--;\n  }\n  return [];\n}","C#":"using System;\n\npublic class Solution {\n    public int[] TwoSum(int[] nums, int target) {\n        int n = nums.Length;\n        int[] idx = new int[n];\n        for (int i = 0; i < n; i++) idx[i] = i;\n        Array.Sort(idx, (a, b) => nums[a].CompareTo(nums[b]));\n        int left = 0, right = n - 1;\n        while (left < right) {\n            int sum = nums[idx[left]] + nums[idx[right]];\n            if (sum == target) return new int[] { idx[left], idx[right] };\n            if (sum < target) left++;\n            else right--;\n        }\n        return new int[0];\n    }\n}","PHP":"class Solution {\n    function twoSum($nums, $target) {\n        $pairs = [];\n        foreach ($nums as $i => $val) {\n            $pairs[] = [$val, $i];\n        }\n        usort($pairs, function ($a, $b) { return $a[0] <=> $b[0]; });\n        $left = 0;\n        $right = count($pairs) - 1;\n        while ($left < $right) {\n            $sum = $pairs[$left][0] + $pairs[$right][0];\n            if ($sum === $target) return [$pairs[$left][1], $pairs[$right][1]];\n            if ($sum < $target) $left++;\n            else $right--;\n        }\n        return [];\n    }\n}"}},{"id":"sort-binary-search","name":"Sort + Binary Search","recommended":false,"coreIdeaSummary":"Sort (value, index) pairs and binary-search the complement for each position.","coreIdea":"After sorting value-index pairs, iterate through each position i and binary-search the suffix [i + 1 .. n - 1] for target - pairs[i].val.","steps":["Store (nums[i], i) pairs and sort by value.","For each sorted index i from 0 to n - 2, binary-search in [i + 1, n - 1] for need = target - pairs[i].val.","If found at mid, return [pairs[i].idx, pairs[mid].idx]."],"whyItWorks":"Sorting makes every suffix [i + 1 .. n - 1] monotonic, so binary search checks for the partner in O(log n) without revisiting index i.","whenToUse":"Useful when worst-case O(n log n) predictability matters more than expected O(n) hash performance.","complexity":{"time":"O(n log n)","space":"O(n)","variables":"n = length of nums","boundType":"Worst-case"},"code":{"Java":"import java.util.Arrays;\nimport java.util.Comparator;\n\nclass Solution {\n    public int[] twoSum(int[] nums, int target) {\n        int n = nums.length;\n        int[][] pairs = new int[n][2];\n        for (int i = 0; i < n; i++) {\n            pairs[i][0] = nums[i];\n            pairs[i][1] = i;\n        }\n        Arrays.sort(pairs, Comparator.comparingInt(a -> a[0]));\n        for (int i = 0; i < n - 1; i++) {\n            int need = target - pairs[i][0];\n            int lo = i + 1, hi = n - 1;\n            while (lo <= hi) {\n                int mid = lo + (hi - lo) / 2;\n                if (pairs[mid][0] == need) {\n                    return new int[] { pairs[i][1], pairs[mid][1] };\n                } else if (pairs[mid][0] < need) {\n                    lo = mid + 1;\n                } else {\n                    hi = mid - 1;\n                }\n            }\n        }\n        return new int[0];\n    }\n}","Python3":"class Solution:\n    def twoSum(self, nums: List[int], target: int) -> List[int]:\n        pairs = sorted((val, idx) for idx, val in enumerate(nums))\n        n = len(pairs)\n        for i in range(n - 1):\n            need = target - pairs[i][0]\n            lo, hi = i + 1, n - 1\n            while lo <= hi:\n                mid = (lo + hi) // 2\n                if pairs[mid][0] == need:\n                    return [pairs[i][1], pairs[mid][1]]\n                if pairs[mid][0] < need:\n                    lo = mid + 1\n                else:\n                    hi = mid - 1\n        return []","Python":"class Solution(object):\n    def twoSum(self, nums, target):\n        pairs = sorted((val, idx) for idx, val in enumerate(nums))\n        n = len(pairs)\n        for i in range(n - 1):\n            need = target - pairs[i][0]\n            lo, hi = i + 1, n - 1\n            while lo <= hi:\n                mid = (lo + hi) // 2\n                if pairs[mid][0] == need:\n                    return [pairs[i][1], pairs[mid][1]]\n                if pairs[mid][0] < need:\n                    lo = mid + 1\n                else:\n                    hi = mid - 1\n        return []","JavaScript":"function twoSum(nums, target) {\n  const pairs = nums.map((val, idx) => [val, idx]).sort((a, b) => a[0] - b[0]);\n  for (let i = 0; i < pairs.length - 1; i++) {\n    const need = target - pairs[i][0];\n    let lo = i + 1;\n    let hi = pairs.length - 1;\n    while (lo <= hi) {\n      const mid = (lo + hi) >> 1;\n      if (pairs[mid][0] === need) return [pairs[i][1], pairs[mid][1]];\n      if (pairs[mid][0] < need) lo = mid + 1;\n      else hi = mid - 1;\n    }\n  }\n  return [];\n}","TypeScript":"function twoSum(nums: number[], target: number): number[] {\n  const pairs: [number, number][] = nums\n    .map((val, idx): [number, number] => [val, idx])\n    .sort((a, b) => a[0] - b[0]);\n  for (let i = 0; i < pairs.length - 1; i++) {\n    const need = target - pairs[i][0];\n    let lo = i + 1;\n    let hi = pairs.length - 1;\n    while (lo <= hi) {\n      const mid = (lo + hi) >> 1;\n      if (pairs[mid][0] === need) return [pairs[i][1], pairs[mid][1]];\n      if (pairs[mid][0] < need) lo = mid + 1;\n      else hi = mid - 1;\n    }\n  }\n  return [];\n}","C#":"using System;\n\npublic class Solution {\n    public int[] TwoSum(int[] nums, int target) {\n        int n = nums.Length;\n        int[] idx = new int[n];\n        for (int i = 0; i < n; i++) idx[i] = i;\n        Array.Sort(idx, (a, b) => nums[a].CompareTo(nums[b]));\n        for (int i = 0; i < n - 1; i++) {\n            int need = target - nums[idx[i]];\n            int lo = i + 1, hi = n - 1;\n            while (lo <= hi) {\n                int mid = lo + (hi - lo) / 2;\n                int val = nums[idx[mid]];\n                if (val == need) return new int[] { idx[i], idx[mid] };\n                if (val < need) lo = mid + 1;\n                else hi = mid - 1;\n            }\n        }\n        return new int[0];\n    }\n}","PHP":"class Solution {\n    function twoSum($nums, $target) {\n        $pairs = [];\n        foreach ($nums as $i => $val) $pairs[] = [$val, $i];\n        usort($pairs, function ($a, $b) { return $a[0] <=> $b[0]; });\n        $n = count($pairs);\n        for ($i = 0; $i < $n - 1; $i++) {\n            $need = $target - $pairs[$i][0];\n            $lo = $i + 1;\n            $hi = $n - 1;\n            while ($lo <= $hi) {\n                $mid = intdiv($lo + $hi, 2);\n                if ($pairs[$mid][0] === $need) return [$pairs[$i][1], $pairs[$mid][1]];\n                if ($pairs[$mid][0] < $need) $lo = $mid + 1;\n                else $hi = $mid - 1;\n            }\n        }\n        return [];\n    }\n}"}},{"id":"one-pass-hash","name":"One-Pass Hash Map","recommended":true,"recommendedTradeOff":"Trades O(n) extra hash table memory to cut runtime from O(n^2) to expected O(n) in a single left-to-right scan, while naturally preventing self-pairing.","coreIdeaSummary":"Check if target - nums[i] was already seen before inserting nums[i].","coreIdea":"Maintain a hash map of numbers seen so far and their indices. At index i, immediately query whether target - nums[i] is already stored; if not, record nums[i] -> i.","steps":["Create an empty hash map seen (value -> index).","Iterate i from 0 to n - 1 and compute complement = target - nums[i].","If complement exists in seen, return [seen[complement], i].","Otherwise insert seen[nums[i]] = i and continue."],"whyItWorks":"For any valid pair (a, b) with a < b, when the loop reaches b, nums[a] has already been placed into seen. Checking seen before inserting nums[b] also guarantees a != b even when nums[a] == nums[b].","whenToUse":"Default choice for unsorted arrays whenever O(n) auxiliary space is acceptable.","complexity":{"time":"O(n)","space":"O(n)","variables":"n = length of nums","boundType":"Expected (worst-case O(n^2) only under adversarial hash collisions)"},"code":{"C++":"#include <unordered_map>\n#include <vector>\nusing namespace std;\n\nclass Solution {\npublic:\n    vector<int> twoSum(vector<int>& nums, int target) {\n        unordered_map<int, int> seen;\n        for (int i = 0; i < (int)nums.size(); ++i) {\n            int need = target - nums[i];\n            auto it = seen.find(need);\n            if (it != seen.end()) return {it->second, i};\n            seen[nums[i]] = i;\n        }\n        return {};\n    }\n};","Java":"import java.util.HashMap;\nimport java.util.Map;\n\nclass Solution {\n    public int[] twoSum(int[] nums, int target) {\n        Map<Integer, Integer> seen = new HashMap<>();\n        for (int i = 0; i < nums.length; i++) {\n            int need = target - nums[i];\n            if (seen.containsKey(need)) {\n                return new int[] { seen.get(need), i };\n            }\n            seen.put(nums[i], i);\n        }\n        return new int[0];\n    }\n}","Python3":"class Solution:\n    def twoSum(self, nums: List[int], target: int) -> List[int]:\n        seen: Dict[int, int] = {}\n        for i, num in enumerate(nums):\n            need = target - num\n            if need in seen:\n                return [seen[need], i]\n            seen[num] = i\n        return []","Python":"class Solution(object):\n    def twoSum(self, nums, target):\n        seen = {}\n        for i, num in enumerate(nums):\n            need = target - num\n            if need in seen:\n                return [seen[need], i]\n            seen[num] = i\n        return []","JavaScript":"function twoSum(nums, target) {\n  const seen = new Map();\n  for (let i = 0; i < nums.length; i++) {\n    const need = target - nums[i];\n    if (seen.has(need)) {\n      return [seen.get(need), i];\n    }\n    seen.set(nums[i], i);\n  }\n  return [];\n}","TypeScript":"function twoSum(nums: number[], target: number): number[] {\n  const seen = new Map<number, number>();\n  for (let i = 0; i < nums.length; i++) {\n    const need = target - nums[i];\n    const prev = seen.get(need);\n    if (prev !== undefined) {\n      return [prev, i];\n    }\n    seen.set(nums[i], i);\n  }\n  return [];\n}","C#":"using System.Collections.Generic;\n\npublic class Solution {\n    public int[] TwoSum(int[] nums, int target) {\n        var seen = new Dictionary<int, int>();\n        for (int i = 0; i < nums.Length; i++) {\n            int need = target - nums[i];\n            int prev;\n            if (seen.TryGetValue(need, out prev)) {\n                return new int[] { prev, i };\n            }\n            seen[nums[i]] = i;\n        }\n        return new int[0];\n    }\n}","C":"#include <stdlib.h>\n\nint* twoSum(int* nums, int numsSize, int target, int* returnSize) {\n    int* res = (int*)malloc(2 * sizeof(int));\n    *returnSize = 2;\n    for (int i = 0; i < numsSize; i++) {\n        for (int j = i + 1; j < numsSize; j++) {\n            if (nums[i] + nums[j] == target) {\n                res[0] = i;\n                res[1] = j;\n                return res;\n            }\n        }\n    }\n    *returnSize = 0;\n    return res;\n}","Go":"func twoSum(nums []int, target int) []int {\n\tseen := make(map[int]int, len(nums))\n\tfor i, v := range nums {\n\t\tif j, ok := seen[target-v]; ok {\n\t\t\treturn []int{j, i}\n\t\t}\n\t\tseen[v] = i\n\t}\n\treturn nil\n}","Kotlin":"class Solution {\n    fun twoSum(nums: IntArray, target: Int): IntArray {\n        val seen = HashMap<Int, Int>()\n        for (i in nums.indices) {\n            val need = target - nums[i]\n            val prev = seen[need]\n            if (prev != null) return intArrayOf(prev, i)\n            seen[nums[i]] = i\n        }\n        return intArrayOf()\n    }\n}","Swift":"class Solution {\n    func twoSum(_ nums: [Int], _ target: Int) -> [Int] {\n        var seen = [Int: Int]()\n        for (i, num) in nums.enumerated() {\n            if let prev = seen[target - num] {\n                return [prev, i]\n            }\n            seen[num] = i\n        }\n        return []\n    }\n}","Rust":"use std::collections::HashMap;\n\nimpl Solution {\n    pub fn two_sum(nums: Vec<i32>, target: i32) -> Vec<i32> {\n        let mut seen = HashMap::new();\n        for (i, &num) in nums.iter().enumerate() {\n            if let Some(&prev) = seen.get(&(target - num)) {\n                return vec![prev as i32, i as i32];\n            }\n            seen.insert(num, i);\n        }\n        vec![]\n    }\n}","Ruby":"def two_sum(nums, target)\n  seen = {}\n  nums.each_with_index do |num, i|\n    need = target - num\n    return [seen[need], i] if seen.key?(need)\n    seen[num] = i\n  end\n  []\nend","PHP":"class Solution {\n    function twoSum($nums, $target) {\n        $seen = [];\n        foreach ($nums as $i => $num) {\n            $need = $target - $num;\n            if (isset($seen[$need])) {\n                return [$seen[$need], $i];\n            }\n            $seen[$num] = $i;\n        }\n        return [];\n    }\n}","Dart":"class Solution {\n  List<int> twoSum(List<int> nums, int target) {\n    final seen = <int, int>{};\n    for (var i = 0; i < nums.length; i++) {\n      final need = target - nums[i];\n      if (seen.containsKey(need)) return [seen[need]!, i];\n      seen[nums[i]] = i;\n    }\n    return [];\n  }\n}","Scala":"import scala.collection.mutable\n\nobject Solution {\n  def twoSum(nums: Array[Int], target: Int): Array[Int] = {\n    val seen = mutable.HashMap.empty[Int, Int]\n    for (i <- nums.indices) {\n      val need = target - nums(i)\n      seen.get(need) match {\n        case Some(j) => return Array(j, i)\n        case None    => seen(nums(i)) = i\n      }\n    }\n    Array.emptyIntArray\n  }\n}","Elixir":"defmodule Solution do\n  @spec two_sum(nums :: [integer], target :: integer) :: [integer]\n  def two_sum(nums, target) do\n    Enum.with_index(nums)\n    |> Enum.reduce_while(%{}, fn {num, i}, seen ->\n      case Map.get(seen, target - num) do\n        nil -> {:cont, Map.put(seen, num, i)}\n        prev -> {:halt, [prev, i]}\n      end\n    end)\n  end\nend","Erlang":"-spec two_sum(Nums :: [integer()], Target :: integer()) -> [integer()].\ntwo_sum(Nums, Target) ->\n  two_sum(Nums, Target, 0, #{}).\n\ntwo_sum([H | T], Target, I, Seen) ->\n  case maps:find(Target - H, Seen) of\n    {ok, Prev} -> [Prev, I];\n    error -> two_sum(T, Target, I + 1, maps:put(H, I, Seen))\n  end.","Racket":"(define/contract (two-sum nums target)\n  (-> (listof exact-integer?) exact-integer? (listof exact-integer?))\n  (let loop ([rest nums] [i 0] [seen (hash)])\n    (if (null? rest)\n        '()\n        (let* ([x (car rest)]\n               [need (- target x)]\n               [prev (hash-ref seen need #f)])\n          (if prev\n              (list prev i)\n              (loop (cdr rest) (+ i 1) (hash-set seen x i)))))))"}}],"tests":[{"name":"Example 1","args":[[4,9,1,7],10],"expected":[1,2],"unorderedArray":true},{"name":"Example 2 (duplicates + negative)","args":[[-3,5,5,12],10],"expected":[1,2],"unorderedArray":true},{"name":"Zero sum pair","args":[[0,4,3,0],0],"expected":[0,3],"unorderedArray":true},{"name":"Two elements only","args":[[8,-2],6],"expected":[0,1],"unorderedArray":true}],"javaDriver":"import java.util.Arrays;\npublic class Main {\n  static void check(int[] actual, int[] exp, String name) {\n    int[] a = Arrays.copyOf(actual, actual.length); Arrays.sort(a);\n    int[] e = Arrays.copyOf(exp, exp.length); Arrays.sort(e);\n    if (!Arrays.equals(a, e)) throw new AssertionError(name + \": got \" + Arrays.toString(actual));\n  }\n  public static void main(String[] args) {\n    Solution s = new Solution();\n    check(s.twoSum(new int[]{4,9,1,7}, 10), new int[]{1,2}, \"Ex1\");\n    check(s.twoSum(new int[]{-3,5,5,12}, 10), new int[]{1,2}, \"Ex2\");\n    check(s.twoSum(new int[]{0,4,3,0}, 0), new int[]{0,3}, \"Zero\");\n    check(s.twoSum(new int[]{8,-2}, 6), new int[]{0,1}, \"Two\");\n  }\n}","phpDriver":"$s = new Solution();\n$cases = [\n  [[4,9,1,7], 10, [1,2]],\n  [[-3,5,5,12], 10, [1,2]],\n  [[0,4,3,0], 0, [0,3]],\n  [[8,-2], 6, [0,1]]\n];\nforeach ($cases as $c) {\n  $a = $s->twoSum($c[0], $c[1]); sort($a); $e = $c[2]; sort($e);\n  if ($a !== $e) { fwrite(STDERR, \"FAIL\"); exit(1); }\n}","csharpDriver":"using System;\npublic class Runner {\n  static void Check(int[] a, int[] e) {\n    Array.Sort(a); Array.Sort(e);\n    if (a.Length != e.Length || a[0] != e[0] || a[1] != e[1]) throw new Exception(\"Mismatch\");\n  }\n  public static void Main() {\n    var s = new Solution();\n    Check(s.TwoSum(new int[]{4,9,1,7}, 10), new int[]{1,2});\n    Check(s.TwoSum(new int[]{-3,5,5,12}, 10), new int[]{1,2});\n    Check(s.TwoSum(new int[]{0,4,3,0}, 0), new int[]{0,3});\n    Check(s.TwoSum(new int[]{8,-2}, 6), new int[]{0,1});\n  }\n}"},"data/guides/2-add-two-numbers.json":{"number":2,"slug":"add-two-numbers","title":"Add Two Numbers","difficulty":"Medium","topics":["Linked List","Math","Recursion"],"access":"Free","url":"https://leetcode.com/problems/add-two-numbers/","jsFunctionName":"addTwoNumbers","pyMethodName":"addTwoNumbers","runtimeHelpers":"linked_list","verification":{"verifiedLanguages":["Java","Python3","Python","JavaScript","TypeScript","C#","PHP"],"untestedLanguages":[]},"understand":{"question":"Two whole numbers are stored backwards in linked lists (ones digit first). How do we add them together and return their sum as a linked list in the same backwards order?","plainExplanation":"Normally when you add two numbers on paper, you start at the rightmost (ones) column and carry any overflow left to the tens column. Because these linked lists already put the ones digit at the head, walking forward from the head is literally doing column-by-column addition from right to left!","inputMeaning":"Two non-empty singly linked lists l1 and l2, where each node stores a single digit 0..9 in reverse digit order.","outputMeaning":"The head node of a new singly linked list holding the sum's digits in the same reverse order.","rules":["The two lists may have different lengths (for example, adding a 3-digit number and a 2-digit number).","When a column sum is 10 or more, keep total % 10 in the current node and pass carry = Math.floor(total / 10) to the next position.","Do not forget a leftover carry after both lists finish (for example, 95 + 8 produces an extra 1 node at the end)."],"terms":[{"term":"Node","definition":"A small container holding one value (val) and a pointer (next) to the following container, or null at the end."},{"term":"Dummy Head","definition":"A temporary placeholder node placed before the real answer list so appending the first digit needs no special-case check."},{"term":"Carry","definition":"The tens digit (0 or 1 when adding two digits plus a prior carry) forwarded to the next higher place value."}],"example1":{"input":"l1 = [5, 2, 3] (represents 325), l2 = [7, 4] (represents 47)","output":"[2, 7, 3] (represents 372)","whyValid":"Ones place: 5 + 7 = 12 -> digit 2, carry 1. Tens place: 2 + 4 + 1 = 7 -> digit 7, carry 0. Hundreds place: 3 + 0 + 0 = 3 -> digit 3. Result list is 2 -> 7 -> 3.","diagram":{"type":"linked-list","nodes":[{"id":"r0","value":2,"state":"match","label":"(5+7)%10"},{"id":"r1","value":7,"state":"match","label":"2+4+1"},{"id":"r2","value":3,"state":"match","label":"3+0+0"}],"pointers":[{"nodeId":"r0","name":"head"}],"aux":{"title":"Column Math","entries":[{"key":"325 + 47","value":"372","highlight":true}]},"caption":"Result list 2 -> 7 -> 3 represents 372."}},"example2":{"input":"l1 = [9, 9], l2 = [1]","output":"[0, 0, 1]","whyEdgeCase":"Different lengths plus cascading carry past the end! 99 + 1 = 100, so even after both lists end, carry = 1 must still create a final node."}},"dryRun":{"approachId":"iterative-dummy","algorithmName":"Iterative Addition with Dummy Head","steps":[{"title":"Start at ones column with carry = 0","description":"Create dummy -> null. Read l1 = 5 and l2 = 7. Sum = 5 + 7 + 0 = 12 -> append node(2) and set carry = 1.","state":{"type":"linked-list","nodes":[{"id":"n0","value":2,"state":"active","label":"ones"}],"pointers":[{"nodeId":"n0","name":"tail"}],"aux":{"title":"Step 1 State","entries":[{"key":"l1.val","value":5},{"key":"l2.val","value":7},{"key":"sum","value":12},{"key":"carry","value":1,"highlight":true}]},"caption":"Appended 2; carry = 1 passes to tens place."}},{"title":"Tens column: 2 + 4 + carry(1) = 7","description":"Advance l1 to 2 and l2 to 4. Sum = 2 + 4 + 1 = 7 -> append node(7) and set carry = 0.","state":{"type":"linked-list","nodes":[{"id":"n0","value":2,"state":"match","label":"ones"},{"id":"n1","value":7,"state":"active","label":"tens"}],"pointers":[{"nodeId":"n1","name":"tail"}],"aux":{"title":"Step 2 State","entries":[{"key":"l1.val","value":2},{"key":"l2.val","value":4},{"key":"sum","value":7},{"key":"carry","value":0}]},"caption":"Appended 7; l2 is now exhausted."}},{"title":"Hundreds column: 3 + 0 + 0 = 3","description":"l2 is null so treat its digit as 0. Sum = 3 + 0 + 0 = 3 -> append node(3), carry = 0. Both lists and carry are done; return dummy.next.","state":{"type":"linked-list","nodes":[{"id":"n0","value":2,"state":"match","label":"ones"},{"id":"n1","value":7,"state":"match","label":"tens"},{"id":"n2","value":3,"state":"match","label":"hundreds"}],"pointers":[{"nodeId":"n0","name":"return"}],"aux":{"title":"Final State","entries":[{"key":"carry","value":0},{"key":"result","value":"[2, 7, 3]","highlight":true}]},"caption":"Return 2 -> 7 -> 3."}}]},"approaches":[{"id":"iterative-dummy","name":"Iterative Digit-by-Digit with Dummy Head","recommended":true,"recommendedTradeOff":"Processes both lists in a single O(max(m, n)) pass using O(1) extra workspace (excluding the output list) and avoids recursion stack overhead.","coreIdeaSummary":"Walk both lists together while carry > 0, building digits behind a dummy head.","coreIdea":"Keep looping while l1 != null OR l2 != null OR carry != 0. Treat any exhausted list as 0, append total % 10, and update carry = floor(total / 10).","steps":["Create a dummy node and set tail = dummy, carry = 0.","While l1, l2, or carry is non-zero, sum available digits plus carry.","Attach a new node with value sum % 10 to tail.next and advance tail, l1, and l2.","Return dummy.next."],"whyItWorks":"The loop condition (l1 || l2 || carry) handles unequal lengths and trailing carries uniformly in one place without extra cleanup loops.","whenToUse":"Default production solution for linked-list addition.","complexity":{"time":"O(max(m, n))","space":"O(1) auxiliary (O(max(m, n)) for the output list)","variables":"m = length of l1, n = length of l2","boundType":"Worst-case"},"code":{"Java":"class Solution {\n    public ListNode addTwoNumbers(ListNode l1, ListNode l2) {\n        ListNode dummy = new ListNode(0);\n        ListNode tail = dummy;\n        int carry = 0;\n        while (l1 != null || l2 != null || carry != 0) {\n            int x = (l1 != null) ? l1.val : 0;\n            int y = (l2 != null) ? l2.val : 0;\n            int sum = x + y + carry;\n            carry = sum / 10;\n            tail.next = new ListNode(sum % 10);\n            tail = tail.next;\n            if (l1 != null) l1 = l1.next;\n            if (l2 != null) l2 = l2.next;\n        }\n        return dummy.next;\n    }\n}","Python3":"class Solution:\n    def addTwoNumbers(self, l1: Optional[ListNode], l2: Optional[ListNode]) -> Optional[ListNode]:\n        dummy = ListNode(0)\n        tail = dummy\n        carry = 0\n        while l1 or l2 or carry:\n            x = l1.val if l1 else 0\n            y = l2.val if l2 else 0\n            total = x + y + carry\n            carry = total // 10\n            tail.next = ListNode(total % 10)\n            tail = tail.next\n            l1 = l1.next if l1 else None\n            l2 = l2.next if l2 else None\n        return dummy.next","Python":"class Solution(object):\n    def addTwoNumbers(self, l1, l2):\n        dummy = ListNode(0)\n        tail = dummy\n        carry = 0\n        while l1 is not None or l2 is not None or carry != 0:\n            x = l1.val if l1 is not None else 0\n            y = l2.val if l2 is not None else 0\n            total = x + y + carry\n            carry = total // 10\n            tail.next = ListNode(total % 10)\n            tail = tail.next\n            l1 = l1.next if l1 is not None else None\n            l2 = l2.next if l2 is not None else None\n        return dummy.next","JavaScript":"function addTwoNumbers(l1, l2) {\n  const dummy = new ListNode(0);\n  let tail = dummy;\n  let carry = 0;\n  while (l1 !== null || l2 !== null || carry !== 0) {\n    const x = l1 ? l1.val : 0;\n    const y = l2 ? l2.val : 0;\n    const sum = x + y + carry;\n    carry = Math.floor(sum / 10);\n    tail.next = new ListNode(sum % 10);\n    tail = tail.next;\n    if (l1) l1 = l1.next;\n    if (l2) l2 = l2.next;\n  }\n  return dummy.next;\n}","TypeScript":"function addTwoNumbers(l1: ListNode | null, l2: ListNode | null): ListNode | null {\n  const dummy = new ListNode(0);\n  let tail = dummy;\n  let carry = 0;\n  while (l1 !== null || l2 !== null || carry !== 0) {\n    const x = l1 ? l1.val : 0;\n    const y = l2 ? l2.val : 0;\n    const sum = x + y + carry;\n    carry = Math.floor(sum / 10);\n    tail.next = new ListNode(sum % 10);\n    tail = tail.next;\n    if (l1) l1 = l1.next;\n    if (l2) l2 = l2.next;\n  }\n  return dummy.next;\n}","C#":"public class Solution {\n    public ListNode AddTwoNumbers(ListNode l1, ListNode l2) {\n        ListNode dummy = new ListNode(0);\n        ListNode tail = dummy;\n        int carry = 0;\n        while (l1 != null || l2 != null || carry != 0) {\n            int x = l1 != null ? l1.val : 0;\n            int y = l2 != null ? l2.val : 0;\n            int sum = x + y + carry;\n            carry = sum / 10;\n            tail.next = new ListNode(sum % 10);\n            tail = tail.next;\n            if (l1 != null) l1 = l1.next;\n            if (l2 != null) l2 = l2.next;\n        }\n        return dummy.next;\n    }\n}","PHP":"class Solution {\n    function addTwoNumbers($l1, $l2) {\n        $dummy = new ListNode(0);\n        $tail = $dummy;\n        $carry = 0;\n        while ($l1 !== null || $l2 !== null || $carry !== 0) {\n            $x = $l1 !== null ? $l1->val : 0;\n            $y = $l2 !== null ? $l2->val : 0;\n            $sum = $x + $y + $carry;\n            $carry = intdiv($sum, 10);\n            $tail->next = new ListNode($sum % 10);\n            $tail = $tail->next;\n            if ($l1 !== null) $l1 = $l1->next;\n            if ($l2 !== null) $l2 = $l2->next;\n        }\n        return $dummy->next;\n    }\n}"}},{"id":"recursive-carry","name":"Recursive Carry Propagation","recommended":false,"coreIdeaSummary":"Recursively build each digit node and pass the carry down to the next node.","coreIdea":"Define add(l1, l2, carry) which computes one node for the current place value and recursively attaches add(l1.next, l2.next, nextCarry).","steps":["Base case: if l1 == null && l2 == null && carry == 0, return null.","Compute sum = (l1 ? l1.val : 0) + (l2 ? l2.val : 0) + carry.","Create node(sum % 10) and set node.next = add(l1?.next, l2?.next, sum / 10).","Return node."],"whyItWorks":"Each recursive frame computes one column and delegates the remaining higher-order digits plus carry to the next call.","whenToUse":"Elegant when recursion depth max(m, n) is small and functional style is preferred.","complexity":{"time":"O(max(m, n))","space":"O(max(m, n))","variables":"m = length of l1, n = length of l2 (call stack depth)","boundType":"Worst-case"},"code":{"Java":"class Solution {\n    public ListNode addTwoNumbers(ListNode l1, ListNode l2) {\n        return add(l1, l2, 0);\n    }\n    private ListNode add(ListNode l1, ListNode l2, int carry) {\n        if (l1 == null && l2 == null && carry == 0) return null;\n        int sum = (l1 != null ? l1.val : 0) + (l2 != null ? l2.val : 0) + carry;\n        ListNode node = new ListNode(sum % 10);\n        node.next = add(l1 != null ? l1.next : null, l2 != null ? l2.next : null, sum / 10);\n        return node;\n    }\n}","Python3":"class Solution:\n    def addTwoNumbers(self, l1: Optional[ListNode], l2: Optional[ListNode]) -> Optional[ListNode]:\n        def add(a: Optional[ListNode], b: Optional[ListNode], carry: int) -> Optional[ListNode]:\n            if not a and not b and carry == 0:\n                return None\n            total = (a.val if a else 0) + (b.val if b else 0) + carry\n            node = ListNode(total % 10)\n            node.next = add(a.next if a else None, b.next if b else None, total // 10)\n            return node\n        return add(l1, l2, 0)","Python":"class Solution(object):\n    def addTwoNumbers(self, l1, l2):\n        def add(a, b, carry):\n            if a is None and b is None and carry == 0:\n                return None\n            total = (a.val if a is not None else 0) + (b.val if b is not None else 0) + carry\n            node = ListNode(total % 10)\n            node.next = add(a.next if a is not None else None, b.next if b is not None else None, total // 10)\n            return node\n        return add(l1, l2, 0)","JavaScript":"function addTwoNumbers(l1, l2) {\n  function add(a, b, carry) {\n    if (!a && !b && carry === 0) return null;\n    const sum = (a ? a.val : 0) + (b ? b.val : 0) + carry;\n    const node = new ListNode(sum % 10);\n    node.next = add(a ? a.next : null, b ? b.next : null, Math.floor(sum / 10));\n    return node;\n  }\n  return add(l1, l2, 0);\n}","TypeScript":"function addTwoNumbers(l1: ListNode | null, l2: ListNode | null): ListNode | null {\n  function add(a: ListNode | null, b: ListNode | null, carry: number): ListNode | null {\n    if (!a && !b && carry === 0) return null;\n    const sum = (a ? a.val : 0) + (b ? b.val : 0) + carry;\n    const node = new ListNode(sum % 10);\n    node.next = add(a ? a.next : null, b ? b.next : null, Math.floor(sum / 10));\n    return node;\n  }\n  return add(l1, l2, 0);\n}","C#":"public class Solution {\n    public ListNode AddTwoNumbers(ListNode l1, ListNode l2) {\n        return Add(l1, l2, 0);\n    }\n    private ListNode Add(ListNode a, ListNode b, int carry) {\n        if (a == null && b == null && carry == 0) return null;\n        int sum = (a != null ? a.val : 0) + (b != null ? b.val : 0) + carry;\n        ListNode node = new ListNode(sum % 10);\n        node.next = Add(a != null ? a.next : null, b != null ? b.next : null, sum / 10);\n        return node;\n    }\n}","PHP":"class Solution {\n    function addTwoNumbers($l1, $l2) {\n        return $this->add($l1, $l2, 0);\n    }\n    private function add($a, $b, $carry) {\n        if ($a === null && $b === null && $carry === 0) return null;\n        $sum = ($a !== null ? $a->val : 0) + ($b !== null ? $b->val : 0) + $carry;\n        $node = new ListNode($sum % 10);\n        $node->next = $this->add($a !== null ? $a->next : null, $b !== null ? $b->next : null, intdiv($sum, 10));\n        return $node;\n    }\n}"}},{"id":"in-place-reuse","name":"In-Place Modification of l1","recommended":false,"coreIdeaSummary":"Overwrite l1's nodes directly, splicing l2 or a new carry node if l1 ends early.","coreIdea":"Update l1 node values in place while walking both lists. Whenever l1 runs out before l2, link l2's remaining chain onto l1 and keep propagating carry.","steps":["Save head = l1 and track prev = null.","Walk while l1 != null || l2 != null: if l1 is null, attach l2 to prev.next and set l1 = l2, l2 = null.","Compute sum = l1.val + (l2 ? l2.val : 0) + carry, store sum % 10 in l1.val, and update carry.","If carry > 0 at the end, append one new ListNode(carry) to prev.next."],"whyItWorks":"Reuses existing list nodes so only at most one new node (for a final carry) is ever allocated.","whenToUse":"Only when mutating the input list l1 is explicitly permitted and minimizing heap allocations is critical.","complexity":{"time":"O(max(m, n))","space":"O(1)","variables":"m = length of l1, n = length of l2","boundType":"Worst-case"},"code":{"Java":"class Solution {\n    public ListNode addTwoNumbers(ListNode l1, ListNode l2) {\n        ListNode head = l1, prev = null;\n        int carry = 0;\n        while (l1 != null || l2 != null) {\n            if (l1 == null) {\n                prev.next = l2;\n                l1 = l2;\n                l2 = null;\n            }\n            int sum = l1.val + (l2 != null ? l2.val : 0) + carry;\n            l1.val = sum % 10;\n            carry = sum / 10;\n            prev = l1;\n            l1 = l1.next;\n            if (l2 != null) l2 = l2.next;\n        }\n        if (carry > 0) prev.next = new ListNode(carry);\n        return head;\n    }\n}","Python3":"class Solution:\n    def addTwoNumbers(self, l1: Optional[ListNode], l2: Optional[ListNode]) -> Optional[ListNode]:\n        head, prev, carry = l1, None, 0\n        while l1 or l2:\n            if l1 is None:\n                prev.next = l2\n                l1 = l2\n                l2 = None\n            total = l1.val + (l2.val if l2 else 0) + carry\n            l1.val = total % 10\n            carry = total // 10\n            prev = l1\n            l1 = l1.next\n            if l2:\n                l2 = l2.next\n        if carry:\n            prev.next = ListNode(carry)\n        return head","Python":"class Solution(object):\n    def addTwoNumbers(self, l1, l2):\n        head, prev, carry = l1, None, 0\n        while l1 is not None or l2 is not None:\n            if l1 is None:\n                prev.next = l2\n                l1 = l2\n                l2 = None\n            total = l1.val + (l2.val if l2 is not None else 0) + carry\n            l1.val = total % 10\n            carry = total // 10\n            prev = l1\n            l1 = l1.next\n            if l2 is not None:\n                l2 = l2.next\n        if carry:\n            prev.next = ListNode(carry)\n        return head","JavaScript":"function addTwoNumbers(l1, l2) {\n  const head = l1;\n  let prev = null;\n  let carry = 0;\n  while (l1 !== null || l2 !== null) {\n    if (l1 === null) {\n      prev.next = l2;\n      l1 = l2;\n      l2 = null;\n    }\n    const sum = l1.val + (l2 ? l2.val : 0) + carry;\n    l1.val = sum % 10;\n    carry = Math.floor(sum / 10);\n    prev = l1;\n    l1 = l1.next;\n    if (l2) l2 = l2.next;\n  }\n  if (carry > 0) prev.next = new ListNode(carry);\n  return head;\n}","TypeScript":"function addTwoNumbers(l1: ListNode | null, l2: ListNode | null): ListNode | null {\n  const head = l1;\n  let prev: ListNode | null = null;\n  let carry = 0;\n  while (l1 !== null || l2 !== null) {\n    if (l1 === null && prev !== null) {\n      prev.next = l2;\n      l1 = l2;\n      l2 = null;\n    }\n    if (!l1) break;\n    const sum = l1.val + (l2 ? l2.val : 0) + carry;\n    l1.val = sum % 10;\n    carry = Math.floor(sum / 10);\n    prev = l1;\n    l1 = l1.next;\n    if (l2) l2 = l2.next;\n  }\n  if (carry > 0 && prev !== null) prev.next = new ListNode(carry);\n  return head;\n}","C#":"public class Solution {\n    public ListNode AddTwoNumbers(ListNode l1, ListNode l2) {\n        ListNode head = l1, prev = null;\n        int carry = 0;\n        while (l1 != null || l2 != null) {\n            if (l1 == null) {\n                prev.next = l2;\n                l1 = l2;\n                l2 = null;\n            }\n            int sum = l1.val + (l2 != null ? l2.val : 0) + carry;\n            l1.val = sum % 10;\n            carry = sum / 10;\n            prev = l1;\n            l1 = l1.next;\n            if (l2 != null) l2 = l2.next;\n        }\n        if (carry > 0) prev.next = new ListNode(carry);\n        return head;\n    }\n}","PHP":"class Solution {\n    function addTwoNumbers($l1, $l2) {\n        $head = $l1; $prev = null; $carry = 0;\n        while ($l1 !== null || $l2 !== null) {\n            if ($l1 === null) {\n                $prev->next = $l2;\n                $l1 = $l2;\n                $l2 = null;\n            }\n            $sum = $l1->val + ($l2 !== null ? $l2->val : 0) + $carry;\n            $l1->val = $sum % 10;\n            $carry = intdiv($sum, 10);\n            $prev = $l1;\n            $l1 = $l1->next;\n            if ($l2 !== null) $l2 = $l2->next;\n        }\n        if ($carry > 0) $prev->next = new ListNode($carry);\n        return $head;\n    }\n}"}}],"tests":[{"name":"Example 1 (325 + 47)","args":[[5,2,3],[7,4]],"expected":[2,7,3]},{"name":"Example 2 (99 + 1)","args":[[9,9],[1]],"expected":[0,0,1]},{"name":"Zeros (0 + 0)","args":[[0],[0]],"expected":[0]},{"name":"Carry chain (999 + 99)","args":[[9,9,9],[9,9]],"expected":[8,9,0,1]}],"javaDriver":"import java.util.*;\nclass ListNode { int val; ListNode next; ListNode(int v){val=v;} }\npublic class Main {\n  static ListNode mk(int[] a){ ListNode d=new ListNode(0),c=d; for(int x:a){c.next=new ListNode(x);c=c.next;} return d.next; }\n  static int[] arr(ListNode n){ List<Integer> l=new ArrayList<>(); while(n!=null){l.add(n.val);n=n.next;} return l.stream().mapToInt(i->i).toArray(); }\n  public static void main(String[] args) {\n    Solution s = new Solution();\n    if (!Arrays.equals(arr(s.addTwoNumbers(mk(new int[]{5,2,3}), mk(new int[]{7,4}))), new int[]{2,7,3})) throw new AssertionError(\"Ex1\");\n    if (!Arrays.equals(arr(s.addTwoNumbers(mk(new int[]{9,9}), mk(new int[]{1}))), new int[]{0,0,1})) throw new AssertionError(\"Ex2\");\n    if (!Arrays.equals(arr(s.addTwoNumbers(mk(new int[]{0}), mk(new int[]{0}))), new int[]{0})) throw new AssertionError(\"Zero\");\n    if (!Arrays.equals(arr(s.addTwoNumbers(mk(new int[]{9,9,9}), mk(new int[]{9,9}))), new int[]{8,9,0,1})) throw new AssertionError(\"Carry\");\n  }\n}","phpDriver":"class ListNode { public $val = 0; public $next = null; function __construct($v = 0, $n = null) { $this->val = $v; $this->next = $n; } }\nfunction mk($a) { $d = new ListNode(0); $c = $d; foreach ($a as $x) { $c->next = new ListNode($x); $c = $c->next; } return $d->next; }\nfunction arr($n) { $o = []; while ($n !== null) { $o[] = $n->val; $n = $n->next; } return $o; }\n$s = new Solution();\nif (arr($s->addTwoNumbers(mk([5,2,3]), mk([7,4]))) !== [2,7,3]) exit(1);\nif (arr($s->addTwoNumbers(mk([9,9]), mk([1]))) !== [0,0,1]) exit(1);\nif (arr($s->addTwoNumbers(mk([0]), mk([0]))) !== [0]) exit(1);\nif (arr($s->addTwoNumbers(mk([9,9,9]), mk([9,9]))) !== [8,9,0,1]) exit(1);","csharpDriver":"using System;\nusing System.Collections.Generic;\npublic class ListNode { public int val; public ListNode next; public ListNode(int v=0, ListNode n=null){val=v;next=n;} }\npublic class Runner {\n  static ListNode Mk(int[] a){ var d=new ListNode(0); var c=d; foreach(int x in a){c.next=new ListNode(x);c=c.next;} return d.next; }\n  static int[] Arr(ListNode n){ var l=new List<int>(); while(n!=null){l.Add(n.val);n=n.next;} return l.ToArray(); }\n  static void Eq(int[] a, int[] b){ if(a.Length!=b.Length) throw new Exception(); for(int i=0;i<a.Length;i++) if(a[i]!=b[i]) throw new Exception(); }\n  public static void Main() {\n    var s = new Solution();\n    Eq(Arr(s.AddTwoNumbers(Mk(new int[]{5,2,3}), Mk(new int[]{7,4}))), new int[]{2,7,3});\n    Eq(Arr(s.AddTwoNumbers(Mk(new int[]{9,9}), Mk(new int[]{1}))), new int[]{0,0,1});\n    Eq(Arr(s.AddTwoNumbers(Mk(new int[]{0}), Mk(new int[]{0}))), new int[]{0});\n    Eq(Arr(s.AddTwoNumbers(Mk(new int[]{9,9,9}), Mk(new int[]{9,9}))), new int[]{8,9,0,1});\n  }\n}"},"data/guides/3-longest-substring-without-repeating-characters.json":{"number":3,"slug":"longest-substring-without-repeating-characters","title":"Longest Substring Without Repeating Characters","difficulty":"Medium","topics":["Hash Table","String","Sliding Window"],"access":"Free","url":"https://leetcode.com/problems/longest-substring-without-repeating-characters/","jsFunctionName":"lengthOfLongestSubstring","pyMethodName":"lengthOfLongestSubstring","verification":{"verifiedLanguages":["Java","Python3","Python","JavaScript","TypeScript","C#","PHP"],"untestedLanguages":[]},"understand":{"question":"Given a text string, what is the length of the longest unbroken stretch of characters in which every character appears at most once?","plainExplanation":"Imagine highlighting a contiguous snippet of letters with a marker. You want your highlight to be as wide as possible, but the moment a character would appear twice inside the highlight, you must shrink the left side past its earlier copy.","inputMeaning":"A string s made of English letters, digits, symbols, or spaces (including an empty string \"\").","outputMeaning":"An integer equal to the maximum length of any valid substring with all unique characters.","rules":["A substring must be contiguous (you cannot delete characters from the middle).","Case matters ('a' and 'A' are different characters), and spaces/symbols count as characters.","An empty string \"\" has a longest unique substring of length 0."],"terms":[{"term":"Substring","definition":"A contiguous slice s[left..right] of consecutive characters from s."},{"term":"Sliding Window","definition":"Two pointers [left, right] that expand right to include new items and advance left only when a rule (here: uniqueness) is broken."},{"term":"Last-Seen Index","definition":"A map storing the most recent position where each character appeared so left can jump past duplicates in one step."}],"example1":{"input":"s = \"cadbzabcd\"","output":"5","whyValid":"The substring \"cadbz\" (indices 0..4) has 5 distinct characters. When index 5 ('a') arrives, 'a' repeats from index 1, so left slides to 2 (\"dbza\"), and later reaches \"zabcd\" (also length 5), so the maximum length is 5.","diagram":{"type":"array","items":[{"index":0,"value":"c","state":"match"},{"index":1,"value":"a","state":"match"},{"index":2,"value":"d","state":"match"},{"index":3,"value":"b","state":"match"},{"index":4,"value":"z","state":"match"},{"index":5,"value":"a","state":"skip"},{"index":6,"value":"b","state":"default"},{"index":7,"value":"c","state":"default"},{"index":8,"value":"d","state":"default"}],"pointers":[{"index":0,"name":"L"},{"index":4,"name":"R"}],"caption":"Window \"cadbz\" (indices 0..4) has 5 all-unique characters."}},"example2":{"input":"s = \"abba\"","output":"2","whyEdgeCase":"Trap for naive index jumps! When right reaches the second 'a' at index 3, the old 'a' was at index 0, which is ALREADY behind left = 2. Never move left backwards: always use left = max(left, lastSeen[ch] + 1)."}},"dryRun":{"approachId":"sliding-window-map","algorithmName":"Sliding Window with Last-Seen Map","steps":[{"title":"Indices 0..4: expand across unique letters 'c','a','d','b','z'","description":"None of c, a, d, b, z is in our active window [0..4]. Record each index in lastSeen and update maxLen = 5.","state":{"type":"hash","items":[{"index":0,"value":"c","state":"match"},{"index":1,"value":"a","state":"match"},{"index":2,"value":"d","state":"match"},{"index":3,"value":"b","state":"match"},{"index":4,"value":"z","state":"match"},{"index":5,"value":"a","state":"default"},{"index":6,"value":"b","state":"default"},{"index":7,"value":"c","state":"default"},{"index":8,"value":"d","state":"default"}],"pointers":[{"index":0,"name":"L"},{"index":4,"name":"R"}],"aux":{"title":"Window & Last-Seen Map","entries":[{"key":"maxLen","value":5,"highlight":true},{"key":"c:0, a:1, d:2, b:3, z:4","value":""}]},"caption":"Window length = 4 - 0 + 1 = 5."}},{"title":"Index 5 ('a'): duplicate inside window -> jump L to 2","description":"lastSeen['a'] is 1 (>= L = 0). Move L to 1 + 1 = 2 so the old 'a' leaves the window. Update lastSeen['a'] = 5. Window is \"dbza\" (length 4).","state":{"type":"hash","items":[{"index":0,"value":"c","state":"skip"},{"index":1,"value":"a","state":"skip"},{"index":2,"value":"d","state":"window"},{"index":3,"value":"b","state":"window"},{"index":4,"value":"z","state":"window"},{"index":5,"value":"a","state":"active"},{"index":6,"value":"b","state":"default"},{"index":7,"value":"c","state":"default"},{"index":8,"value":"d","state":"default"}],"pointers":[{"index":2,"name":"L"},{"index":5,"name":"R"}],"aux":{"title":"Window & Last-Seen Map","entries":[{"key":"maxLen","value":5},{"key":"a","value":"updated -> 5","highlight":true}]},"caption":"Window [2..5] = \"dbza\", length 4."}},{"title":"Indices 6..8 ('b', 'c', 'd'): slide past 'b', ignore stale 'c', 'd'","description":"At R=6 ('b'), lastSeen['b']=3 >= L=2 so L jumps to 4. At R=7 ('c') and R=8 ('d'), their old indices (0 and 2) are < L=4 so L stays at 4! Window \"zabcd\" reaches length 5. Return 5.","state":{"type":"hash","items":[{"index":0,"value":"c","state":"skip"},{"index":1,"value":"a","state":"skip"},{"index":2,"value":"d","state":"skip"},{"index":3,"value":"b","state":"skip"},{"index":4,"value":"z","state":"match"},{"index":5,"value":"a","state":"match"},{"index":6,"value":"b","state":"match"},{"index":7,"value":"c","state":"match"},{"index":8,"value":"d","state":"match"}],"pointers":[{"index":4,"name":"L"},{"index":8,"name":"R"}],"aux":{"title":"Final Result","entries":[{"key":"maxLen","value":5,"highlight":true}]},"caption":"Window [4..8] = \"zabcd\" also has length 5. Final answer: 5."}}]},"approaches":[{"id":"brute-force","name":"Brute Force with Character Set","recommended":false,"coreIdeaSummary":"Start from each index i and extend right until a repeat occurs.","coreIdea":"For every starting index i, grow the substring rightwards using a set until encountering a repeated character.","steps":["Initialize best = 0.","For each start index i, create an empty seen set.","Loop j from i to n - 1: if s[j] is in seen, break; else insert s[j] and update best."],"whyItWorks":"Checking every possible start index and stopping on the first duplicate examines every valid unique substring.","whenToUse":"Only for tiny strings or baseline verification.","complexity":{"time":"O(n * min(n, sigma))","space":"O(min(n, sigma))","variables":"n = string length, sigma = character alphabet size","boundType":"Worst-case"},"code":{"Java":"import java.util.HashSet;\nimport java.util.Set;\n\nclass Solution {\n    public int lengthOfLongestSubstring(String s) {\n        int best = 0;\n        for (int i = 0; i < s.length(); i++) {\n            Set<Character> seen = new HashSet<>();\n            for (int j = i; j < s.length(); j++) {\n                if (!seen.add(s.charAt(j))) break;\n                best = Math.max(best, j - i + 1);\n            }\n        }\n        return best;\n    }\n}","Python3":"class Solution:\n    def lengthOfLongestSubstring(self, s: str) -> int:\n        best = 0\n        n = len(s)\n        for i in range(n):\n            seen = set()\n            for j in range(i, n):\n                if s[j] in seen:\n                    break\n                seen.add(s[j])\n                best = max(best, j - i + 1)\n        return best","Python":"class Solution(object):\n    def lengthOfLongestSubstring(self, s):\n        best = 0\n        n = len(s)\n        for i in range(n):\n            seen = set()\n            for j in range(i, n):\n                if s[j] in seen:\n                    break\n                seen.add(s[j])\n                if j - i + 1 > best:\n                    best = j - i + 1\n        return best","JavaScript":"function lengthOfLongestSubstring(s) {\n  let best = 0;\n  for (let i = 0; i < s.length; i++) {\n    const seen = new Set();\n    for (let j = i; j < s.length; j++) {\n      if (seen.has(s[j])) break;\n      seen.add(s[j]);\n      best = Math.max(best, j - i + 1);\n    }\n  }\n  return best;\n}","TypeScript":"function lengthOfLongestSubstring(s: string): number {\n  let best = 0;\n  for (let i = 0; i < s.length; i++) {\n    const seen = new Set<string>();\n    for (let j = i; j < s.length; j++) {\n      if (seen.has(s[j])) break;\n      seen.add(s[j]);\n      best = Math.max(best, j - i + 1);\n    }\n  }\n  return best;\n}","C#":"using System;\nusing System.Collections.Generic;\n\npublic class Solution {\n    public int LengthOfLongestSubstring(string s) {\n        int best = 0;\n        for (int i = 0; i < s.Length; i++) {\n            var seen = new HashSet<char>();\n            for (int j = i; j < s.Length; j++) {\n                if (!seen.Add(s[j])) break;\n                best = Math.Max(best, j - i + 1);\n            }\n        }\n        return best;\n    }\n}","PHP":"class Solution {\n    function lengthOfLongestSubstring($s) {\n        $best = 0; $n = strlen($s);\n        for ($i = 0; $i < $n; $i++) {\n            $seen = [];\n            for ($j = $i; $j < $n; $j++) {\n                $ch = $s[$j];\n                if (isset($seen[$ch])) break;\n                $seen[$ch] = true;\n                $best = max($best, $j - $i + 1);\n            }\n        }\n        return $best;\n    }\n}"}},{"id":"sliding-window-set","name":"Sliding Window with Active Set","recommended":false,"coreIdeaSummary":"Shrink left one step at a time while s[right] is in the active set.","coreIdea":"Maintain a set of characters inside [left..right]. Before adding s[right], advance left and remove s[left] until s[right] is no longer present.","steps":["Initialize left = 0, best = 0, and an empty set active.","For right from 0 to n - 1: while s[right] is in active, remove s[left] and increment left.","Add s[right] to active and update best = max(best, right - left + 1)."],"whyItWorks":"Each character is inserted once and removed at most once, so left and right together make at most 2n moves.","whenToUse":"Easy-to-adapt template for sliding window problems with frequency constraints.","complexity":{"time":"O(n)","space":"O(min(n, sigma))","variables":"n = string length, sigma = alphabet size","boundType":"Expected (hash set)"},"code":{"Java":"import java.util.HashSet;\nimport java.util.Set;\n\nclass Solution {\n    public int lengthOfLongestSubstring(String s) {\n        Set<Character> active = new HashSet<>();\n        int left = 0, best = 0;\n        for (int right = 0; right < s.length(); right++) {\n            char c = s.charAt(right);\n            while (active.contains(c)) {\n                active.remove(s.charAt(left++));\n            }\n            active.add(c);\n            best = Math.max(best, right - left + 1);\n        }\n        return best;\n    }\n}","Python3":"class Solution:\n    def lengthOfLongestSubstring(self, s: str) -> int:\n        active = set()\n        left = 0\n        best = 0\n        for right, ch in enumerate(s):\n            while ch in active:\n                active.remove(s[left])\n                left += 1\n            active.add(ch)\n            best = max(best, right - left + 1)\n        return best","Python":"class Solution(object):\n    def lengthOfLongestSubstring(self, s):\n        active = set()\n        left = 0\n        best = 0\n        for right, ch in enumerate(s):\n            while ch in active:\n                active.remove(s[left])\n                left += 1\n            active.add(ch)\n            if right - left + 1 > best:\n                best = right - left + 1\n        return best","JavaScript":"function lengthOfLongestSubstring(s) {\n  const active = new Set();\n  let left = 0, best = 0;\n  for (let right = 0; right < s.length; right++) {\n    const c = s[right];\n    while (active.has(c)) {\n      active.delete(s[left++]);\n    }\n    active.add(c);\n    best = Math.max(best, right - left + 1);\n  }\n  return best;\n}","TypeScript":"function lengthOfLongestSubstring(s: string): number {\n  const active = new Set<string>();\n  let left = 0, best = 0;\n  for (let right = 0; right < s.length; right++) {\n    const c = s[right];\n    while (active.has(c)) {\n      active.delete(s[left++]);\n    }\n    active.add(c);\n    best = Math.max(best, right - left + 1);\n  }\n  return best;\n}","C#":"using System;\nusing System.Collections.Generic;\n\npublic class Solution {\n    public int LengthOfLongestSubstring(string s) {\n        var active = new HashSet<char>();\n        int left = 0, best = 0;\n        for (int right = 0; right < s.Length; right++) {\n            char c = s[right];\n            while (active.Contains(c)) {\n                active.Remove(s[left++]);\n            }\n            active.Add(c);\n            best = Math.Max(best, right - left + 1);\n        }\n        return best;\n    }\n}","PHP":"class Solution {\n    function lengthOfLongestSubstring($s) {\n        $active = [];\n        $left = 0; $best = 0; $n = strlen($s);\n        for ($right = 0; $right < $n; $right++) {\n            $c = $s[$right];\n            while (isset($active[$c])) {\n                unset($active[$s[$left]]);\n                $left++;\n            }\n            $active[$c] = true;\n            $best = max($best, $right - $left + 1);\n        }\n        return $best;\n    }\n}"}},{"id":"sliding-window-map","name":"Sliding Window with Last-Seen Map","recommended":true,"recommendedTradeOff":"Visits each index strictly once by jumping left directly past the previous occurrence instead of deleting elements step by step.","coreIdeaSummary":"Store each character's latest index and jump left = max(left, lastSeen[ch] + 1).","coreIdea":"Track the last index where every character appeared. When s[right] was seen at prev >= left, move left directly to prev + 1.","steps":["Initialize map lastSeen = {}, left = 0, best = 0.","For each right from 0 to n - 1: if s[right] is in lastSeen and lastSeen[s[right]] >= left, set left = lastSeen[s[right]] + 1.","Store lastSeen[s[right]] = right and update best = max(best, right - left + 1)."],"whyItWorks":"Taking max(left, prev + 1) keeps left monotonic so stale characters from before the current window are safely ignored without removing them.","whenToUse":"Default optimal solution for general Unicode or ASCII strings.","complexity":{"time":"O(n)","space":"O(min(n, sigma))","variables":"n = string length, sigma = alphabet size","boundType":"Expected (hash map)"},"code":{"Java":"import java.util.HashMap;\nimport java.util.Map;\n\nclass Solution {\n    public int lengthOfLongestSubstring(String s) {\n        Map<Character, Integer> lastSeen = new HashMap<>();\n        int left = 0, best = 0;\n        for (int right = 0; right < s.length(); right++) {\n            char c = s.charAt(right);\n            Integer prev = lastSeen.get(c);\n            if (prev != null && prev >= left) {\n                left = prev + 1;\n            }\n            lastSeen.put(c, right);\n            best = Math.max(best, right - left + 1);\n        }\n        return best;\n    }\n}","Python3":"class Solution:\n    def lengthOfLongestSubstring(self, s: str) -> int:\n        last_seen: Dict[str, int] = {}\n        left = 0\n        best = 0\n        for right, ch in enumerate(s):\n            if ch in last_seen and last_seen[ch] >= left:\n                left = last_seen[ch] + 1\n            last_seen[ch] = right\n            best = max(best, right - left + 1)\n        return best","Python":"class Solution(object):\n    def lengthOfLongestSubstring(self, s):\n        last_seen = {}\n        left = 0\n        best = 0\n        for right, ch in enumerate(s):\n            if ch in last_seen and last_seen[ch] >= left:\n                left = last_seen[ch] + 1\n            last_seen[ch] = right\n            if right - left + 1 > best:\n                best = right - left + 1\n        return best","JavaScript":"function lengthOfLongestSubstring(s) {\n  const lastSeen = new Map();\n  let left = 0, best = 0;\n  for (let right = 0; right < s.length; right++) {\n    const c = s[right];\n    const prev = lastSeen.get(c);\n    if (prev !== undefined && prev >= left) {\n      left = prev + 1;\n    }\n    lastSeen.set(c, right);\n    best = Math.max(best, right - left + 1);\n  }\n  return best;\n}","TypeScript":"function lengthOfLongestSubstring(s: string): number {\n  const lastSeen = new Map<string, number>();\n  let left = 0, best = 0;\n  for (let right = 0; right < s.length; right++) {\n    const c = s[right];\n    const prev = lastSeen.get(c);\n    if (prev !== undefined && prev >= left) {\n      left = prev + 1;\n    }\n    lastSeen.set(c, right);\n    best = Math.max(best, right - left + 1);\n  }\n  return best;\n}","C#":"using System;\nusing System.Collections.Generic;\n\npublic class Solution {\n    public int LengthOfLongestSubstring(string s) {\n        var lastSeen = new Dictionary<char, int>();\n        int left = 0, best = 0;\n        for (int right = 0; right < s.Length; right++) {\n            char c = s[right];\n            int prev;\n            if (lastSeen.TryGetValue(c, out prev) && prev >= left) {\n                left = prev + 1;\n            }\n            lastSeen[c] = right;\n            best = Math.Max(best, right - left + 1);\n        }\n        return best;\n    }\n}","PHP":"class Solution {\n    function lengthOfLongestSubstring($s) {\n        $lastSeen = [];\n        $left = 0; $best = 0; $n = strlen($s);\n        for ($right = 0; $right < $n; $right++) {\n            $c = $s[$right];\n            if (isset($lastSeen[$c]) && $lastSeen[$c] >= $left) {\n                $left = $lastSeen[$c] + 1;\n            }\n            $lastSeen[$c] = $right;\n            $best = max($best, $right - $left + 1);\n        }\n        return $best;\n    }\n}"}},{"id":"ascii-table","name":"Fixed 128-Slot ASCII Array","recommended":false,"coreIdeaSummary":"Replace the hash map with a 128-element integer array for ASCII inputs.","coreIdea":"For standard ASCII strings, use a fixed int[128] array initialized to -1 to achieve worst-case O(1) lookup without hashing.","steps":["Initialize int[128] lastSeen filled with -1, left = 0, best = 0.","For each character code code = ord(s[right]), set left = max(left, lastSeen[code] + 1).","Set lastSeen[code] = right and update best = max(best, right - left + 1)."],"whyItWorks":"Since ASCII codes fall in 0..127, direct array indexing avoids hash collisions and dynamic allocation.","whenToUse":"When inputs are guaranteed to be ASCII and strict worst-case O(n) time / O(1) fixed table space is desired.","complexity":{"time":"O(n)","space":"O(1) (fixed 128-entry table for ASCII)","variables":"n = string length","boundType":"Worst-case"},"code":{"Java":"import java.util.Arrays;\n\nclass Solution {\n    public int lengthOfLongestSubstring(String s) {\n        int[] last = new int[128];\n        Arrays.fill(last, -1);\n        int left = 0, best = 0;\n        for (int right = 0; right < s.length(); right++) {\n            int code = s.charAt(right);\n            if (last[code] >= left) left = last[code] + 1;\n            last[code] = right;\n            best = Math.max(best, right - left + 1);\n        }\n        return best;\n    }\n}","Python3":"class Solution:\n    def lengthOfLongestSubstring(self, s: str) -> int:\n        last = [-1] * 128\n        left = 0\n        best = 0\n        for right, ch in enumerate(s):\n            code = ord(ch)\n            if last[code] >= left:\n                left = last[code] + 1\n            last[code] = right\n            best = max(best, right - left + 1)\n        return best","Python":"class Solution(object):\n    def lengthOfLongestSubstring(self, s):\n        last = [-1] * 128\n        left = 0\n        best = 0\n        for right, ch in enumerate(s):\n            code = ord(ch)\n            if last[code] >= left:\n                left = last[code] + 1\n            last[code] = right\n            if right - left + 1 > best:\n                best = right - left + 1\n        return best","JavaScript":"function lengthOfLongestSubstring(s) {\n  const last = new Int32Array(128).fill(-1);\n  let left = 0, best = 0;\n  for (let right = 0; right < s.length; right++) {\n    const code = s.charCodeAt(right);\n    if (last[code] >= left) left = last[code] + 1;\n    last[code] = right;\n    best = Math.max(best, right - left + 1);\n  }\n  return best;\n}","TypeScript":"function lengthOfLongestSubstring(s: string): number {\n  const last = new Int32Array(128).fill(-1);\n  let left = 0, best = 0;\n  for (let right = 0; right < s.length; right++) {\n    const code = s.charCodeAt(right);\n    if (last[code] >= left) left = last[code] + 1;\n    last[code] = right;\n    best = Math.max(best, right - left + 1);\n  }\n  return best;\n}","C#":"using System;\n\npublic class Solution {\n    public int LengthOfLongestSubstring(string s) {\n        int[] last = new int[128];\n        for (int i = 0; i < 128; i++) last[i] = -1;\n        int left = 0, best = 0;\n        for (int right = 0; right < s.Length; right++) {\n            int code = s[right];\n            if (last[code] >= left) left = last[code] + 1;\n            last[code] = right;\n            best = Math.Max(best, right - left + 1);\n        }\n        return best;\n    }\n}","PHP":"class Solution {\n    function lengthOfLongestSubstring($s) {\n        $last = array_fill(0, 128, -1);\n        $left = 0; $best = 0; $n = strlen($s);\n        for ($right = 0; $right < $n; $right++) {\n            $code = ord($s[$right]);\n            if ($last[$code] >= $left) $left = $last[$code] + 1;\n            $last[$code] = $right;\n            $best = max($best, $right - $left + 1);\n        }\n        return $best;\n    }\n}"}}],"tests":[{"name":"Example 1","args":["cadbzabcd"],"expected":5},{"name":"Example 2 (abba trap)","args":["abba"],"expected":2},{"name":"Empty string","args":[""],"expected":0},{"name":"All identical","args":["zzzzz"],"expected":1}],"javaDriver":"public class Main {\n  public static void main(String[] args) {\n    Solution s = new Solution();\n    if (s.lengthOfLongestSubstring(\"cadbzabcd\") != 5) throw new AssertionError(\"Ex1\");\n    if (s.lengthOfLongestSubstring(\"abba\") != 2) throw new AssertionError(\"Ex2\");\n    if (s.lengthOfLongestSubstring(\"\") != 0) throw new AssertionError(\"Empty\");\n    if (s.lengthOfLongestSubstring(\"zzzzz\") != 1) throw new AssertionError(\"Same\");\n  }\n}","phpDriver":"$s = new Solution();\nif ($s->lengthOfLongestSubstring(\"cadbzabcd\") !== 5) exit(1);\nif ($s->lengthOfLongestSubstring(\"abba\") !== 2) exit(1);\nif ($s->lengthOfLongestSubstring(\"\") !== 0) exit(1);\nif ($s->lengthOfLongestSubstring(\"zzzzz\") !== 1) exit(1);","csharpDriver":"using System;\npublic class Runner {\n  public static void Main() {\n    var s = new Solution();\n    if (s.LengthOfLongestSubstring(\"cadbzabcd\") != 5) throw new Exception(\"Ex1\");\n    if (s.LengthOfLongestSubstring(\"abba\") != 2) throw new Exception(\"Ex2\");\n    if (s.LengthOfLongestSubstring(\"\") != 0) throw new Exception(\"Empty\");\n    if (s.LengthOfLongestSubstring(\"zzzzz\") != 1) throw new Exception(\"Same\");\n  }\n}"},"data/guides/4-median-of-two-sorted-arrays.json":{"number":4,"slug":"median-of-two-sorted-arrays","title":"Median of Two Sorted Arrays","difficulty":"Hard","topics":["Array","Binary Search","Divide and Conquer"],"access":"Free","url":"https://leetcode.com/problems/median-of-two-sorted-arrays/","jsFunctionName":"findMedianSortedArrays","pyMethodName":"findMedianSortedArrays","verification":{"verifiedLanguages":["Java","Python3","Python","JavaScript","TypeScript","C#","PHP"],"untestedLanguages":[]},"understand":{"question":"Given two already-sorted integer arrays, what would the middle value (median) be if they were combined into one sorted list, without actually building that giant list in slow time?","plainExplanation":"Imagine two sorted stacks of test scores. If you poured them into one combined sorted pile, the median splits the pile into two equal-sized halves: every score in the left half is <= every score in the right half.","inputMeaning":"Two sorted integer arrays nums1 (length m) and nums2 (length n), where at least one array is non-empty.","outputMeaning":"A floating-point number: the middle element if m + n is odd, or the average of the two middle elements if m + n is even.","rules":["Both input arrays are already sorted in non-decreasing order.","Total length N = m + n determines whether there is 1 center value (odd N) or 2 center values averaged together (even N).","Target optimal time complexity is O(log(min(m, n)))."],"terms":[{"term":"Median","definition":"The value(s) dividing a sorted dataset into equal lower and upper halves."},{"term":"Partition","definition":"Choosing a cut point i in nums1 and j in nums2 so the left side holds half of all elements: i + j = Math.floor((m + n + 1) / 2)."},{"term":"Sentinel (-Infinity / +Infinity)","definition":"Placeholder boundary values used when a cut sits at the very start (0 elements on left) or very end (0 elements on right) of an array."}],"example1":{"input":"nums1 = [2, 8], nums2 = [1, 4, 9]","output":"4.0","whyValid":"Merged sorted order is [1, 2, 4, 8, 9] (length 5, odd). Cutting nums1 at i = 1 ([2] | [8]) and nums2 at j = 2 ([1, 4] | [9]) puts 3 elements on the left (1, 2, 4) and 2 on the right (8, 9). Max on left = max(2, 4) = 4, which is the median.","diagram":{"type":"array","items":[{"index":0,"value":1,"state":"window","label":"left half"},{"index":1,"value":2,"state":"window","label":"left half"},{"index":2,"value":4,"state":"match","label":"median"},{"index":3,"value":8,"state":"default","label":"right half"},{"index":4,"value":9,"state":"default","label":"right half"}],"pointers":[{"index":2,"name":"mid"}],"caption":"Combined sorted view [1, 2, 4, 8, 9] has median 4.0."}},"example2":{"input":"nums1 = [], nums2 = [3, 5]","output":"4.0","whyEdgeCase":"One array is completely empty and total length is even (2). The cut in nums1 is i = 0, so sentinels -Infinity/+Infinity prevent out-of-bounds reads, and the median averages (3 + 5) / 2 = 4.0."}},"dryRun":{"approachId":"binary-search-partition","algorithmName":"Binary Search Partition on Shorter Array","steps":[{"title":"Binary-search cut i in shorter array nums1 = [2, 8]","description":"Ensure nums1 is shorter (m=2, n=3). Half-size = (2 + 3 + 1) // 2 = 3. Search i in [0..2], starting at mid i = 1 -> j = 3 - 1 = 2.","state":{"type":"array","items":[{"index":0,"value":2,"state":"active","label":"A_left"},{"index":1,"value":8,"state":"default","label":"A_right"}],"pointers":[{"index":1,"name":"cut i=1"}],"aux":{"title":"Partition Check (i=1, j=2)","entries":[{"key":"A_left","value":2},{"key":"A_right","value":8},{"key":"B_left","value":4},{"key":"B_right","value":9}]},"caption":"Check cross inequalities: A_left <= B_right and B_left <= A_right."}},{"title":"Cross-check succeeds: 2 <= 9 and 4 <= 8","description":"Both inequalities hold! Because m + n = 5 is odd, the median is max(A_left, B_left) = max(2, 4) = 4.0.","state":{"type":"array","items":[{"index":0,"value":2,"state":"window","label":"A_left=2"},{"index":1,"value":8,"state":"default","label":"A_right=8"}],"pointers":[{"index":1,"name":"valid cut"}],"aux":{"title":"Median Calculation (odd total)","entries":[{"key":"max(A_left, B_left)","value":"max(2, 4) = 4.0","highlight":true}]},"caption":"Valid partition found in 1 binary-search probe -> return 4.0."}}]},"approaches":[{"id":"merge-array","name":"Merge Both Sorted Arrays","recommended":false,"coreIdeaSummary":"Merge nums1 and nums2 into a combined array, then pick the middle.","coreIdea":"Use the standard two-pointer merge step from Merge Sort to create a single sorted array of length m + n, then read the median index(es).","steps":["Allocate merged array of size m + n.","Merge nums1 and nums2 with two pointers.","If total is odd return merged[total / 2]; else return (merged[total/2 - 1] + merged[total/2]) / 2.0."],"whyItWorks":"Merging two sorted lists preserves sorted order across all elements.","whenToUse":"Simple baseline when O(m + n) time and space are fine.","complexity":{"time":"O(m + n)","space":"O(m + n)","variables":"m = len(nums1), n = len(nums2)","boundType":"Worst-case"},"code":{"Java":"class Solution {\n    public double findMedianSortedArrays(int[] nums1, int[] nums2) {\n        int m = nums1.length, n = nums2.length, total = m + n;\n        int[] merged = new int[total];\n        int i = 0, j = 0, k = 0;\n        while (i < m && j < n) merged[k++] = (nums1[i] <= nums2[j]) ? nums1[i++] : nums2[j++];\n        while (i < m) merged[k++] = nums1[i++];\n        while (j < n) merged[k++] = nums2[j++];\n        if (total % 2 == 1) return merged[total / 2];\n        return (merged[total / 2 - 1] + merged[total / 2]) / 2.0;\n    }\n}","Python3":"class Solution:\n    def findMedianSortedArrays(self, nums1: List[int], nums2: List[int]) -> float:\n        merged = []\n        i = j = 0\n        while i < len(nums1) and j < len(nums2):\n            if nums1[i] <= nums2[j]:\n                merged.append(nums1[i]); i += 1\n            else:\n                merged.append(nums2[j]); j += 1\n        merged.extend(nums1[i:])\n        merged.extend(nums2[j:])\n        total = len(merged)\n        if total % 2 == 1:\n            return float(merged[total // 2])\n        return (merged[total // 2 - 1] + merged[total // 2]) / 2.0","Python":"class Solution(object):\n    def findMedianSortedArrays(self, nums1, nums2):\n        merged = []\n        i = j = 0\n        while i < len(nums1) and j < len(nums2):\n            if nums1[i] <= nums2[j]:\n                merged.append(nums1[i]); i += 1\n            else:\n                merged.append(nums2[j]); j += 1\n        merged.extend(nums1[i:])\n        merged.extend(nums2[j:])\n        total = len(merged)\n        if total % 2 == 1:\n            return float(merged[total // 2])\n        return (merged[total // 2 - 1] + merged[total // 2]) / 2.0","JavaScript":"function findMedianSortedArrays(nums1, nums2) {\n  const merged = [];\n  let i = 0, j = 0;\n  while (i < nums1.length && j < nums2.length) {\n    merged.push(nums1[i] <= nums2[j] ? nums1[i++] : nums2[j++]);\n  }\n  while (i < nums1.length) merged.push(nums1[i++]);\n  while (j < nums2.length) merged.push(nums2[j++]);\n  const total = merged.length;\n  const mid = Math.floor(total / 2);\n  return total % 2 === 1 ? merged[mid] : (merged[mid - 1] + merged[mid]) / 2;\n}","TypeScript":"function findMedianSortedArrays(nums1: number[], nums2: number[]): number {\n  const merged: number[] = [];\n  let i = 0, j = 0;\n  while (i < nums1.length && j < nums2.length) {\n    merged.push(nums1[i] <= nums2[j] ? nums1[i++] : nums2[j++]);\n  }\n  while (i < nums1.length) merged.push(nums1[i++]);\n  while (j < nums2.length) merged.push(nums2[j++]);\n  const total = merged.length;\n  const mid = Math.floor(total / 2);\n  return total % 2 === 1 ? merged[mid] : (merged[mid - 1] + merged[mid]) / 2;\n}","C#":"public class Solution {\n    public double FindMedianSortedArrays(int[] nums1, int[] nums2) {\n        int m = nums1.Length, n = nums2.Length, total = m + n;\n        int[] merged = new int[total];\n        int i = 0, j = 0, k = 0;\n        while (i < m && j < n) merged[k++] = nums1[i] <= nums2[j] ? nums1[i++] : nums2[j++];\n        while (i < m) merged[k++] = nums1[i++];\n        while (j < n) merged[k++] = nums2[j++];\n        if (total % 2 == 1) return merged[total / 2];\n        return (merged[total / 2 - 1] + merged[total / 2]) / 2.0;\n    }\n}","PHP":"class Solution {\n    function findMedianSortedArrays($nums1, $nums2) {\n        $merged = []; $i = 0; $j = 0; $m = count($nums1); $n = count($nums2);\n        while ($i < $m && $j < $n) $merged[] = ($nums1[$i] <= $nums2[$j]) ? $nums1[$i++] : $nums2[$j++];\n        while ($i < $m) $merged[] = $nums1[$i++];\n        while ($j < $n) $merged[] = $nums2[$j++];\n        $total = count($merged); $mid = intdiv($total, 2);\n        return ($total % 2 === 1) ? (float)$merged[$mid] : ($merged[$mid - 1] + $merged[$mid]) / 2.0;\n    }\n}"}},{"id":"two-pointer-count","name":"Two-Pointer Simulation (O(1) Space)","recommended":false,"coreIdeaSummary":"Advance two pointers (m + n) / 2 steps tracking only the last two values.","coreIdea":"Walk through the virtual merged sequence without storing it, retaining only prev and curr until reaching index (m + n) / 2.","steps":["Set total = m + n and targetSteps = floor(total / 2) + 1.","Repeat targetSteps times: shift prev = curr, pick smaller head from nums1[i] or nums2[j] into curr.","Return curr if total is odd, else (prev + curr) / 2.0."],"whyItWorks":"Median only depends on the 1 or 2 values at the midpoint, so earlier merged values do not need to be retained.","whenToUse":"When O(1) space is wanted and O(m + n) time is acceptable.","complexity":{"time":"O(m + n)","space":"O(1)","variables":"m = len(nums1), n = len(nums2)","boundType":"Worst-case"},"code":{"Java":"class Solution {\n    public double findMedianSortedArrays(int[] nums1, int[] nums2) {\n        int m = nums1.length, n = nums2.length, total = m + n;\n        int i = 0, j = 0, prev = 0, curr = 0;\n        for (int step = 0; step <= total / 2; step++) {\n            prev = curr;\n            if (i < m && (j >= n || nums1[i] <= nums2[j])) curr = nums1[i++];\n            else curr = nums2[j++];\n        }\n        return (total % 2 == 1) ? curr : (prev + curr) / 2.0;\n    }\n}","Python3":"class Solution:\n    def findMedianSortedArrays(self, nums1: List[int], nums2: List[int]) -> float:\n        m, n = len(nums1), len(nums2)\n        total = m + n\n        i = j = prev = curr = 0\n        for _ in range(total // 2 + 1):\n            prev = curr\n            if i < m and (j >= n or nums1[i] <= nums2[j]):\n                curr = nums1[i]; i += 1\n            else:\n                curr = nums2[j]; j += 1\n        return float(curr) if total % 2 == 1 else (prev + curr) / 2.0","Python":"class Solution(object):\n    def findMedianSortedArrays(self, nums1, nums2):\n        m, n = len(nums1), len(nums2)\n        total = m + n\n        i = j = prev = curr = 0\n        for _ in range(total // 2 + 1):\n            prev = curr\n            if i < m and (j >= n or nums1[i] <= nums2[j]):\n                curr = nums1[i]; i += 1\n            else:\n                curr = nums2[j]; j += 1\n        return float(curr) if total % 2 == 1 else (prev + curr) / 2.0","JavaScript":"function findMedianSortedArrays(nums1, nums2) {\n  const m = nums1.length, n = nums2.length, total = m + n;\n  let i = 0, j = 0, prev = 0, curr = 0;\n  for (let step = 0; step <= Math.floor(total / 2); step++) {\n    prev = curr;\n    if (i < m && (j >= n || nums1[i] <= nums2[j])) curr = nums1[i++];\n    else curr = nums2[j++];\n  }\n  return total % 2 === 1 ? curr : (prev + curr) / 2;\n}","TypeScript":"function findMedianSortedArrays(nums1: number[], nums2: number[]): number {\n  const m = nums1.length, n = nums2.length, total = m + n;\n  let i = 0, j = 0, prev = 0, curr = 0;\n  for (let step = 0; step <= Math.floor(total / 2); step++) {\n    prev = curr;\n    if (i < m && (j >= n || nums1[i] <= nums2[j])) curr = nums1[i++];\n    else curr = nums2[j++];\n  }\n  return total % 2 === 1 ? curr : (prev + curr) / 2;\n}","C#":"public class Solution {\n    public double FindMedianSortedArrays(int[] nums1, int[] nums2) {\n        int m = nums1.Length, n = nums2.Length, total = m + n;\n        int i = 0, j = 0, prev = 0, curr = 0;\n        for (int step = 0; step <= total / 2; step++) {\n            prev = curr;\n            if (i < m && (j >= n || nums1[i] <= nums2[j])) curr = nums1[i++];\n            else curr = nums2[j++];\n        }\n        return (total % 2 == 1) ? curr : (prev + curr) / 2.0;\n    }\n}","PHP":"class Solution {\n    function findMedianSortedArrays($nums1, $nums2) {\n        $m = count($nums1); $n = count($nums2); $total = $m + $n;\n        $i = 0; $j = 0; $prev = 0; $curr = 0;\n        for ($step = 0; $step <= intdiv($total, 2); $step++) {\n            $prev = $curr;\n            if ($i < $m && ($j >= $n || $nums1[$i] <= $nums2[$j])) $curr = $nums1[$i++];\n            else $curr = $nums2[$j++];\n        }\n        return ($total % 2 === 1) ? (float)$curr : ($prev + $curr) / 2.0;\n    }\n}"}},{"id":"binary-search-partition","name":"Binary Search Partition on Shorter Array","recommended":true,"recommendedTradeOff":"Achieves optimal O(log(min(m, n))) time and O(1) space by binary-searching the split index on the shorter array.","coreIdeaSummary":"Binary-search cut i on the shorter array so left-half max <= right-half min.","coreIdea":"Always binary-search on the shorter array A so j = half - i stays in bounds for B. Adjust i until A_left <= B_right and B_left <= A_right.","steps":["If len(nums1) > len(nums2), swap them so nums1 has smaller length m.","Set half = floor((m + n + 1) / 2), lo = 0, hi = m.","Pick i = floor((lo + hi) / 2), j = half - i, and read boundary values using -Infinity/+Infinity sentinels.","If A_left <= B_right and B_left <= A_right, compute median from max(A_left, B_left) and min(A_right, B_right). Otherwise shift hi = i - 1 (when A_left > B_right) or lo = i + 1."],"whyItWorks":"Since both arrays are sorted, A_left <= A_right and B_left <= B_right already hold. Checking only the two cross inequalities ensures every element in the combined left half is <= every element in the combined right half.","whenToUse":"Default optimal solution meeting the O(log(m + n)) constraint.","complexity":{"time":"O(log(min(m, n)))","space":"O(1)","variables":"m = len(nums1), n = len(nums2)","boundType":"Worst-case"},"code":{"Java":"class Solution {\n    public double findMedianSortedArrays(int[] nums1, int[] nums2) {\n        if (nums1.length > nums2.length) return findMedianSortedArrays(nums2, nums1);\n        int m = nums1.length, n = nums2.length;\n        int half = (m + n + 1) / 2, lo = 0, hi = m;\n        while (lo <= hi) {\n            int i = (lo + hi) / 2;\n            int j = half - i;\n            int aLeft = (i > 0) ? nums1[i - 1] : Integer.MIN_VALUE;\n            int aRight = (i < m) ? nums1[i] : Integer.MAX_VALUE;\n            int bLeft = (j > 0) ? nums2[j - 1] : Integer.MIN_VALUE;\n            int bRight = (j < n) ? nums2[j] : Integer.MAX_VALUE;\n            if (aLeft <= bRight && bLeft <= aRight) {\n                if ((m + n) % 2 == 1) return Math.max(aLeft, bLeft);\n                return (Math.max(aLeft, bLeft) + Math.min(aRight, bRight)) / 2.0;\n            } else if (aLeft > bRight) {\n                hi = i - 1;\n            } else {\n                lo = i + 1;\n            }\n        }\n        return 0.0;\n    }\n}","Python3":"class Solution:\n    def findMedianSortedArrays(self, nums1: List[int], nums2: List[int]) -> float:\n        if len(nums1) > len(nums2):\n            nums1, nums2 = nums2, nums1\n        m, n = len(nums1), len(nums2)\n        half = (m + n + 1) // 2\n        lo, hi = 0, m\n        while lo <= hi:\n            i = (lo + hi) // 2\n            j = half - i\n            a_left = nums1[i - 1] if i > 0 else float('-inf')\n            a_right = nums1[i] if i < m else float('inf')\n            b_left = nums2[j - 1] if j > 0 else float('-inf')\n            b_right = nums2[j] if j < n else float('inf')\n            if a_left <= b_right and b_left <= a_right:\n                if (m + n) % 2 == 1:\n                    return float(max(a_left, b_left))\n                return (max(a_left, b_left) + min(a_right, b_right)) / 2.0\n            if a_left > b_right:\n                hi = i - 1\n            else:\n                lo = i + 1\n        return 0.0","Python":"class Solution(object):\n    def findMedianSortedArrays(self, nums1, nums2):\n        if len(nums1) > len(nums2):\n            nums1, nums2 = nums2, nums1\n        m, n = len(nums1), len(nums2)\n        half = (m + n + 1) // 2\n        lo, hi = 0, m\n        while lo <= hi:\n            i = (lo + hi) // 2\n            j = half - i\n            a_left = nums1[i - 1] if i > 0 else float('-inf')\n            a_right = nums1[i] if i < m else float('inf')\n            b_left = nums2[j - 1] if j > 0 else float('-inf')\n            b_right = nums2[j] if j < n else float('inf')\n            if a_left <= b_right and b_left <= a_right:\n                if (m + n) % 2 == 1:\n                    return float(max(a_left, b_left))\n                return (max(a_left, b_left) + min(a_right, b_right)) / 2.0\n            if a_left > b_right:\n                hi = i - 1\n            else:\n                lo = i + 1\n        return 0.0","JavaScript":"function findMedianSortedArrays(nums1, nums2) {\n  if (nums1.length > nums2.length) return findMedianSortedArrays(nums2, nums1);\n  const m = nums1.length, n = nums2.length;\n  const half = Math.floor((m + n + 1) / 2);\n  let lo = 0, hi = m;\n  while (lo <= hi) {\n    const i = (lo + hi) >> 1;\n    const j = half - i;\n    const aLeft = i > 0 ? nums1[i - 1] : -Infinity;\n    const aRight = i < m ? nums1[i] : Infinity;\n    const bLeft = j > 0 ? nums2[j - 1] : -Infinity;\n    const bRight = j < n ? nums2[j] : Infinity;\n    if (aLeft <= bRight && bLeft <= aRight) {\n      if ((m + n) % 2 === 1) return Math.max(aLeft, bLeft);\n      return (Math.max(aLeft, bLeft) + Math.min(aRight, bRight)) / 2;\n    } else if (aLeft > bRight) {\n      hi = i - 1;\n    } else {\n      lo = i + 1;\n    }\n  }\n  return 0;\n}","TypeScript":"function findMedianSortedArrays(nums1: number[], nums2: number[]): number {\n  if (nums1.length > nums2.length) return findMedianSortedArrays(nums2, nums1);\n  const m = nums1.length, n = nums2.length;\n  const half = Math.floor((m + n + 1) / 2);\n  let lo = 0, hi = m;\n  while (lo <= hi) {\n    const i = (lo + hi) >> 1;\n    const j = half - i;\n    const aLeft = i > 0 ? nums1[i - 1] : -Infinity;\n    const aRight = i < m ? nums1[i] : Infinity;\n    const bLeft = j > 0 ? nums2[j - 1] : -Infinity;\n    const bRight = j < n ? nums2[j] : Infinity;\n    if (aLeft <= bRight && bLeft <= aRight) {\n      if ((m + n) % 2 === 1) return Math.max(aLeft, bLeft);\n      return (Math.max(aLeft, bLeft) + Math.min(aRight, bRight)) / 2;\n    } else if (aLeft > bRight) {\n      hi = i - 1;\n    } else {\n      lo = i + 1;\n    }\n  }\n  return 0;\n}","C#":"using System;\n\npublic class Solution {\n    public double FindMedianSortedArrays(int[] nums1, int[] nums2) {\n        if (nums1.Length > nums2.Length) return FindMedianSortedArrays(nums2, nums1);\n        int m = nums1.Length, n = nums2.Length;\n        int half = (m + n + 1) / 2, lo = 0, hi = m;\n        while (lo <= hi) {\n            int i = (lo + hi) / 2;\n            int j = half - i;\n            int aLeft = i > 0 ? nums1[i - 1] : int.MinValue;\n            int aRight = i < m ? nums1[i] : int.MaxValue;\n            int bLeft = j > 0 ? nums2[j - 1] : int.MinValue;\n            int bRight = j < n ? nums2[j] : int.MaxValue;\n            if (aLeft <= bRight && bLeft <= aRight) {\n                if ((m + n) % 2 == 1) return Math.Max(aLeft, bLeft);\n                return (Math.Max(aLeft, bLeft) + Math.Min(aRight, bRight)) / 2.0;\n            } else if (aLeft > bRight) {\n                hi = i - 1;\n            } else {\n                lo = i + 1;\n            }\n        }\n        return 0.0;\n    }\n}","PHP":"class Solution {\n    function findMedianSortedArrays($nums1, $nums2) {\n        if (count($nums1) > count($nums2)) return $this->findMedianSortedArrays($nums2, $nums1);\n        $m = count($nums1); $n = count($nums2);\n        $half = intdiv($m + $n + 1, 2); $lo = 0; $hi = $m;\n        while ($lo <= $hi) {\n            $i = intdiv($lo + $hi, 2);\n            $j = $half - $i;\n            $aLeft = $i > 0 ? $nums1[$i - 1] : -INF;\n            $aRight = $i < $m ? $nums1[$i] : INF;\n            $bLeft = $j > 0 ? $nums2[$j - 1] : -INF;\n            $bRight = $j < $n ? $nums2[$j] : INF;\n            if ($aLeft <= $bRight && $bLeft <= $aRight) {\n                if (($m + $n) % 2 === 1) return (float)max($aLeft, $bLeft);\n                return (max($aLeft, $bLeft) + min($aRight, $bRight)) / 2.0;\n            } elseif ($aLeft > $bRight) {\n                $hi = $i - 1;\n            } else {\n                $lo = $i + 1;\n            }\n        }\n        return 0.0;\n    }\n}"}}],"tests":[{"name":"Example 1 (odd total)","args":[[2,8],[1,4,9]],"expected":4},{"name":"Example 2 (empty nums1)","args":[[],[3,5]],"expected":4},{"name":"Even interleaved","args":[[1,3],[2,4]],"expected":2.5},{"name":"Negatives","args":[[-5,-2],[-3,10]],"expected":-2.5}],"javaDriver":"public class Main {\n  static void eq(double a, double b, String n) { if (Math.abs(a - b) > 1e-9) throw new AssertionError(n + \": \" + a); }\n  public static void main(String[] args) {\n    Solution s = new Solution();\n    eq(s.findMedianSortedArrays(new int[]{2,8}, new int[]{1,4,9}), 4.0, \"Ex1\");\n    eq(s.findMedianSortedArrays(new int[]{}, new int[]{3,5}), 4.0, \"Ex2\");\n    eq(s.findMedianSortedArrays(new int[]{1,3}, new int[]{2,4}), 2.5, \"Even\");\n    eq(s.findMedianSortedArrays(new int[]{-5,-2}, new int[]{-3,10}), -2.5, \"Neg\");\n  }\n}","phpDriver":"$s = new Solution();\nif (abs($s->findMedianSortedArrays([2,8],[1,4,9]) - 4.0) > 1e-9) exit(1);\nif (abs($s->findMedianSortedArrays([],[3,5]) - 4.0) > 1e-9) exit(1);\nif (abs($s->findMedianSortedArrays([1,3],[2,4]) - 2.5) > 1e-9) exit(1);\nif (abs($s->findMedianSortedArrays([-5,-2],[-3,10]) - (-2.5)) > 1e-9) exit(1);","csharpDriver":"using System;\npublic class Runner {\n  public static void Main() {\n    var s = new Solution();\n    if (Math.Abs(s.FindMedianSortedArrays(new int[]{2,8}, new int[]{1,4,9}) - 4.0) > 1e-9) throw new Exception();\n    if (Math.Abs(s.FindMedianSortedArrays(new int[]{}, new int[]{3,5}) - 4.0) > 1e-9) throw new Exception();\n    if (Math.Abs(s.FindMedianSortedArrays(new int[]{1,3}, new int[]{2,4}) - 2.5) > 1e-9) throw new Exception();\n    if (Math.Abs(s.FindMedianSortedArrays(new int[]{-5,-2}, new int[]{-3,10}) - (-2.5)) > 1e-9) throw new Exception();\n  }\n}"},"data/guides/5-longest-palindromic-substring.json":{"number":5,"slug":"longest-palindromic-substring","title":"Longest Palindromic Substring","difficulty":"Medium","topics":["Two Pointers","String","Dynamic Programming"],"access":"Free","url":"https://leetcode.com/problems/longest-palindromic-substring/","jsFunctionName":"longestPalindrome","pyMethodName":"longestPalindrome","verification":{"verifiedLanguages":["Java","Python3","Python","JavaScript","TypeScript","C#","PHP"],"untestedLanguages":[]},"understand":{"question":"Given a string, what is the longest contiguous slice that reads the exact same forwards and backwards?","plainExplanation":"Every palindrome mirrors itself around a middle point: either one center letter (like 'racecar', centered at 'e') or the gap between two matching middle letters (like 'noon', centered between the two 'o's). Finding the longest palindrome means finding the widest mirror.","inputMeaning":"A non-empty string s of length 1 or more.","outputMeaning":"Any single substring of s with maximum length that is a palindrome.","rules":["Both odd-length palindromes (centered on one character) and even-length palindromes (centered between two characters) are valid.","A single character by itself is always a palindrome of length 1.","If multiple palindromes tie for longest length, returning any one of them is valid."],"terms":[{"term":"Palindrome","definition":"A string that stays identical when reversed, such as \"level\" or \"aa\"."},{"term":"Center","definition":"The middle position(s) from which symmetric characters expand outward: (i, i) for odd lengths and (i, i+1) for even lengths."}],"example1":{"input":"s = \"xabay\"","output":"\"aba\"","whyValid":"Expanding around center index 2 ('b') sees s[1] == 'a' and s[3] == 'a', giving \"aba\" (length 3). Expanding further sees 'x' != 'y' and stops.","diagram":{"type":"two-pointers","items":[{"index":0,"value":"x","state":"skip"},{"index":1,"value":"a","state":"match"},{"index":2,"value":"b","state":"match","label":"center"},{"index":3,"value":"a","state":"match"},{"index":4,"value":"y","state":"skip"}],"pointers":[{"index":1,"name":"L"},{"index":3,"name":"R"}],"caption":"\"aba\" mirrors cleanly around index 2."}},"example2":{"input":"s = \"noon\"","output":"\"noon\"","whyEdgeCase":"Even-length palindrome! There is no single middle character — the center sits between indices 1 and 2 ('o' and 'o'), so checking only odd centers (i, i) would miss it."}},"dryRun":{"approachId":"expand-center","algorithmName":"Expand Around Center","steps":[{"title":"Start at center i = 0 ('x')","description":"Odd center (0,0) gives \"x\" (len 1). Even center (0,1) fails ('x' != 'a'). Best so far: [0..0] = \"x\".","state":{"type":"two-pointers","items":[{"index":0,"value":"x","state":"active"},{"index":1,"value":"a","state":"default"},{"index":2,"value":"b","state":"default"},{"index":3,"value":"a","state":"default"},{"index":4,"value":"y","state":"default"}],"pointers":[{"index":0,"name":"L=R"}],"aux":{"title":"Best Slice","entries":[{"key":"best","value":"\"x\" (len 1)"}]},"caption":"Center 0 gives length 1."}},{"title":"Center i = 2 ('b'): expand to [1..3] = \"aba\"","description":"Start with L=2, R=2 ('b'). Step outward to L=1, R=3: s[1] == s[3] ('a' == 'a'), so expand again! Next step L=0, R=4 fails ('x' != 'y'). Best updates to \"aba\" (len 3).","state":{"type":"two-pointers","items":[{"index":0,"value":"x","state":"skip"},{"index":1,"value":"a","state":"match"},{"index":2,"value":"b","state":"match"},{"index":3,"value":"a","state":"match"},{"index":4,"value":"y","state":"skip"}],"pointers":[{"index":1,"name":"L"},{"index":3,"name":"R"}],"aux":{"title":"Best Slice","entries":[{"key":"best","value":"\"aba\" (len 3)","highlight":true}]},"caption":"Found length-3 palindrome \"aba\"!"}},{"title":"Finish centers i = 3, 4 and return \"aba\"","description":"Centers 3 and 4 only produce length-1 palindromes. Return s.slice(1, 4) = \"aba\".","state":{"type":"two-pointers","items":[{"index":0,"value":"x","state":"default"},{"index":1,"value":"a","state":"match"},{"index":2,"value":"b","state":"match"},{"index":3,"value":"a","state":"match"},{"index":4,"value":"y","state":"default"}],"pointers":[{"index":1,"name":"bestStart"},{"index":3,"name":"bestEnd"}],"aux":{"title":"Final Result","entries":[{"key":"output","value":"\"aba\"","highlight":true}]},"caption":"Final answer: \"aba\"."}}]},"approaches":[{"id":"brute-force","name":"Brute Force Substring Verification","recommended":false,"coreIdeaSummary":"Check every substring s[i..j] with two pointers.","coreIdea":"Enumerate every substring (i, j) and scan inward from i and j to verify whether it is a palindrome.","steps":["Track bestStart = 0, bestLen = 1.","For every pair i <= j where j - i + 1 > bestLen, test if s[i..j] is a palindrome.","Update bestStart and bestLen whenever a longer palindrome is found."],"whyItWorks":"All substrings of s are checked directly from longest/candidate bounds.","whenToUse":"Baseline verification on short strings.","complexity":{"time":"O(n^3)","space":"O(1)","variables":"n = length of s","boundType":"Worst-case"},"code":{"Java":"class Solution {\n    public String longestPalindrome(String s) {\n        int bestStart = 0, bestLen = 1, n = s.length();\n        for (int i = 0; i < n; i++) {\n            for (int j = i + bestLen; j < n; j++) {\n                int l = i, r = j;\n                boolean ok = true;\n                while (l < r) { if (s.charAt(l++) != s.charAt(r--)) { ok = false; break; } }\n                if (ok) { bestStart = i; bestLen = j - i + 1; }\n            }\n        }\n        return s.substring(bestStart, bestStart + bestLen);\n    }\n}","Python3":"class Solution:\n    def longestPalindrome(self, s: str) -> str:\n        best_start, best_len, n = 0, 1, len(s)\n        for i in range(n):\n            for j in range(i + best_len, n):\n                sub = s[i:j + 1]\n                if sub == sub[::-1]:\n                    best_start, best_len = i, j - i + 1\n        return s[best_start:best_start + best_len]","Python":"class Solution(object):\n    def longestPalindrome(self, s):\n        best_start, best_len, n = 0, 1, len(s)\n        for i in range(n):\n            for j in range(i + best_len, n):\n                sub = s[i:j + 1]\n                if sub == sub[::-1]:\n                    best_start, best_len = i, j - i + 1\n        return s[best_start:best_start + best_len]","JavaScript":"function longestPalindrome(s) {\n  let bestStart = 0, bestLen = 1;\n  for (let i = 0; i < s.length; i++) {\n    for (let j = i + bestLen; j < s.length; j++) {\n      let l = i, r = j, ok = true;\n      while (l < r) if (s[l++] !== s[r--]) { ok = false; break; }\n      if (ok) { bestStart = i; bestLen = j - i + 1; }\n    }\n  }\n  return s.slice(bestStart, bestStart + bestLen);\n}","TypeScript":"function longestPalindrome(s: string): string {\n  let bestStart = 0, bestLen = 1;\n  for (let i = 0; i < s.length; i++) {\n    for (let j = i + bestLen; j < s.length; j++) {\n      let l = i, r = j, ok = true;\n      while (l < r) if (s[l++] !== s[r--]) { ok = false; break; }\n      if (ok) { bestStart = i; bestLen = j - i + 1; }\n    }\n  }\n  return s.slice(bestStart, bestStart + bestLen);\n}","C#":"public class Solution {\n    public string LongestPalindrome(string s) {\n        int bestStart = 0, bestLen = 1, n = s.Length;\n        for (int i = 0; i < n; i++) {\n            for (int j = i + bestLen; j < n; j++) {\n                int l = i, r = j; bool ok = true;\n                while (l < r) if (s[l++] != s[r--]) { ok = false; break; }\n                if (ok) { bestStart = i; bestLen = j - i + 1; }\n            }\n        }\n        return s.Substring(bestStart, bestLen);\n    }\n}","PHP":"class Solution {\n    function longestPalindrome($s) {\n        $bestStart = 0; $bestLen = 1; $n = strlen($s);\n        for ($i = 0; $i < $n; $i++) {\n            for ($j = $i + $bestLen; $j < $n; $j++) {\n                $l = $i; $r = $j; $ok = true;\n                while ($l < $r) { if ($s[$l++] !== $s[$r--]) { $ok = false; break; } }\n                if ($ok) { $bestStart = $i; $bestLen = $j - $i + 1; }\n            }\n        }\n        return substr($s, $bestStart, $bestLen);\n    }\n}"}},{"id":"dp-2d","name":"2D Dynamic Programming Table","recommended":false,"coreIdeaSummary":"dp[i][j] is true when s[i] == s[j] and the inner slice s[i+1..j-1] is a palindrome.","coreIdea":"Fill a boolean table dp[i][j] by increasing substring length so inner slices are known before outer slices.","steps":["Set dp[i][i] = true for all i.","For length L from 2 to n, check s[i] == s[j] and (L == 2 or dp[i+1][j-1]).","Record the longest [i..j] where dp[i][j] is true."],"whyItWorks":"A slice s[i..j] is palindromic if and only if its endpoints match and its interior s[i+1..j-1] is palindromic.","whenToUse":"Useful when also answering repeated substring-palindrome queries in O(1).","complexity":{"time":"O(n^2)","space":"O(n^2)","variables":"n = length of s","boundType":"Worst-case"},"code":{"Java":"class Solution {\n    public String longestPalindrome(String s) {\n        int n = s.length(), start = 0, maxLen = 1;\n        boolean[][] dp = new boolean[n][n];\n        for (int i = n - 1; i >= 0; i--) {\n            for (int j = i; j < n; j++) {\n                if (s.charAt(i) == s.charAt(j) && (j - i <= 2 || dp[i + 1][j - 1])) {\n                    dp[i][j] = true;\n                    if (j - i + 1 > maxLen) { start = i; maxLen = j - i + 1; }\n                }\n            }\n        }\n        return s.substring(start, start + maxLen);\n    }\n}","Python3":"class Solution:\n    def longestPalindrome(self, s: str) -> str:\n        n = len(s)\n        dp = [[False] * n for _ in range(n)]\n        start, max_len = 0, 1\n        for i in range(n - 1, -1, -1):\n            for j in range(i, n):\n                if s[i] == s[j] and (j - i <= 2 or dp[i + 1][j - 1]):\n                    dp[i][j] = True\n                    if j - i + 1 > max_len:\n                        start, max_len = i, j - i + 1\n        return s[start:start + max_len]","Python":"class Solution(object):\n    def longestPalindrome(self, s):\n        n = len(s)\n        dp = [[False] * n for _ in range(n)]\n        start, max_len = 0, 1\n        for i in range(n - 1, -1, -1):\n            for j in range(i, n):\n                if s[i] == s[j] and (j - i <= 2 or dp[i + 1][j - 1]):\n                    dp[i][j] = True\n                    if j - i + 1 > max_len:\n                        start, max_len = i, j - i + 1\n        return s[start:start + max_len]","JavaScript":"function longestPalindrome(s) {\n  const n = s.length;\n  const dp = Array.from({ length: n }, () => new Uint8Array(n));\n  let start = 0, maxLen = 1;\n  for (let i = n - 1; i >= 0; i--) {\n    for (let j = i; j < n; j++) {\n      if (s[i] === s[j] && (j - i <= 2 || dp[i + 1][j - 1])) {\n        dp[i][j] = 1;\n        if (j - i + 1 > maxLen) { start = i; maxLen = j - i + 1; }\n      }\n    }\n  }\n  return s.slice(start, start + maxLen);\n}","TypeScript":"function longestPalindrome(s: string): string {\n  const n = s.length;\n  const dp = Array.from({ length: n }, () => new Uint8Array(n));\n  let start = 0, maxLen = 1;\n  for (let i = n - 1; i >= 0; i--) {\n    for (let j = i; j < n; j++) {\n      if (s[i] === s[j] && (j - i <= 2 || dp[i + 1][j - 1])) {\n        dp[i][j] = 1;\n        if (j - i + 1 > maxLen) { start = i; maxLen = j - i + 1; }\n      }\n    }\n  }\n  return s.slice(start, start + maxLen);\n}","C#":"public class Solution {\n    public string LongestPalindrome(string s) {\n        int n = s.Length, start = 0, maxLen = 1;\n        bool[,] dp = new bool[n, n];\n        for (int i = n - 1; i >= 0; i--) {\n            for (int j = i; j < n; j++) {\n                if (s[i] == s[j] && (j - i <= 2 || dp[i + 1, j - 1])) {\n                    dp[i, j] = true;\n                    if (j - i + 1 > maxLen) { start = i; maxLen = j - i + 1; }\n                }\n            }\n        }\n        return s.Substring(start, maxLen);\n    }\n}","PHP":"class Solution {\n    function longestPalindrome($s) {\n        $n = strlen($s); $start = 0; $maxLen = 1;\n        $dp = array_fill(0, $n, array_fill(0, $n, false));\n        for ($i = $n - 1; $i >= 0; $i--) {\n            for ($j = $i; $j < $n; $j++) {\n                if ($s[$i] === $s[$j] && ($j - $i <= 2 || $dp[$i + 1][$j - 1])) {\n                    $dp[$i][$j] = true;\n                    if ($j - $i + 1 > $maxLen) { $start = $i; $maxLen = $j - $i + 1; }\n                }\n            }\n        }\n        return substr($s, $start, $maxLen);\n    }\n}"}},{"id":"expand-center","name":"Expand Around Center","recommended":true,"recommendedTradeOff":"Matches 2D DP's O(n^2) time while eliminating the entire O(n^2) table down to O(1) auxiliary space with clean, minimal code.","coreIdeaSummary":"Expand outward from each of the 2n - 1 odd and even centers.","coreIdea":"For every index i, expand two pointers outward from (i, i) for odd palindromes and (i, i + 1) for even palindromes while characters match.","steps":["Initialize bestStart = 0, bestLen = 1.","Define expand(l, r) that widens while l >= 0, r < n, and s[l] == s[r], returning the valid length.","For each i from 0 to n - 1, take the wider of expand(i, i) and expand(i, i + 1) and update bestStart / bestLen."],"whyItWorks":"Every palindrome has a unique center among the 2n - 1 possible centers, and expanding outward only visits matching pairs.","whenToUse":"Best practical default for string lengths up to a few thousand characters.","complexity":{"time":"O(n^2)","space":"O(1)","variables":"n = length of s","boundType":"Worst-case"},"code":{"Java":"class Solution {\n    public String longestPalindrome(String s) {\n        int start = 0, end = 0;\n        for (int i = 0; i < s.length(); i++) {\n            int len1 = expand(s, i, i);\n            int len2 = expand(s, i, i + 1);\n            int len = Math.max(len1, len2);\n            if (len > end - start + 1) {\n                start = i - (len - 1) / 2;\n                end = i + len / 2;\n            }\n        }\n        return s.substring(start, end + 1);\n    }\n    private int expand(String s, int l, int r) {\n        while (l >= 0 && r < s.length() && s.charAt(l) == s.charAt(r)) { l--; r++; }\n        return r - l - 1;\n    }\n}","Python3":"class Solution:\n    def longestPalindrome(self, s: str) -> str:\n        start, end = 0, 0\n        def expand(l: int, r: int) -> int:\n            while l >= 0 and r < len(s) and s[l] == s[r]:\n                l -= 1; r += 1\n            return r - l - 1\n        for i in range(len(s)):\n            best = max(expand(i, i), expand(i, i + 1))\n            if best > end - start + 1:\n                start = i - (best - 1) // 2\n                end = i + best // 2\n        return s[start:end + 1]","Python":"class Solution(object):\n    def longestPalindrome(self, s):\n        start, end = 0, 0\n        def expand(l, r):\n            while l >= 0 and r < len(s) and s[l] == s[r]:\n                l -= 1; r += 1\n            return r - l - 1\n        for i in range(len(s)):\n            best = max(expand(i, i), expand(i, i + 1))\n            if best > end - start + 1:\n                start = i - (best - 1) // 2\n                end = i + best // 2\n        return s[start:end + 1]","JavaScript":"function longestPalindrome(s) {\n  let start = 0, end = 0;\n  const expand = (l, r) => {\n    while (l >= 0 && r < s.length && s[l] === s[r]) { l--; r++; }\n    return r - l - 1;\n  };\n  for (let i = 0; i < s.length; i++) {\n    const best = Math.max(expand(i, i), expand(i, i + 1));\n    if (best > end - start + 1) {\n      start = i - Math.floor((best - 1) / 2);\n      end = i + Math.floor(best / 2);\n    }\n  }\n  return s.slice(start, end + 1);\n}","TypeScript":"function longestPalindrome(s: string): string {\n  let start = 0, end = 0;\n  const expand = (l: number, r: number): number => {\n    while (l >= 0 && r < s.length && s[l] === s[r]) { l--; r++; }\n    return r - l - 1;\n  };\n  for (let i = 0; i < s.length; i++) {\n    const best = Math.max(expand(i, i), expand(i, i + 1));\n    if (best > end - start + 1) {\n      start = i - Math.floor((best - 1) / 2);\n      end = i + Math.floor(best / 2);\n    }\n  }\n  return s.slice(start, end + 1);\n}","C#":"using System;\n\npublic class Solution {\n    public string LongestPalindrome(string s) {\n        int start = 0, end = 0;\n        for (int i = 0; i < s.Length; i++) {\n            int best = Math.Max(Expand(s, i, i), Expand(s, i, i + 1));\n            if (best > end - start + 1) {\n                start = i - (best - 1) / 2;\n                end = i + best / 2;\n            }\n        }\n        return s.Substring(start, end - start + 1);\n    }\n    private int Expand(string s, int l, int r) {\n        while (l >= 0 && r < s.Length && s[l] == s[r]) { l--; r++; }\n        return r - l - 1;\n    }\n}","PHP":"class Solution {\n    function longestPalindrome($s) {\n        $start = 0; $end = 0; $n = strlen($s);\n        for ($i = 0; $i < $n; $i++) {\n            $best = max($this->expand($s, $i, $i), $this->expand($s, $i, $i + 1));\n            if ($best > $end - $start + 1) {\n                $start = $i - intdiv($best - 1, 2);\n                $end = $i + intdiv($best, 2);\n            }\n        }\n        return substr($s, $start, $end - $start + 1);\n    }\n    private function expand($s, $l, $r) {\n        $n = strlen($s);\n        while ($l >= 0 && $r < $n && $s[$l] === $s[$r]) { $l--; $r++; }\n        return $r - $l - 1;\n    }\n}"}},{"id":"manacher","name":"Manacher's Linear-Time Algorithm","recommended":false,"coreIdeaSummary":"Insert '#' separators and reuse mirror radii inside the rightmost known palindrome.","coreIdea":"Transform s into '#a#b#a#' so all palindromes have odd length. Track the palindrome with the rightmost reach R and reuse mirrored radii before expanding.","steps":["Build transformed string T with '#' between characters and sentinels '^' and '$'.","Maintain center C and right boundary R of the rightmost palindrome.","Initialize p[i] = (i < R) ? min(R - i, p[2*C - i]) : 0, then expand around i and update C, R when i + p[i] > R."],"whyItWorks":"Every expansion step that succeeds strictly advances R; since R moves right at most 2n times, total work is O(n).","whenToUse":"When n is very large (e.g., >= 10^5) and true linear O(n) worst-case time is required.","complexity":{"time":"O(n)","space":"O(n)","variables":"n = length of s","boundType":"Worst-case"},"code":{"Java":"class Solution {\n    public String longestPalindrome(String s) {\n        StringBuilder sb = new StringBuilder(\"^\");\n        for (int i = 0; i < s.length(); i++) sb.append('#').append(s.charAt(i));\n        sb.append(\"#$\");\n        String t = sb.toString();\n        int[] p = new int[t.length()];\n        int c = 0, r = 0, bestLen = 0, bestCenter = 0;\n        for (int i = 1; i < t.length() - 1; i++) {\n            if (i < r) p[i] = Math.min(r - i, p[2 * c - i]);\n            while (t.charAt(i + 1 + p[i]) == t.charAt(i - 1 - p[i])) p[i]++;\n            if (i + p[i] > r) { c = i; r = i + p[i]; }\n            if (p[i] > bestLen) { bestLen = p[i]; bestCenter = i; }\n        }\n        int start = (bestCenter - bestLen) / 2;\n        return s.substring(start, start + bestLen);\n    }\n}","Python3":"class Solution:\n    def longestPalindrome(self, s: str) -> str:\n        t = '^#' + '#'.join(s) + '#$'\n        p = [0] * len(t)\n        c = r = best_len = best_center = 0\n        for i in range(1, len(t) - 1):\n            if i < r:\n                p[i] = min(r - i, p[2 * c - i])\n            while t[i + 1 + p[i]] == t[i - 1 - p[i]]:\n                p[i] += 1\n            if i + p[i] > r:\n                c, r = i, i + p[i]\n            if p[i] > best_len:\n                best_len, best_center = p[i], i\n        start = (best_center - best_len) // 2\n        return s[start:start + best_len]","Python":"class Solution(object):\n    def longestPalindrome(self, s):\n        t = '^#' + '#'.join(s) + '#$'\n        p = [0] * len(t)\n        c = r = best_len = best_center = 0\n        for i in range(1, len(t) - 1):\n            if i < r:\n                p[i] = min(r - i, p[2 * c - i])\n            while t[i + 1 + p[i]] == t[i - 1 - p[i]]:\n                p[i] += 1\n            if i + p[i] > r:\n                c, r = i, i + p[i]\n            if p[i] > best_len:\n                best_len, best_center = p[i], i\n        start = (best_center - best_len) // 2\n        return s[start:start + best_len]","JavaScript":"function longestPalindrome(s) {\n  const t = \"^#\" + s.split(\"\").join(\"#\") + \"#$\";\n  const p = new Int32Array(t.length);\n  let c = 0, r = 0, bestLen = 0, bestCenter = 0;\n  for (let i = 1; i < t.length - 1; i++) {\n    if (i < r) p[i] = Math.min(r - i, p[2 * c - i]);\n    while (t[i + 1 + p[i]] === t[i - 1 - p[i]]) p[i]++;\n    if (i + p[i] > r) { c = i; r = i + p[i]; }\n    if (p[i] > bestLen) { bestLen = p[i]; bestCenter = i; }\n  }\n  const start = Math.floor((bestCenter - bestLen) / 2);\n  return s.slice(start, start + bestLen);\n}","TypeScript":"function longestPalindrome(s: string): string {\n  const t = \"^#\" + s.split(\"\").join(\"#\") + \"#$\";\n  const p = new Int32Array(t.length);\n  let c = 0, r = 0, bestLen = 0, bestCenter = 0;\n  for (let i = 1; i < t.length - 1; i++) {\n    if (i < r) p[i] = Math.min(r - i, p[2 * c - i]);\n    while (t[i + 1 + p[i]] === t[i - 1 - p[i]]) p[i]++;\n    if (i + p[i] > r) { c = i; r = i + p[i]; }\n    if (p[i] > bestLen) { bestLen = p[i]; bestCenter = i; }\n  }\n  const start = Math.floor((bestCenter - bestLen) / 2);\n  return s.slice(start, start + bestLen);\n}","C#":"using System;\nusing System.Text;\n\npublic class Solution {\n    public string LongestPalindrome(string s) {\n        var sb = new StringBuilder(\"^\");\n        for (int i = 0; i < s.Length; i++) { sb.Append('#'); sb.Append(s[i]); }\n        sb.Append(\"#$\");\n        string t = sb.ToString();\n        int[] p = new int[t.Length];\n        int c = 0, r = 0, bestLen = 0, bestCenter = 0;\n        for (int i = 1; i < t.Length - 1; i++) {\n            if (i < r) p[i] = Math.Min(r - i, p[2 * c - i]);\n            while (t[i + 1 + p[i]] == t[i - 1 - p[i]]) p[i]++;\n            if (i + p[i] > r) { c = i; r = i + p[i]; }\n            if (p[i] > bestLen) { bestLen = p[i]; bestCenter = i; }\n        }\n        int start = (bestCenter - bestLen) / 2;\n        return s.Substring(start, bestLen);\n    }\n}","PHP":"class Solution {\n    function longestPalindrome($s) {\n        $t = \"^#\" . implode(\"#\", str_split($s)) . \"#$\";\n        $n = strlen($t);\n        $p = array_fill(0, $n, 0);\n        $c = 0; $r = 0; $bestLen = 0; $bestCenter = 0;\n        for ($i = 1; $i < $n - 1; $i++) {\n            if ($i < $r) $p[$i] = min($r - $i, $p[2 * $c - $i]);\n            while ($t[$i + 1 + $p[$i]] === $t[$i - 1 - $p[$i]]) $p[$i]++;\n            if ($i + $p[$i] > $r) { $c = $i; $r = $i + $p[$i]; }\n            if ($p[$i] > $bestLen) { $bestLen = $p[$i]; $bestCenter = $i; }\n        }\n        $start = intdiv($bestCenter - $bestLen, 2);\n        return substr($s, $start, $bestLen);\n    }\n}"}}],"tests":[{"name":"Example 1","args":["xabay"],"expected":"aba"},{"name":"Example 2 (even)","args":["noon"],"expected":"noon"},{"name":"Single char","args":["q"],"expected":"q"},{"name":"All equal","args":["aaaa"],"expected":"aaaa"}],"javaDriver":"public class Main {\n  public static void main(String[] args) {\n    Solution s = new Solution();\n    if (!s.longestPalindrome(\"xabay\").equals(\"aba\")) throw new AssertionError(\"Ex1\");\n    if (!s.longestPalindrome(\"noon\").equals(\"noon\")) throw new AssertionError(\"Ex2\");\n    if (!s.longestPalindrome(\"q\").equals(\"q\")) throw new AssertionError(\"One\");\n    if (!s.longestPalindrome(\"aaaa\").equals(\"aaaa\")) throw new AssertionError(\"All\");\n  }\n}","phpDriver":"$s = new Solution();\nif ($s->longestPalindrome(\"xabay\") !== \"aba\") exit(1);\nif ($s->longestPalindrome(\"noon\") !== \"noon\") exit(1);\nif ($s->longestPalindrome(\"q\") !== \"q\") exit(1);\nif ($s->longestPalindrome(\"aaaa\") !== \"aaaa\") exit(1);","csharpDriver":"using System;\npublic class Runner {\n  public static void Main() {\n    var s = new Solution();\n    if (s.LongestPalindrome(\"xabay\") != \"aba\") throw new Exception();\n    if (s.LongestPalindrome(\"noon\") != \"noon\") throw new Exception();\n    if (s.LongestPalindrome(\"q\") != \"q\") throw new Exception();\n    if (s.LongestPalindrome(\"aaaa\") != \"aaaa\") throw new Exception();\n  }\n}"},"data/guides/6-zigzag-conversion.json":{"number":6,"slug":"zigzag-conversion","title":"Zigzag Conversion","difficulty":"Medium","topics":["String"],"access":"Free","url":"https://leetcode.com/problems/zigzag-conversion/","jsFunctionName":"convert","pyMethodName":"convert","verification":{"verifiedLanguages":["Java","Python3","Python","JavaScript","TypeScript","C#","PHP"],"untestedLanguages":[]},"understand":{"question":"If you write a string's characters down and diagonally up across numRows horizontal rows in a zigzag wave, what string do you get when reading row by row from top to bottom?","plainExplanation":"Imagine writing letters onto lined notebook paper with numRows lines: go straight down from line 0 to the bottom line, bounce diagonally back up to line 0, and repeat. Then read line 0 from left to right, followed by line 1, and so on.","inputMeaning":"A string s and a positive integer numRows (>= 1).","outputMeaning":"The concatenated string formed by reading each row left-to-right from row 0 down to row numRows - 1.","rules":["If numRows == 1 or numRows >= s.length, there is no zigzag bounce — return s unchanged.","Do NOT emit spaces between diagonal letters; each row simply collects its characters in order.","Direction flips only when reaching row 0 (start moving down) or row numRows - 1 (start moving up)."],"terms":[{"term":"Row Bucket","definition":"A string buffer dedicated to one horizontal line (0 .. numRows - 1) that collects letters in the exact order they land on that row."},{"term":"Cycle Length","definition":"The number of characters in one full down-and-up wave: 2 * (numRows - 1) when numRows > 1."}],"example1":{"input":"s = \"INFINITY\", numRows = 3","output":"\"IIIFNTNY\"","whyValid":"Writing \"INFINITY\" across 3 rows places indices 0:'I'->r0, 1:'N'->r1, 2:'F'->r2, 3:'I'->r1, 4:'N'->r0, 5:'I'->r1, 6:'T'->r2, 7:'Y'->r1. Reading row 0 (\"IN\"), row 1 (\"NIIY\"), and row 2 (\"FT\") yields \"INNIIYFT\".","diagram":{"type":"grid","rows":[[{"value":"I","state":"match"},{"value":""},{"value":"N","state":"match"},{"value":""}],[{"value":"N","state":"active"},{"value":"I","state":"active"},{"value":"I","state":"active"},{"value":"Y","state":"active"}],[{"value":"F"},{"value":""},{"value":"T"},{"value":""}]],"caption":"Row 0: IN, Row 1: NIIY, Row 2: FT -> \"INNIIYFT\"."}},"example2":{"input":"s = \"AB\", numRows = 1","output":"\"AB\"","whyEdgeCase":"When numRows == 1, cycle length 2 * (numRows - 1) is 0! Any formula dividing or stepping by cycle length would loop infinitely unless numRows == 1 returns s early."}},"dryRun":{"approachId":"row-simulation","algorithmName":"Row-by-Row Direction Simulation","steps":[{"title":"Place 'I', 'N', 'F' moving down rows 0 -> 1 -> 2","description":"Start at row = 0, step = +1. Append 'I' to row 0, 'N' to row 1, 'F' to row 2. Hitting bottom row 2 flips step to -1.","state":{"type":"grid","rows":[[{"value":"I","state":"match"},{"value":""},{"value":""},{"value":""}],[{"value":"N","state":"match"},{"value":""},{"value":""},{"value":""}],[{"value":"F","state":"active"},{"value":""},{"value":""},{"value":""}]],"aux":{"title":"Row Buffers","entries":[{"key":"r0","value":"I"},{"key":"r1","value":"N"},{"key":"r2","value":"F"}]},"caption":"Reached bottom row 2; bounce direction upward."}},{"title":"Place 'I', 'N' bouncing up to row 0, then 'I', 'T', 'Y'","description":"Step up to row 1 ('I') and row 0 ('N'), flip down to row 1 ('I'), row 2 ('T'), and back up to row 1 ('Y').","state":{"type":"grid","rows":[[{"value":"I","state":"match"},{"value":""},{"value":"N","state":"match"},{"value":""}],[{"value":"N","state":"match"},{"value":"I","state":"match"},{"value":"I","state":"match"},{"value":"Y","state":"active"}],[{"value":"F","state":"match"},{"value":""},{"value":"T","state":"match"},{"value":""}]],"aux":{"title":"Row Buffers","entries":[{"key":"r0","value":"IN"},{"key":"r1","value":"NIIY"},{"key":"r2","value":"FT"}]},"caption":"Join rows 0 + 1 + 2 = \"INNIIYFT\"."}}]},"approaches":[{"id":"row-simulation","name":"Row-by-Row Simulation with Direction Flag","recommended":true,"recommendedTradeOff":"Visits each character once in O(n) time without needing 2D blank cells or tricky index arithmetic.","coreIdeaSummary":"Keep one buffer per row and bounce a row cursor between 0 and numRows - 1.","coreIdea":"Maintain an array of numRows string builders. Append each character to rows[curRow], flipping direction at row 0 and row numRows - 1.","steps":["If numRows == 1 or numRows >= len(s), return s.","Create numRows empty row buffers and set row = 0, dir = -1.","For each char ch: if row == 0 or row == numRows - 1, negate dir; append ch to rows[row]; set row += dir.","Join all row buffers and return."],"whyItWorks":"Negating dir at both endpoints makes row oscillate cleanly: 0, 1, ..., numRows-1, numRows-2, ..., 0.","whenToUse":"Default clean, bug-resistant solution.","complexity":{"time":"O(n)","space":"O(n)","variables":"n = length of s","boundType":"Worst-case"},"code":{"Java":"class Solution {\n    public String convert(String s, int numRows) {\n        if (numRows == 1 || numRows >= s.length()) return s;\n        StringBuilder[] rows = new StringBuilder[numRows];\n        for (int i = 0; i < numRows; i++) rows[i] = new StringBuilder();\n        int row = 0, dir = -1;\n        for (int i = 0; i < s.length(); i++) {\n            if (row == 0 || row == numRows - 1) dir = -dir;\n            rows[row].append(s.charAt(i));\n            row += dir;\n        }\n        StringBuilder out = new StringBuilder(s.length());\n        for (StringBuilder rb : rows) out.append(rb);\n        return out.toString();\n    }\n}","Python3":"class Solution:\n    def convert(self, s: str, numRows: int) -> str:\n        if numRows == 1 or numRows >= len(s):\n            return s\n        rows = [[] for _ in range(numRows)]\n        row, step = 0, -1\n        for ch in s:\n            if row == 0 or row == numRows - 1:\n                step = -step\n            rows[row].append(ch)\n            row += step\n        return ''.join(''.join(r) for r in rows)","Python":"class Solution(object):\n    def convert(self, s, numRows):\n        if numRows == 1 or numRows >= len(s):\n            return s\n        rows = [[] for _ in range(numRows)]\n        row, step = 0, -1\n        for ch in s:\n            if row == 0 or row == numRows - 1:\n                step = -step\n            rows[row].append(ch)\n            row += step\n        return ''.join(''.join(r) for r in rows)","JavaScript":"function convert(s, numRows) {\n  if (numRows === 1 || numRows >= s.length) return s;\n  const rows = Array.from({ length: numRows }, () => \"\");\n  let row = 0, dir = -1;\n  for (const ch of s) {\n    if (row === 0 || row === numRows - 1) dir = -dir;\n    rows[row] += ch;\n    row += dir;\n  }\n  return rows.join(\"\");\n}","TypeScript":"function convert(s: string, numRows: number): string {\n  if (numRows === 1 || numRows >= s.length) return s;\n  const rows: string[] = Array.from({ length: numRows }, () => \"\");\n  let row = 0, dir = -1;\n  for (const ch of s) {\n    if (row === 0 || row === numRows - 1) dir = -dir;\n    rows[row] += ch;\n    row += dir;\n  }\n  return rows.join(\"\");\n}","C#":"using System.Text;\n\npublic class Solution {\n    public string Convert(string s, int numRows) {\n        if (numRows == 1 || numRows >= s.Length) return s;\n        StringBuilder[] rows = new StringBuilder[numRows];\n        for (int i = 0; i < numRows; i++) rows[i] = new StringBuilder();\n        int row = 0, dir = -1;\n        foreach (char ch in s) {\n            if (row == 0 || row == numRows - 1) dir = -dir;\n            rows[row].Append(ch);\n            row += dir;\n        }\n        StringBuilder res = new StringBuilder(s.Length);\n        foreach (var rb in rows) res.Append(rb);\n        return res.ToString();\n    }\n}","PHP":"class Solution {\n    function convert($s, $numRows) {\n        if ($numRows === 1 || $numRows >= strlen($s)) return $s;\n        $rows = array_fill(0, $numRows, \"\");\n        $row = 0; $dir = -1; $n = strlen($s);\n        for ($i = 0; $i < $n; $i++) {\n            if ($row === 0 || $row === $numRows - 1) $dir = -$dir;\n            $rows[$row] .= $s[$i];\n            $row += $dir;\n        }\n        return implode(\"\", $rows);\n    }\n}"}},{"id":"cycle-jump","name":"Direct Cycle Index Jumping","recommended":false,"coreIdeaSummary":"Visit characters directly in output row order using cycle = 2 * (numRows - 1).","coreIdea":"Each row repeats every cycle = 2 * (numRows - 1) indices. Interior rows (0 < r < numRows - 1) have one extra diagonal index at j + cycle - 2 * r.","steps":["If numRows == 1, return s.","Set cycle = 2 * (numRows - 1).","For row r from 0 to numRows - 1, step j = r, r + cycle, ...: append s[j], and if 0 < r < numRows - 1 and j + cycle - 2*r < n, also append s[j + cycle - 2*r]."],"whyItWorks":"Inside each cycle of length 2*(numRows - 1), the vertical column puts row r at offset r and the upward diagonal puts row r at offset cycle - r.","whenToUse":"When you want zero intermediate row buffers (only output storage).","complexity":{"time":"O(n)","space":"O(1) auxiliary (O(n) for output string)","variables":"n = length of s","boundType":"Worst-case"},"code":{"Java":"class Solution {\n    public String convert(String s, int numRows) {\n        if (numRows == 1 || numRows >= s.length()) return s;\n        int n = s.length(), cycle = 2 * (numRows - 1);\n        StringBuilder out = new StringBuilder(n);\n        for (int r = 0; r < numRows; r++) {\n            for (int j = r; j < n; j += cycle) {\n                out.append(s.charAt(j));\n                int diag = j + cycle - 2 * r;\n                if (r > 0 && r < numRows - 1 && diag < n) out.append(s.charAt(diag));\n            }\n        }\n        return out.toString();\n    }\n}","Python3":"class Solution:\n    def convert(self, s: str, numRows: int) -> str:\n        if numRows == 1 or numRows >= len(s):\n            return s\n        n = len(s)\n        cycle = 2 * (numRows - 1)\n        out = []\n        for r in range(numRows):\n            for j in range(r, n, cycle):\n                out.append(s[j])\n                diag = j + cycle - 2 * r\n                if 0 < r < numRows - 1 and diag < n:\n                    out.append(s[diag])\n        return ''.join(out)","Python":"class Solution(object):\n    def convert(self, s, numRows):\n        if numRows == 1 or numRows >= len(s):\n            return s\n        n = len(s)\n        cycle = 2 * (numRows - 1)\n        out = []\n        for r in range(numRows):\n            for j in range(r, n, cycle):\n                out.append(s[j])\n                diag = j + cycle - 2 * r\n                if 0 < r < numRows - 1 and diag < n:\n                    out.append(s[diag])\n        return ''.join(out)","JavaScript":"function convert(s, numRows) {\n  if (numRows === 1 || numRows >= s.length) return s;\n  const n = s.length, cycle = 2 * (numRows - 1);\n  let out = \"\";\n  for (let r = 0; r < numRows; r++) {\n    for (let j = r; j < n; j += cycle) {\n      out += s[j];\n      const diag = j + cycle - 2 * r;\n      if (r > 0 && r < numRows - 1 && diag < n) out += s[diag];\n    }\n  }\n  return out;\n}","TypeScript":"function convert(s: string, numRows: number): string {\n  if (numRows === 1 || numRows >= s.length) return s;\n  const n = s.length, cycle = 2 * (numRows - 1);\n  let out = \"\";\n  for (let r = 0; r < numRows; r++) {\n    for (let j = r; j < n; j += cycle) {\n      out += s[j];\n      const diag = j + cycle - 2 * r;\n      if (r > 0 && r < numRows - 1 && diag < n) out += s[diag];\n    }\n  }\n  return out;\n}","C#":"using System.Text;\n\npublic class Solution {\n    public string Convert(string s, int numRows) {\n        if (numRows == 1 || numRows >= s.Length) return s;\n        int n = s.Length, cycle = 2 * (numRows - 1);\n        StringBuilder outSb = new StringBuilder(n);\n        for (int r = 0; r < numRows; r++) {\n            for (int j = r; j < n; j += cycle) {\n                outSb.Append(s[j]);\n                int diag = j + cycle - 2 * r;\n                if (r > 0 && r < numRows - 1 && diag < n) outSb.Append(s[diag]);\n            }\n        }\n        return outSb.ToString();\n    }\n}","PHP":"class Solution {\n    function convert($s, $numRows) {\n        $n = strlen($s);\n        if ($numRows === 1 || $numRows >= $n) return $s;\n        $cycle = 2 * ($numRows - 1); $out = \"\";\n        for ($r = 0; $r < $numRows; $r++) {\n            for ($j = $r; $j < $n; $j += $cycle) {\n                $out .= $s[$j];\n                $diag = $j + $cycle - 2 * $r;\n                if ($r > 0 && $r < $numRows - 1 && $diag < $n) $out .= $s[$diag];\n            }\n        }\n        return $out;\n    }\n}"}}],"tests":[{"name":"Example 1","args":["INFINITY",3],"expected":"INNIIYFT"},{"name":"Example 2 (numRows=1)","args":["AB",1],"expected":"AB"},{"name":"4 rows","args":["PAYPALISHIRING",4],"expected":"PINALSIGYAHRPI"},{"name":"numRows > len","args":["HI",5],"expected":"HI"}],"javaDriver":"public class Main {\n  public static void main(String[] args) {\n    Solution s = new Solution();\n    if (!s.convert(\"INFINITY\", 3).equals(\"INNIIYFT\")) throw new AssertionError(\"Ex1\");\n    if (!s.convert(\"AB\", 1).equals(\"AB\")) throw new AssertionError(\"Ex2\");\n    if (!s.convert(\"PAYPALISHIRING\", 4).equals(\"PINALSIGYAHRPI\")) throw new AssertionError(\"Ex3\");\n    if (!s.convert(\"HI\", 5).equals(\"HI\")) throw new AssertionError(\"Ex4\");\n  }\n}","phpDriver":"$s = new Solution();\nif ($s->convert(\"INFINITY\", 3) !== \"INNIIYFT\") exit(1);\nif ($s->convert(\"AB\", 1) !== \"AB\") exit(1);\nif ($s->convert(\"PAYPALISHIRING\", 4) !== \"PINALSIGYAHRPI\") exit(1);\nif ($s->convert(\"HI\", 5) !== \"HI\") exit(1);","csharpDriver":"using System;\npublic class Runner {\n  public static void Main() {\n    var s = new Solution();\n    if (s.Convert(\"INFINITY\", 3) != \"INNIIYFT\") throw new Exception();\n    if (s.Convert(\"AB\", 1) != \"AB\") throw new Exception();\n    if (s.Convert(\"PAYPALISHIRING\", 4) != \"PINALSIGYAHRPI\") throw new Exception();\n    if (s.Convert(\"HI\", 5) != \"HI\") throw new Exception();\n  }\n}"},"data/guides/7-reverse-integer.json":{"number":7,"slug":"reverse-integer","title":"Reverse Integer","difficulty":"Medium","topics":["Math"],"access":"Free","url":"https://leetcode.com/problems/reverse-integer/","jsFunctionName":"reverse","pyMethodName":"reverse","verification":{"verifiedLanguages":["Java","Python3","Python","JavaScript","TypeScript","C#","PHP"],"untestedLanguages":[]},"understand":{"question":"Given a signed 32-bit integer, how do we flip its digits backwards while keeping its minus sign and returning 0 if the flipped value overflows 32 bits?","plainExplanation":"Peel the last digit off x using remainder (% 10) and push it onto the back of rev by multiplying rev by 10 and adding that digit. Before multiplying by 10, check whether rev is about to exceed the 32-bit signed integer limits [-2^31, 2^31 - 1].","inputMeaning":"A signed 32-bit integer x in [-2,147,483,648, 2,147,483,647].","outputMeaning":"The digit-reversed integer, or 0 if reversing x falls outside [-2,147,483,648, 2,147,483,647].","rules":["Trailing zeros disappear when reversed (for example, 420 reverses to 24).","Negative numbers stay negative (-420 reverses to -24).","If the reversed integer cannot fit in signed 32 bits [-2147483648, 2147483647], return 0."],"terms":[{"term":"Signed 32-Bit Range","definition":"Integers from INT_MIN (-2,147,483,648) up to INT_MAX (2,147,483,647)."},{"term":"Truncated Modulo / Division","definition":"Integer division toward zero (so -12 / 10 = -1 and -12 % 10 = -2 in C/Java/JS, whereas Python's // floors toward -infinity)."}],"example1":{"input":"x = -420","output":"-24","whyValid":"Popping digits from right to left yields 0, then 2, then 4 while preserving the negative sign, producing -24.","diagram":{"type":"array","items":[{"index":0,"value":"-","state":"window","label":"sign"},{"index":1,"value":"4","state":"match","label":"last popped"},{"index":2,"value":"2","state":"match","label":"2nd popped"},{"index":3,"value":"0","state":"skip","label":"drops leading 0"}],"caption":"Reading digits right-to-left gives -024 -> -24."}},"example2":{"input":"x = 1534236469","output":"0","whyEdgeCase":"Reversing 1,534,236,469 gives 9,646,324,351, which exceeds INT_MAX (2,147,483,647), so we must detect overflow BEFORE multiplying rev * 10 and return 0."}},"dryRun":{"approachId":"pop-push-guard","algorithmName":"Digit Pop & Push with Pre-Overflow Guard","steps":[{"title":"Pop 0 from -420","description":"Extract sign (-1) and work with remaining = 420. Pop digit = 0, remaining = 42, rev = 0 * 10 + 0 = 0.","state":{"type":"array","items":[{"index":0,"value":4,"state":"default"},{"index":1,"value":2,"state":"default"},{"index":2,"value":0,"state":"active","label":"pop"}],"aux":{"title":"State","entries":[{"key":"sign","value":-1},{"key":"remaining","value":42},{"key":"rev","value":0}]},"caption":"Digit 0 dropped cleanly because rev starts at 0."}},{"title":"Pop 2, then pop 4","description":"Pop 2 -> rev = 2, remaining = 4. Pop 4 -> 2 <= 214748364 (safe!) -> rev = 24, remaining = 0. Multiply by sign (-1) -> -24.","state":{"type":"array","items":[{"index":0,"value":4,"state":"match","label":"pop"},{"index":1,"value":2,"state":"match"},{"index":2,"value":0,"state":"skip"}],"aux":{"title":"Final State","entries":[{"key":"remaining","value":0},{"key":"result","value":-24,"highlight":true}]},"caption":"Apply sign -> return -24."}}]},"approaches":[{"id":"pop-push-guard","name":"Math Pop & Push with 32-bit Overflow Guard","recommended":true,"recommendedTradeOff":"Uses pure integer arithmetic in O(log10 |x|) time and O(1) space, strictly staying within 32-bit integer arithmetic without allocating strings or 64-bit types.","coreIdeaSummary":"Repeatedly pop x % 10 and check rev against INT_MAX / 10 before rev * 10 + digit.","coreIdea":"Pop digits one by one with % 10 and / 10. Before updating rev = rev * 10 + pop, verify that rev will not overflow [INT_MIN, INT_MAX].","steps":["Set rev = 0, INT_MAX = 2147483647, INT_MIN = -2147483648.","While x != 0: pop = remainder toward zero, x = truncated quotient x / 10.","If rev > INT_MAX / 10 or (rev == INT_MAX / 10 and pop > 7), return 0.","If rev < INT_MIN / 10 or (rev == INT_MIN / 10 and pop < -8), return 0.","Set rev = rev * 10 + pop and continue; return rev."],"whyItWorks":"Because INT_MAX = 2147483647 ends in 7 and INT_MIN = -2147483648 ends in -8, comparing rev against +/-214748364 catches every overflow one step before multiplication overflows.","whenToUse":"Default optimal solution, especially in strict 32-bit environments.","complexity":{"time":"O(log10 |x|)","space":"O(1)","variables":"x = input integer (at most 10 digits for 32-bit)","boundType":"Worst-case"},"code":{"Java":"class Solution {\n    public int reverse(int x) {\n        int rev = 0;\n        while (x != 0) {\n            int pop = x % 10;\n            x /= 10;\n            if (rev > Integer.MAX_VALUE / 10 || (rev == Integer.MAX_VALUE / 10 && pop > 7)) return 0;\n            if (rev < Integer.MIN_VALUE / 10 || (rev == Integer.MIN_VALUE / 10 && pop < -8)) return 0;\n            rev = rev * 10 + pop;\n        }\n        return rev;\n    }\n}","Python3":"class Solution:\n    def reverse(self, x: int) -> int:\n        sign = -1 if x < 0 else 1\n        x = abs(x)\n        rev = 0\n        limit = (2**31 - 1) if sign == 1 else 2**31\n        while x:\n            pop = x % 10\n            x //= 10\n            if rev > (limit - pop) // 10:\n                return 0\n            rev = rev * 10 + pop\n        return sign * rev","Python":"class Solution(object):\n    def reverse(self, x):\n        sign = -1 if x < 0 else 1\n        x = abs(x)\n        rev = 0\n        limit = (2**31 - 1) if sign == 1 else 2**31\n        while x:\n            pop = x % 10\n            x //= 10\n            if rev > (limit - pop) // 10:\n                return 0\n            rev = rev * 10 + pop\n        return sign * rev","JavaScript":"function reverse(x) {\n  const INT_MAX = 2147483647, INT_MIN = -2147483648;\n  let rev = 0;\n  while (x !== 0) {\n    const pop = x % 10;\n    x = Math.trunc(x / 10);\n    if (rev > Math.trunc(INT_MAX / 10) || (rev === Math.trunc(INT_MAX / 10) && pop > 7)) return 0;\n    if (rev < Math.trunc(INT_MIN / 10) || (rev === Math.trunc(INT_MIN / 10) && pop < -8)) return 0;\n    rev = rev * 10 + pop;\n  }\n  return rev;\n}","TypeScript":"function reverse(x: number): number {\n  const INT_MAX = 2147483647, INT_MIN = -2147483648;\n  let rev = 0;\n  while (x !== 0) {\n    const pop = x % 10;\n    x = Math.trunc(x / 10);\n    if (rev > Math.trunc(INT_MAX / 10) || (rev === Math.trunc(INT_MAX / 10) && pop > 7)) return 0;\n    if (rev < Math.trunc(INT_MIN / 10) || (rev === Math.trunc(INT_MIN / 10) && pop < -8)) return 0;\n    rev = rev * 10 + pop;\n  }\n  return rev;\n}","C#":"public class Solution {\n    public int Reverse(int x) {\n        int rev = 0;\n        while (x != 0) {\n            int pop = x % 10;\n            x /= 10;\n            if (rev > int.MaxValue / 10 || (rev == int.MaxValue / 10 && pop > 7)) return 0;\n            if (rev < int.MinValue / 10 || (rev == int.MinValue / 10 && pop < -8)) return 0;\n            rev = rev * 10 + pop;\n        }\n        return rev;\n    }\n}","PHP":"class Solution {\n    function reverse($x) {\n        $intMax = 2147483647; $intMin = -2147483648;\n        $rev = 0;\n        while ($x !== 0) {\n            $pop = $x % 10;\n            $x = intdiv($x, 10);\n            if ($rev > intdiv($intMax, 10) || ($rev === intdiv($intMax, 10) && $pop > 7)) return 0;\n            if ($rev < intdiv($intMin, 10) || ($rev === intdiv($intMin, 10) && $pop < -8)) return 0;\n            $rev = $rev * 10 + $pop;\n        }\n        return $rev;\n    }\n}"}},{"id":"string-reverse","name":"String Reversal with Bounds Check","recommended":false,"coreIdeaSummary":"Convert |x| to a string, reverse its characters, parse back, and clamp to 32-bit bounds.","coreIdea":"Handle the sign separately, reverse the decimal digit string, parse it safely (using 64-bit / float / big-int), and return 0 if out of [-2^31, 2^31 - 1].","steps":["Record sign = -1 if x < 0 else 1.","Convert |x| to string, reverse characters, and parse integer val = sign * int(reversedStr).","If val < -2^31 or val > 2^31 - 1, return 0; else return val."],"whyItWorks":"String reversal handles trailing zeros automatically when parsed back to an integer.","whenToUse":"Quick to write in languages with arbitrary-precision ints, though slower and uses extra string memory.","complexity":{"time":"O(log10 |x|)","space":"O(log10 |x|)","variables":"x = input integer","boundType":"Worst-case"},"code":{"Java":"class Solution {\n    public int reverse(int x) {\n        long sign = x < 0 ? -1 : 1;\n        String digits = new StringBuilder(String.valueOf(Math.abs((long) x))).reverse().toString();\n        long val = sign * Long.parseLong(digits);\n        return (val < Integer.MIN_VALUE || val > Integer.MAX_VALUE) ? 0 : (int) val;\n    }\n}","Python3":"class Solution:\n    def reverse(self, x: int) -> int:\n        sign = -1 if x < 0 else 1\n        val = sign * int(str(abs(x))[::-1])\n        return val if -2**31 <= val <= 2**31 - 1 else 0","Python":"class Solution(object):\n    def reverse(self, x):\n        sign = -1 if x < 0 else 1\n        val = sign * int(str(abs(x))[::-1])\n        return val if -(2**31) <= val <= 2**31 - 1 else 0","JavaScript":"function reverse(x) {\n  const sign = x < 0 ? -1 : 1;\n  const val = sign * Number(String(Math.abs(x)).split(\"\").reverse().join(\"\"));\n  return val < -2147483648 || val > 2147483647 ? 0 : val;\n}","TypeScript":"function reverse(x: number): number {\n  const sign = x < 0 ? -1 : 1;\n  const val = sign * Number(String(Math.abs(x)).split(\"\").reverse().join(\"\"));\n  return val < -2147483648 || val > 2147483647 ? 0 : val;\n}","C#":"using System;\n\npublic class Solution {\n    public int Reverse(int x) {\n        long sign = x < 0 ? -1 : 1;\n        char[] arr = Math.Abs((long)x).ToString().ToCharArray();\n        Array.Reverse(arr);\n        long val = sign * long.Parse(new string(arr));\n        return (val < int.MinValue || val > int.MaxValue) ? 0 : (int)val;\n    }\n}","PHP":"class Solution {\n    function reverse($x) {\n        $sign = $x < 0 ? -1 : 1;\n        $val = $sign * intval(strrev((string)abs($x)));\n        return ($val < -2147483648 || $val > 2147483647) ? 0 : $val;\n    }\n}"}}],"tests":[{"name":"Example 1","args":[-420],"expected":-24},{"name":"Example 2 (overflow)","args":[1534236469],"expected":0},{"name":"Zero","args":[0],"expected":0},{"name":"Negative overflow","args":[-2147483648],"expected":0}],"javaDriver":"public class Main {\n  public static void main(String[] args) {\n    Solution s = new Solution();\n    if (s.reverse(-420) != -24) throw new AssertionError();\n    if (s.reverse(1534236469) != 0) throw new AssertionError();\n    if (s.reverse(0) != 0) throw new AssertionError();\n    if (s.reverse(-2147483648) != 0) throw new AssertionError();\n  }\n}","phpDriver":"$s = new Solution();\nif ($s->reverse(-420) !== -24) exit(1);\nif ($s->reverse(1534236469) !== 0) exit(1);\nif ($s->reverse(0) !== 0) exit(1);\nif ($s->reverse(-2147483648) !== 0) exit(1);","csharpDriver":"using System;\npublic class Runner {\n  public static void Main() {\n    var s = new Solution();\n    if (s.Reverse(-420) != -24) throw new Exception();\n    if (s.Reverse(1534236469) != 0) throw new Exception();\n    if (s.Reverse(0) != 0) throw new Exception();\n    if (s.Reverse(-2147483648) != 0) throw new Exception();\n  }\n}"},"data/guides/8-string-to-integer-atoi.json":{"number":8,"slug":"string-to-integer-atoi","title":"String to Integer (atoi)","difficulty":"Medium","topics":["String"],"access":"Free","url":"https://leetcode.com/problems/string-to-integer-atoi/","jsFunctionName":"myAtoi","pyMethodName":"myAtoi","verification":{"verifiedLanguages":["Java","Python3","Python","JavaScript","TypeScript","C#","PHP"],"untestedLanguages":[]},"understand":{"question":"Given a messy text string, how do we parse a leading signed integer while skipping leading spaces, reading at most one '+' or '-', stopping at the first non-digit, and clamping to 32-bit bounds?","plainExplanation":"Think of a strict form-field parser walking left to right: first ignore leading spaces, then check for a single optional '+' or '-', then consume consecutive digits 0-9 until a non-digit appears, and finally clamp huge numbers to [-2^31, 2^31 - 1].","inputMeaning":"Any string s containing spaces, signs, digits, or letters.","outputMeaning":"The parsed integer clamped into [-2,147,483,648, 2,147,483,647], or 0 if no valid digits start after spaces/sign.","rules":["Only leading spaces (' ') are skipped — once a sign or digit starts, spaces stop parsing too.","Only one optional '+' or '-' is allowed; two signs like '+-4' stops immediately and returns 0.","Unlike Reverse Integer (#7), out-of-range values are CLAMPED to INT_MIN or INT_MAX rather than returning 0."],"terms":[{"term":"Clamping","definition":"Capping a value at the nearest boundary: anything > 2,147,483,647 becomes 2,147,483,647, and anything < -2,147,483,648 becomes -2,147,483,648."},{"term":"DFA (Deterministic Finite Automaton)","definition":"A small state machine (start -> signed -> in_number -> end) where each character type triggers a predictable transition."}],"example1":{"input":"s = \"   -042abc\"","output":"-42","whyValid":"Skip the 3 leading spaces, read '-' (sign = -1), skip/absorb leading 0, read '4' and '2' (value = 42), then stop as soon as 'a' appears. Final answer: -42.","diagram":{"type":"array","items":[{"index":0,"value":" ","state":"skip","label":"space"},{"index":1,"value":" ","state":"skip","label":"space"},{"index":2,"value":" ","state":"skip","label":"space"},{"index":3,"value":"-","state":"window","label":"sign=-1"},{"index":4,"value":"0","state":"match","label":"digit"},{"index":5,"value":"4","state":"match","label":"digit"},{"index":6,"value":"2","state":"match","label":"digit"},{"index":7,"value":"a","state":"skip","label":"stop!"}],"pointers":[{"index":7,"name":"halt"}],"caption":"Result after stopping at 'a': -42."}},"example2":{"input":"s = \"-91283472332\"","output":"-2147483648","whyEdgeCase":"Massive negative number! Instead of wrapping around or returning 0, myAtoi must clamp at INT_MIN (-2,147,483,648)."}},"dryRun":{"approachId":"single-pass-scan","algorithmName":"Single-Pass Scanner with Clamping Guard","steps":[{"title":"Skip leading whitespace (indices 0..2)","description":"Advance pointer i past all leading ' ' characters until landing on '-' at index 3.","state":{"type":"array","items":[{"index":0,"value":"_","state":"skip"},{"index":1,"value":"_","state":"skip"},{"index":2,"value":"_","state":"skip"},{"index":3,"value":"-","state":"active"},{"index":4,"value":"0","state":"default"},{"index":5,"value":"4","state":"default"},{"index":6,"value":"2","state":"default"},{"index":7,"value":"a","state":"default"}],"pointers":[{"index":3,"name":"i"}],"aux":{"title":"Parser State","entries":[{"key":"sign","value":1},{"key":"acc","value":0}]},"caption":"Spaces skipped; ready to check optional sign."}},{"title":"Consume sign '-' and digits 0, 4, 2","description":"Read '-' so sign = -1 and i = 4. Then read '0' -> acc = 0, '4' -> acc = 4, '2' -> acc = 42. All are safely below INT_MAX / 10.","state":{"type":"array","items":[{"index":0,"value":"_","state":"skip"},{"index":1,"value":"_","state":"skip"},{"index":2,"value":"_","state":"skip"},{"index":3,"value":"-","state":"window"},{"index":4,"value":"0","state":"match"},{"index":5,"value":"4","state":"match"},{"index":6,"value":"2","state":"match"},{"index":7,"value":"a","state":"active"}],"pointers":[{"index":7,"name":"i"}],"aux":{"title":"Parser State","entries":[{"key":"sign","value":-1},{"key":"acc","value":42,"highlight":true}]},"caption":"'a' is not a digit: stop and return -42."}}]},"approaches":[{"id":"single-pass-scan","name":"Single-Pass Pointer Scan with Pre-Overflow Guard","recommended":true,"recommendedTradeOff":"Scans left-to-right in O(n) time and O(1) space while catching 32-bit overflow before multiplication so it works identically in 32-bit and 64-bit languages.","coreIdeaSummary":"Advance one index through spaces -> optional sign -> digits, clamping before overflow.","coreIdea":"Walk index i sequentially: first skip spaces, then read at most one sign, then accumulate digits checking acc > floor((INT_MAX - digit) / 10).","steps":["Advance i while i < n and s[i] == ' '.","Check s[i] for '+' or '-' to set sign (+1 or -1) and advance i by 1.","While i < n and s[i] is '0'..'9': if acc > (INT_MAX - d) / 10, return (sign == 1 ? INT_MAX : INT_MIN); else acc = acc * 10 + d.","Return sign * acc."],"whyItWorks":"Checking acc > (2147483647 - d) / 10 guarantees acc * 10 + d never overflows 32 bits; if acc reaches 214748364 with d = 8 or 9 when sign == -1, returning INT_MIN (-2147483648) is exact!","whenToUse":"Default clean production implementation.","complexity":{"time":"O(n)","space":"O(1)","variables":"n = length of s","boundType":"Worst-case"},"code":{"Java":"class Solution {\n    public int myAtoi(String s) {\n        int n = s.length(), i = 0, sign = 1, acc = 0;\n        while (i < n && s.charAt(i) == ' ') i++;\n        if (i < n && (s.charAt(i) == '+' || s.charAt(i) == '-')) {\n            sign = (s.charAt(i++) == '-') ? -1 : 1;\n        }\n        while (i < n && Character.isDigit(s.charAt(i))) {\n            int d = s.charAt(i++) - '0';\n            if (acc > (Integer.MAX_VALUE - d) / 10) {\n                return (sign == 1) ? Integer.MAX_VALUE : Integer.MIN_VALUE;\n            }\n            acc = acc * 10 + d;\n        }\n        return sign * acc;\n    }\n}","Python3":"class Solution:\n    def myAtoi(self, s: str) -> int:\n        n, i, sign, acc = len(s), 0, 1, 0\n        INT_MAX, INT_MIN = 2**31 - 1, -(2**31)\n        while i < n and s[i] == ' ':\n            i += 1\n        if i < n and s[i] in ('+', '-'):\n            sign = -1 if s[i] == '-' else 1\n            i += 1\n        while i < n and '0' <= s[i] <= '9':\n            d = ord(s[i]) - ord('0')\n            if acc > (INT_MAX - d) // 10:\n                return INT_MAX if sign == 1 else INT_MIN\n            acc = acc * 10 + d\n            i += 1\n        return sign * acc","Python":"class Solution(object):\n    def myAtoi(self, s):\n        n, i, sign, acc = len(s), 0, 1, 0\n        INT_MAX, INT_MIN = 2**31 - 1, -(2**31)\n        while i < n and s[i] == ' ':\n            i += 1\n        if i < n and s[i] in ('+', '-'):\n            sign = -1 if s[i] == '-' else 1\n            i += 1\n        while i < n and '0' <= s[i] <= '9':\n            d = ord(s[i]) - ord('0')\n            if acc > (INT_MAX - d) // 10:\n                return INT_MAX if sign == 1 else INT_MIN\n            acc = acc * 10 + d\n            i += 1\n        return sign * acc","JavaScript":"function myAtoi(s) {\n  const INT_MAX = 2147483647, INT_MIN = -2147483648;\n  let i = 0, sign = 1, acc = 0;\n  while (i < s.length && s[i] === ' ') i++;\n  if (i < s.length && (s[i] === '+' || s[i] === '-')) {\n    sign = s[i++] === '-' ? -1 : 1;\n  }\n  while (i < s.length && s[i] >= '0' && s[i] <= '9') {\n    const d = s.charCodeAt(i++) - 48;\n    if (acc > Math.floor((INT_MAX - d) / 10)) {\n      return sign === 1 ? INT_MAX : INT_MIN;\n    }\n    acc = acc * 10 + d;\n  }\n  return sign * acc;\n}","TypeScript":"function myAtoi(s: string): number {\n  const INT_MAX = 2147483647, INT_MIN = -2147483648;\n  let i = 0, sign = 1, acc = 0;\n  while (i < s.length && s[i] === ' ') i++;\n  if (i < s.length && (s[i] === '+' || s[i] === '-')) {\n    sign = s[i++] === '-' ? -1 : 1;\n  }\n  while (i < s.length && s[i] >= '0' && s[i] <= '9') {\n    const d = s.charCodeAt(i++) - 48;\n    if (acc > Math.floor((INT_MAX - d) / 10)) {\n      return sign === 1 ? INT_MAX : INT_MIN;\n    }\n    acc = acc * 10 + d;\n  }\n  return sign * acc;\n}","C#":"public class Solution {\n    public int MyAtoi(string s) {\n        int n = s.Length, i = 0, sign = 1, acc = 0;\n        while (i < n && s[i] == ' ') i++;\n        if (i < n && (s[i] == '+' || s[i] == '-')) {\n            sign = (s[i++] == '-') ? -1 : 1;\n        }\n        while (i < n && s[i] >= '0' && s[i] <= '9') {\n            int d = s[i++] - '0';\n            if (acc > (int.MaxValue - d) / 10) {\n                return (sign == 1) ? int.MaxValue : int.MinValue;\n            }\n            acc = acc * 10 + d;\n        }\n        return sign * acc;\n    }\n}","PHP":"class Solution {\n    function myAtoi($s) {\n        $intMax = 2147483647; $intMin = -2147483648;\n        $n = strlen($s); $i = 0; $sign = 1; $acc = 0;\n        while ($i < $n && $s[$i] === ' ') $i++;\n        if ($i < $n && ($s[$i] === '+' || $s[$i] === '-')) {\n            $sign = ($s[$i++] === '-') ? -1 : 1;\n        }\n        while ($i < $n && $s[$i] >= '0' && $s[$i] <= '9') {\n            $d = ord($s[$i++]) - 48;\n            if ($acc > intdiv($intMax - $d, 10)) {\n                return ($sign === 1) ? $intMax : $intMin;\n            }\n            $acc = $acc * 10 + $d;\n        }\n        return $sign * $acc;\n    }\n}"}},{"id":"dfa-machine","name":"Explicit Deterministic Finite Automaton (DFA)","recommended":false,"coreIdeaSummary":"Model parsing as formal state transitions: START -> SIGNED / IN_NUMBER -> END.","coreIdea":"Define explicit states and a transition table mapping (currentState, charKind) to nextState so every edge case is handled cleanly by table lookup.","steps":["Define states: 0=START, 1=SIGNED, 2=IN_NUMBER, 3=END.","Classify each character into space, sign, digit, or other.","Transition using the DFA table; on SIGNED update sign, on IN_NUMBER accumulate + clamp, on END break immediately."],"whyItWorks":"Separating state transitions from value accumulation prevents accidental fall-through bugs like accepting a second sign.","whenToUse":"Great when writing industrial parsers with many character classes or explaining finite-state machines.","complexity":{"time":"O(n)","space":"O(1)","variables":"n = length of s","boundType":"Worst-case"},"code":{"Java":"class Solution {\n    public int myAtoi(String s) {\n        int[][] table = {{0,1,2,3},{3,3,2,3},{3,3,2,3},{3,3,3,3}};\n        int state = 0, sign = 1, acc = 0;\n        for (int i = 0; i < s.length(); i++) {\n            char c = s.charAt(i);\n            int col = (c == ' ') ? 0 : (c == '+' || c == '-') ? 1 : Character.isDigit(c) ? 2 : 3;\n            state = table[state][col];\n            if (state == 3) break;\n            if (state == 1 && c == '-') sign = -1;\n            if (state == 2) {\n                int d = c - '0';\n                if (acc > (Integer.MAX_VALUE - d) / 10) return sign == 1 ? Integer.MAX_VALUE : Integer.MIN_VALUE;\n                acc = acc * 10 + d;\n            }\n        }\n        return sign * acc;\n    }\n}","Python3":"class Solution:\n    def myAtoi(self, s: str) -> int:\n        table = [[0,1,2,3],[3,3,2,3],[3,3,2,3],[3,3,3,3]]\n        state, sign, acc = 0, 1, 0\n        INT_MAX, INT_MIN = 2**31 - 1, -(2**31)\n        for c in s:\n            col = 0 if c == ' ' else 1 if c in '+-' else 2 if '0' <= c <= '9' else 3\n            state = table[state][col]\n            if state == 3:\n                break\n            if state == 1 and c == '-':\n                sign = -1\n            elif state == 2:\n                d = ord(c) - 48\n                if acc > (INT_MAX - d) // 10:\n                    return INT_MAX if sign == 1 else INT_MIN\n                acc = acc * 10 + d\n        return sign * acc","Python":"class Solution(object):\n    def myAtoi(self, s):\n        table = [[0,1,2,3],[3,3,2,3],[3,3,2,3],[3,3,3,3]]\n        state, sign, acc = 0, 1, 0\n        INT_MAX, INT_MIN = 2**31 - 1, -(2**31)\n        for c in s:\n            col = 0 if c == ' ' else 1 if c in '+-' else 2 if '0' <= c <= '9' else 3\n            state = table[state][col]\n            if state == 3:\n                break\n            if state == 1 and c == '-':\n                sign = -1\n            elif state == 2:\n                d = ord(c) - 48\n                if acc > (INT_MAX - d) // 10:\n                    return INT_MAX if sign == 1 else INT_MIN\n                acc = acc * 10 + d\n        return sign * acc","JavaScript":"function myAtoi(s) {\n  const table = [[0,1,2,3],[3,3,2,3],[3,3,2,3],[3,3,3,3]];\n  const INT_MAX = 2147483647, INT_MIN = -2147483648;\n  let state = 0, sign = 1, acc = 0;\n  for (const c of s) {\n    const col = c === ' ' ? 0 : (c === '+' || c === '-') ? 1 : (c >= '0' && c <= '9') ? 2 : 3;\n    state = table[state][col];\n    if (state === 3) break;\n    if (state === 1 && c === '-') sign = -1;\n    if (state === 2) {\n      const d = c.charCodeAt(0) - 48;\n      if (acc > Math.floor((INT_MAX - d) / 10)) return sign === 1 ? INT_MAX : INT_MIN;\n      acc = acc * 10 + d;\n    }\n  }\n  return sign * acc;\n}","TypeScript":"function myAtoi(s: string): number {\n  const table = [[0,1,2,3],[3,3,2,3],[3,3,2,3],[3,3,3,3]];\n  const INT_MAX = 2147483647, INT_MIN = -2147483648;\n  let state = 0, sign = 1, acc = 0;\n  for (const c of s) {\n    const col = c === ' ' ? 0 : (c === '+' || c === '-') ? 1 : (c >= '0' && c <= '9') ? 2 : 3;\n    state = table[state][col];\n    if (state === 3) break;\n    if (state === 1 && c === '-') sign = -1;\n    if (state === 2) {\n      const d = c.charCodeAt(0) - 48;\n      if (acc > Math.floor((INT_MAX - d) / 10)) return sign === 1 ? INT_MAX : INT_MIN;\n      acc = acc * 10 + d;\n    }\n  }\n  return sign * acc;\n}","C#":"public class Solution {\n    public int MyAtoi(string s) {\n        int[,] table = {{0,1,2,3},{3,3,2,3},{3,3,2,3},{3,3,3,3}};\n        int state = 0, sign = 1, acc = 0;\n        foreach (char c in s) {\n            int col = (c == ' ') ? 0 : (c == '+' || c == '-') ? 1 : (c >= '0' && c <= '9') ? 2 : 3;\n            state = table[state, col];\n            if (state == 3) break;\n            if (state == 1 && c == '-') sign = -1;\n            if (state == 2) {\n                int d = c - '0';\n                if (acc > (int.MaxValue - d) / 10) return sign == 1 ? int.MaxValue : int.MinValue;\n                acc = acc * 10 + d;\n            }\n        }\n        return sign * acc;\n    }\n}","PHP":"class Solution {\n    function myAtoi($s) {\n        $table = [[0,1,2,3],[3,3,2,3],[3,3,2,3],[3,3,3,3]];\n        $intMax = 2147483647; $intMin = -2147483648;\n        $state = 0; $sign = 1; $acc = 0; $n = strlen($s);\n        for ($i = 0; $i < $n; $i++) {\n            $c = $s[$i];\n            $col = ($c === ' ') ? 0 : (($c === '+' || $c === '-') ? 1 : (($c >= '0' && $c <= '9') ? 2 : 3));\n            $state = $table[$state][$col];\n            if ($state === 3) break;\n            if ($state === 1 && $c === '-') $sign = -1;\n            if ($state === 2) {\n                $d = ord($c) - 48;\n                if ($acc > intdiv($intMax - $d, 10)) return ($sign === 1) ? $intMax : $intMin;\n                $acc = $acc * 10 + $d;\n            }\n        }\n        return $sign * $acc;\n    }\n}"}}],"tests":[{"name":"Example 1","args":["   -042abc"],"expected":-42},{"name":"Example 2 (clamp min)","args":["-91283472332"],"expected":-2147483648},{"name":"Double sign","args":["+-12"],"expected":0},{"name":"Clamp max","args":["9999999999"],"expected":2147483647}],"javaDriver":"public class Main {\n  public static void main(String[] args) {\n    Solution s = new Solution();\n    if (s.myAtoi(\"   -042abc\") != -42) throw new AssertionError();\n    if (s.myAtoi(\"-91283472332\") != -2147483648) throw new AssertionError();\n    if (s.myAtoi(\"+-12\") != 0) throw new AssertionError();\n    if (s.myAtoi(\"9999999999\") != 2147483647) throw new AssertionError();\n  }\n}","phpDriver":"$s = new Solution();\nif ($s->myAtoi(\"   -042abc\") !== -42) exit(1);\nif ($s->myAtoi(\"-91283472332\") !== -2147483648) exit(1);\nif ($s->myAtoi(\"+-12\") !== 0) exit(1);\nif ($s->myAtoi(\"9999999999\") !== 2147483647) exit(1);","csharpDriver":"using System;\npublic class Runner {\n  public static void Main() {\n    var s = new Solution();\n    if (s.MyAtoi(\"   -042abc\") != -42) throw new Exception();\n    if (s.MyAtoi(\"-91283472332\") != -2147483648) throw new Exception();\n    if (s.MyAtoi(\"+-12\") != 0) throw new Exception();\n    if (s.MyAtoi(\"9999999999\") != 2147483647) throw new Exception();\n  }\n}"},"data/guides/9-palindrome-number.json":{"number":9,"slug":"palindrome-number","title":"Palindrome Number","difficulty":"Easy","topics":["Math"],"access":"Free","url":"https://leetcode.com/problems/palindrome-number/","jsFunctionName":"isPalindrome","pyMethodName":"isPalindrome","verification":{"verifiedLanguages":["Java","Python3","Python","JavaScript","TypeScript","C#","PHP"],"untestedLanguages":[]},"understand":{"question":"Given an integer x, how do we check whether its decimal digits read identically forwards and backwards — ideally without converting x to a string?","plainExplanation":"Negative numbers like -121 cannot be palindromes because the minus sign is only on the left. For positive numbers, if you reverse only the RIGHT half of the digits until the reversed half catches up to the remaining left half, both halves will match!","inputMeaning":"A 32-bit signed integer x.","outputMeaning":"true if x is a palindrome, otherwise false.","rules":["All negative numbers (x < 0) are false because '-' has no matching '-' on the right.","Any positive number ending in 0 (like 10 or 120) cannot be a palindrome because no non-zero number starts with 0; only 0 itself is a palindrome.","Reversing only half of the digits completely avoids integer overflow."],"terms":[{"term":"Half-Reversal","definition":"Building reversedRight from the rightmost digits while shrinking x from the right until x <= reversedRight."},{"term":"Middle Digit","definition":"In odd-digit numbers like 12321, the center digit 3 lands at the end of reversedRight (123 vs 12), so comparing x == reversedRight / 10 ignores it."}],"example1":{"input":"x = 12321","output":"true","whyValid":"Digits mirror around the middle 3: 1 matches 1, and 2 matches 2.","diagram":{"type":"array","items":[{"index":0,"value":1,"state":"match","label":"left"},{"index":1,"value":2,"state":"match","label":"left"},{"index":2,"value":3,"state":"window","label":"middle"},{"index":3,"value":2,"state":"match","label":"right"},{"index":4,"value":1,"state":"match","label":"right"}],"caption":"12 == floor(123 / 10) -> palindrome!"}},"example2":{"input":"x = 10","output":"false","whyEdgeCase":"Trailing zero trap! If we did not reject x % 10 == 0 (for x != 0) upfront, half-reversal on x = 10 would reach x = 0 and rev = 1, where x == floor(rev / 10) (0 == 0) would falsely return true."}},"dryRun":{"approachId":"reverse-half","algorithmName":"Reverse Half of Digits","steps":[{"title":"Check guards and pop 1st digit (1)","description":"12321 >= 0 and does not end in 0. Pop 1 -> x = 1232, rev = 1. Still x > rev.","state":{"type":"array","items":[{"index":0,"value":1,"state":"default"},{"index":1,"value":2,"state":"default"},{"index":2,"value":3,"state":"default"},{"index":3,"value":2,"state":"default"},{"index":4,"value":1,"state":"active","label":"popped"}],"aux":{"title":"Halves","entries":[{"key":"x","value":1232},{"key":"rev","value":1}]},"caption":"Continue while x > rev."}},{"title":"Pop 2 and 3 until x <= rev","description":"Pop 2 -> x = 123, rev = 12. Pop 3 -> x = 12, rev = 123. Now x <= rev so stop! Since 12 == floor(123 / 10), return true.","state":{"type":"array","items":[{"index":0,"value":1,"state":"match"},{"index":1,"value":2,"state":"match"},{"index":2,"value":3,"state":"window","label":"middle"},{"index":3,"value":2,"state":"match"},{"index":4,"value":1,"state":"match"}],"aux":{"title":"Final Comparison","entries":[{"key":"x","value":12},{"key":"rev","value":123},{"key":"x == rev//10","value":"true","highlight":true}]},"caption":"Half-reversal matches! Return true."}}]},"approaches":[{"id":"reverse-half","name":"Reverse Half of Digits","recommended":true,"recommendedTradeOff":"Runs in O(log10 n) time with O(1) extra space, converts no strings, and never overflows 32-bit integers.","coreIdeaSummary":"Reverse digits into rev until x <= rev, then check x == rev or x == rev / 10.","coreIdea":"Reject negative numbers and non-zero multiples of 10 immediately. Then peel digits from x into rev until x <= rev.","steps":["If x < 0 or (x % 10 == 0 and x != 0), return false.","Initialize rev = 0. While x > rev: rev = rev * 10 + x % 10; x = floor(x / 10).","Return x == rev or x == floor(rev / 10)."],"whyItWorks":"Stopping when x <= rev guarantees we split even-length numbers in half (x == rev) and odd-length numbers with the middle digit at the end of rev (x == rev / 10).","whenToUse":"Default optimal solution.","complexity":{"time":"O(log10 n)","space":"O(1)","variables":"n = |x| (number of decimal digits is ~log10 n)","boundType":"Worst-case"},"code":{"Java":"class Solution {\n    public boolean isPalindrome(int x) {\n        if (x < 0 || (x % 10 == 0 && x != 0)) return false;\n        int rev = 0;\n        while (x > rev) {\n            rev = rev * 10 + x % 10;\n            x /= 10;\n        }\n        return x == rev || x == rev / 10;\n    }\n}","Python3":"class Solution:\n    def isPalindrome(self, x: int) -> bool:\n        if x < 0 or (x % 10 == 0 and x != 0):\n            return False\n        rev = 0\n        while x > rev:\n            rev = rev * 10 + x % 10\n            x //= 10\n        return x == rev or x == rev // 10","Python":"class Solution(object):\n    def isPalindrome(self, x):\n        if x < 0 or (x % 10 == 0 and x != 0):\n            return False\n        rev = 0\n        while x > rev:\n            rev = rev * 10 + x % 10\n            x //= 10\n        return x == rev or x == rev // 10","JavaScript":"function isPalindrome(x) {\n  if (x < 0 || (x % 10 === 0 && x !== 0)) return false;\n  let rev = 0;\n  while (x > rev) {\n    rev = rev * 10 + (x % 10);\n    x = Math.floor(x / 10);\n  }\n  return x === rev || x === Math.floor(rev / 10);\n}","TypeScript":"function isPalindrome(x: number): boolean {\n  if (x < 0 || (x % 10 === 0 && x !== 0)) return false;\n  let rev = 0;\n  while (x > rev) {\n    rev = rev * 10 + (x % 10);\n    x = Math.floor(x / 10);\n  }\n  return x === rev || x === Math.floor(rev / 10);\n}","C#":"public class Solution {\n    public bool IsPalindrome(int x) {\n        if (x < 0 || (x % 10 == 0 && x != 0)) return false;\n        int rev = 0;\n        while (x > rev) {\n            rev = rev * 10 + x % 10;\n            x /= 10;\n        }\n        return x == rev || x == rev / 10;\n    }\n}","PHP":"class Solution {\n    function isPalindrome($x) {\n        if ($x < 0 || ($x % 10 === 0 && $x !== 0)) return false;\n        $rev = 0;\n        while ($x > $rev) {\n            $rev = $rev * 10 + ($x % 10);\n            $x = intdiv($x, 10);\n        }\n        return $x === $rev || $x === intdiv($rev, 10);\n    }\n}"}},{"id":"string-two-pointers","name":"String Conversion + Two Pointers","recommended":false,"coreIdeaSummary":"Convert x to a string and compare characters inward from both ends.","coreIdea":"Turn x into text and verify s[left] == s[right] as left and right move toward the center.","steps":["If x < 0, return false.","Convert x to string s.","Use two pointers l = 0, r = len(s) - 1; return false if s[l] != s[r], otherwise return true."],"whyItWorks":"Characters of str(x) directly mirror the decimal digits in order.","whenToUse":"Readable alternative when O(log10 n) string allocation is acceptable.","complexity":{"time":"O(log10 n)","space":"O(log10 n)","variables":"n = |x|","boundType":"Worst-case"},"code":{"Java":"class Solution {\n    public boolean isPalindrome(int x) {\n        if (x < 0) return false;\n        String s = String.valueOf(x);\n        int l = 0, r = s.length() - 1;\n        while (l < r) if (s.charAt(l++) != s.charAt(r--)) return false;\n        return true;\n    }\n}","Python3":"class Solution:\n    def isPalindrome(self, x: int) -> bool:\n        if x < 0:\n            return False\n        s = str(x)\n        return s == s[::-1]","Python":"class Solution(object):\n    def isPalindrome(self, x):\n        if x < 0:\n            return False\n        s = str(x)\n        return s == s[::-1]","JavaScript":"function isPalindrome(x) {\n  if (x < 0) return false;\n  const s = String(x);\n  let l = 0, r = s.length - 1;\n  while (l < r) if (s[l++] !== s[r--]) return false;\n  return true;\n}","TypeScript":"function isPalindrome(x: number): boolean {\n  if (x < 0) return false;\n  const s = String(x);\n  let l = 0, r = s.length - 1;\n  while (l < r) if (s[l++] !== s[r--]) return false;\n  return true;\n}","C#":"public class Solution {\n    public bool IsPalindrome(int x) {\n        if (x < 0) return false;\n        string s = x.ToString();\n        int l = 0, r = s.Length - 1;\n        while (l < r) if (s[l++] != s[r--]) return false;\n        return true;\n    }\n}","PHP":"class Solution {\n    function isPalindrome($x) {\n        if ($x < 0) return false;\n        $s = (string)$x;\n        return $s === strrev($s);\n    }\n}"}},{"id":"full-reverse-long","name":"Full Reversal in 64-Bit Integer","recommended":false,"coreIdeaSummary":"Reverse every digit into a 64-bit integer and compare with the original x.","coreIdea":"For x >= 0, reverse all digits using a 64-bit accumulator so overflow cannot happen, then check rev == x.","steps":["If x < 0, return false.","Copy orig = x, rev = 0 (64-bit). While x > 0: rev = rev * 10 + x % 10; x /= 10.","Return rev == orig."],"whyItWorks":"Any 10-digit reversed 32-bit integer easily fits inside a 64-bit signed integer.","whenToUse":"Simple math implementation when 64-bit integers are available.","complexity":{"time":"O(log10 n)","space":"O(1)","variables":"n = |x|","boundType":"Worst-case"},"code":{"Java":"class Solution {\n    public boolean isPalindrome(int x) {\n        if (x < 0) return false;\n        long orig = x, rev = 0;\n        while (x > 0) {\n            rev = rev * 10 + x % 10;\n            x /= 10;\n        }\n        return rev == orig;\n    }\n}","Python3":"class Solution:\n    def isPalindrome(self, x: int) -> bool:\n        if x < 0:\n            return False\n        orig, rev = x, 0\n        while x > 0:\n            rev = rev * 10 + x % 10\n            x //= 10\n        return rev == orig","Python":"class Solution(object):\n    def isPalindrome(self, x):\n        if x < 0:\n            return False\n        orig, rev = x, 0\n        while x > 0:\n            rev = rev * 10 + x % 10\n            x //= 10\n        return rev == orig","JavaScript":"function isPalindrome(x) {\n  if (x < 0) return false;\n  let orig = x, rev = 0;\n  while (x > 0) {\n    rev = rev * 10 + (x % 10);\n    x = Math.floor(x / 10);\n  }\n  return rev === orig;\n}","TypeScript":"function isPalindrome(x: number): boolean {\n  if (x < 0) return false;\n  let orig = x, rev = 0;\n  while (x > 0) {\n    rev = rev * 10 + (x % 10);\n    x = Math.floor(x / 10);\n  }\n  return rev === orig;\n}","C#":"public class Solution {\n    public bool IsPalindrome(int x) {\n        if (x < 0) return false;\n        long orig = x, rev = 0;\n        while (x > 0) {\n            rev = rev * 10 + x % 10;\n            x /= 10;\n        }\n        return rev == orig;\n    }\n}","PHP":"class Solution {\n    function isPalindrome($x) {\n        if ($x < 0) return false;\n        $orig = $x; $rev = 0;\n        while ($x > 0) {\n            $rev = $rev * 10 + ($x % 10);\n            $x = intdiv($x, 10);\n        }\n        return $rev === $orig;\n    }\n}"}}],"tests":[{"name":"Example 1 (odd palindrome)","args":[12321],"expected":true},{"name":"Example 2 (trailing zero)","args":[10],"expected":false},{"name":"Zero","args":[0],"expected":true},{"name":"Negative","args":[-121],"expected":false}],"javaDriver":"public class Main {\n  public static void main(String[] args) {\n    Solution s = new Solution();\n    if (!s.isPalindrome(12321)) throw new AssertionError();\n    if (s.isPalindrome(10)) throw new AssertionError();\n    if (!s.isPalindrome(0)) throw new AssertionError();\n    if (s.isPalindrome(-121)) throw new AssertionError();\n  }\n}","phpDriver":"$s = new Solution();\nif ($s->isPalindrome(12321) !== true) exit(1);\nif ($s->isPalindrome(10) !== false) exit(1);\nif ($s->isPalindrome(0) !== true) exit(1);\nif ($s->isPalindrome(-121) !== false) exit(1);","csharpDriver":"using System;\npublic class Runner {\n  public static void Main() {\n    var s = new Solution();\n    if (!s.IsPalindrome(12321)) throw new Exception();\n    if (s.IsPalindrome(10)) throw new Exception();\n    if (!s.IsPalindrome(0)) throw new Exception();\n    if (s.IsPalindrome(-121)) throw new Exception();\n  }\n}"},"data/guides/53-maximum-subarray.json":{"number":53,"slug":"maximum-subarray","title":"Maximum Subarray","difficulty":"Medium","topics":["Array","Divide and Conquer","Dynamic Programming"],"access":"Free","url":"https://leetcode.com/problems/maximum-subarray/","jsFunctionName":"maxSubArray","pyMethodName":"maxSubArray","verification":{"verifiedLanguages":["Java","Python3","Python","JavaScript","TypeScript","C#","PHP"],"untestedLanguages":["C++","C","Go","Kotlin","Swift","Rust","Ruby","Dart","Scala","Elixir","Erlang","Racket"]},"understand":{"question":"Given an array of integers (which may include negatives and zero), what is the largest total sum you can get from a non-empty contiguous slice?","plainExplanation":"Think of daily profit-and-loss numbers for a shop. You want to pick one unbroken stretch of consecutive days (at least one day long) whose combined profit is as large as possible.","inputMeaning":"A non-empty integer array nums (for example [-2, 5, -1, 4, -6, 2]).","outputMeaning":"A single integer: the maximum sum of any contiguous subarray of length >= 1.","rules":["The chosen elements must be contiguous (adjacent in the original array without skipping elements in the middle).","The subarray must be non-empty (at least one element must be selected, even if every number in the array is negative).","You only return the maximum sum value, not the slice indices."],"terms":[{"term":"Subarray","definition":"A contiguous slice nums[left..right] with 0 <= left <= right < n. Unlike a subsequence, you cannot skip elements inside the slice."},{"term":"Local Best (currentSum)","definition":"The largest sum of a subarray that MUST end at the current index i."},{"term":"Global Best (bestSum)","definition":"The largest subarray sum seen across all ending indices processed so far."}],"example1":{"input":"nums = [-2, 5, -1, 4, -6, 2]","output":"8","whyValid":"The contiguous slice [5, -1, 4] from index 1 through index 3 sums to 5 + (-1) + 4 = 8. Including index 0 (-2) lowers it to 6, and extending to index 4 (-6) drops it to 2.","diagram":{"type":"array","items":[{"index":0,"value":-2,"state":"skip"},{"index":1,"value":5,"state":"match","label":"start"},{"index":2,"value":-1,"state":"match","label":"bridge"},{"index":3,"value":4,"state":"match","label":"end"},{"index":4,"value":-6,"state":"skip"},{"index":5,"value":2,"state":"default"}],"pointers":[{"index":1,"name":"L"},{"index":3,"name":"R"}],"caption":"Best contiguous subarray [5, -1, 4] has sum 8."}},"example2":{"input":"nums = [-7, -2, -9, -4]","output":"-2","whyEdgeCase":"All numbers are negative! Because the subarray must be non-empty, you cannot return 0 by picking nothing. The least-negative single element [-2] gives the maximum sum -2."}},"dryRun":{"approachId":"kadane","algorithmName":"Kadane's Algorithm","steps":[{"title":"Start at index 0 with nums[0]","description":"Initialize currentSum = -2 and bestSum = -2 using the first element (never 0, so all-negative inputs work).","state":{"type":"array","items":[{"index":0,"value":-2,"state":"active"},{"index":1,"value":5,"state":"default"},{"index":2,"value":-1,"state":"default"},{"index":3,"value":4,"state":"default"},{"index":4,"value":-6,"state":"default"},{"index":5,"value":2,"state":"default"}],"pointers":[{"index":0,"name":"i"}],"aux":{"title":"Kadane State","entries":[{"key":"currentSum","value":-2},{"key":"bestSum","value":-2,"highlight":true}]},"caption":"Initial window is [-2]."}},{"title":"Index 1 (value 5): restart fresh at 5","description":"Extending the previous sum (-2 + 5 = 3) is worse than starting fresh at 5! So currentSum = max(5, 3) = 5, and bestSum updates to 5.","state":{"type":"array","items":[{"index":0,"value":-2,"state":"skip"},{"index":1,"value":5,"state":"match"},{"index":2,"value":-1,"state":"default"},{"index":3,"value":4,"state":"default"},{"index":4,"value":-6,"state":"default"},{"index":5,"value":2,"state":"default"}],"pointers":[{"index":1,"name":"i"}],"aux":{"title":"Kadane State","entries":[{"key":"currentSum","value":5},{"key":"bestSum","value":5,"highlight":true}]},"caption":"Drop negative prefix [-2]; start fresh at index 1."}},{"title":"Index 2 (value -1): extend positive prefix","description":"Extending gives 5 + (-1) = 4, which beats starting at -1 alone. Keep currentSum = 4; bestSum stays 5.","state":{"type":"array","items":[{"index":0,"value":-2,"state":"skip"},{"index":1,"value":5,"state":"window"},{"index":2,"value":-1,"state":"active"},{"index":3,"value":4,"state":"default"},{"index":4,"value":-6,"state":"default"},{"index":5,"value":2,"state":"default"}],"pointers":[{"index":2,"name":"i"}],"aux":{"title":"Kadane State","entries":[{"key":"currentSum","value":4},{"key":"bestSum","value":5}]},"caption":"Keep carrying +4 forward into index 3."}},{"title":"Index 3 (value 4): new peak sum 8!","description":"Extending gives 4 + 4 = 8 (beating 4 alone). currentSum = 8 and bestSum improves to 8.","state":{"type":"array","items":[{"index":0,"value":-2,"state":"skip"},{"index":1,"value":5,"state":"match"},{"index":2,"value":-1,"state":"match"},{"index":3,"value":4,"state":"match"},{"index":4,"value":-6,"state":"default"},{"index":5,"value":2,"state":"default"}],"pointers":[{"index":3,"name":"i"}],"aux":{"title":"Kadane State","entries":[{"key":"currentSum","value":8},{"key":"bestSum","value":8,"highlight":true}]},"caption":"Slice [5, -1, 4] sets bestSum = 8."}},{"title":"Indices 4 & 5 (-6 then +2): finish scan","description":"At index 4 (-6), currentSum = max(-6, 8 - 6) = 2. At index 5 (+2), currentSum = max(2, 2 + 2) = 4. Neither beats bestSum = 8, so return 8.","state":{"type":"array","items":[{"index":0,"value":-2,"state":"skip"},{"index":1,"value":5,"state":"match"},{"index":2,"value":-1,"state":"match"},{"index":3,"value":4,"state":"match"},{"index":4,"value":-6,"state":"window"},{"index":5,"value":2,"state":"active"}],"pointers":[{"index":5,"name":"i"}],"aux":{"title":"Kadane Final State","entries":[{"key":"currentSum","value":4},{"key":"bestSum","value":8,"highlight":true}]},"caption":"Final answer: 8."}}]},"approaches":[{"id":"brute-force","name":"Brute Force Running Sum","recommended":false,"coreIdeaSummary":"Try every starting index i and accumulate sums forward to j.","coreIdea":"Fix every starting index i, maintain a running sum as ending index j moves right, and track the global maximum.","steps":["Initialize bestSum = nums[0].","For each start index i from 0 to n - 1, reset running = 0.","For each end index j from i to n - 1, add nums[j] to running and update bestSum = max(bestSum, running)."],"whyItWorks":"Every non-empty subarray is uniquely identified by its pair (i, j) with 0 <= i <= j < n, so checking all of them guarantees finding the maximum.","whenToUse":"Good baseline to verify small inputs against faster algorithms.","complexity":{"time":"O(n^2)","space":"O(1)","variables":"n = length of nums","boundType":"Worst-case"},"code":{"Java":"class Solution {\n    public int maxSubArray(int[] nums) {\n        int best = nums[0];\n        for (int i = 0; i < nums.length; i++) {\n            int running = 0;\n            for (int j = i; j < nums.length; j++) {\n                running += nums[j];\n                if (running > best) best = running;\n            }\n        }\n        return best;\n    }\n}","Python3":"class Solution:\n    def maxSubArray(self, nums: List[int]) -> int:\n        best = nums[0]\n        n = len(nums)\n        for i in range(n):\n            running = 0\n            for j in range(i, n):\n                running += nums[j]\n                if running > best:\n                    best = running\n        return best","Python":"class Solution(object):\n    def maxSubArray(self, nums):\n        best = nums[0]\n        n = len(nums)\n        for i in range(n):\n            running = 0\n            for j in range(i, n):\n                running += nums[j]\n                if running > best:\n                    best = running\n        return best","JavaScript":"function maxSubArray(nums) {\n  let best = nums[0];\n  for (let i = 0; i < nums.length; i++) {\n    let running = 0;\n    for (let j = i; j < nums.length; j++) {\n      running += nums[j];\n      if (running > best) best = running;\n    }\n  }\n  return best;\n}","TypeScript":"function maxSubArray(nums: number[]): number {\n  let best = nums[0];\n  for (let i = 0; i < nums.length; i++) {\n    let running = 0;\n    for (let j = i; j < nums.length; j++) {\n      running += nums[j];\n      if (running > best) best = running;\n    }\n  }\n  return best;\n}","C#":"public class Solution {\n    public int MaxSubArray(int[] nums) {\n        int best = nums[0];\n        for (int i = 0; i < nums.Length; i++) {\n            int running = 0;\n            for (int j = i; j < nums.Length; j++) {\n                running += nums[j];\n                if (running > best) best = running;\n            }\n        }\n        return best;\n    }\n}","PHP":"class Solution {\n    function maxSubArray($nums) {\n        $best = $nums[0];\n        $n = count($nums);\n        for ($i = 0; $i < $n; $i++) {\n            $running = 0;\n            for ($j = $i; $j < $n; $j++) {\n                $running += $nums[$j];\n                if ($running > $best) $best = $running;\n            }\n        }\n        return $best;\n    }\n}"}},{"id":"prefix-min","name":"Prefix Sum + Minimum Prefix Tracking","recommended":false,"coreIdeaSummary":"Maximize prefixSum[j] - min(prefixSum[i]) for i < j.","coreIdea":"Any subarray sum nums[i..j] equals prefixSum - previousPrefixSum. Tracking the smallest prefix sum seen before the current position lets us compute the best subarray ending here in O(1).","steps":["Initialize prefix = 0, minPrefix = 0, and best = nums[0].","For each value x in nums, add x to prefix.","Update best = max(best, prefix - minPrefix).","Then update minPrefix = min(minPrefix, prefix)."],"whyItWorks":"Subtracting the lowest earlier prefix sum maximizes prefix - earlierPrefix, while updating minPrefix AFTER evaluating best ensures the chosen subarray is non-empty.","whenToUse":"Great when bridging prefix-sum problems (like Best Time to Buy and Sell Stock or Subarray Sum variations).","complexity":{"time":"O(n)","space":"O(1)","variables":"n = length of nums","boundType":"Worst-case"},"code":{"Java":"class Solution {\n    public int maxSubArray(int[] nums) {\n        int prefix = 0, minPrefix = 0, best = nums[0];\n        for (int x : nums) {\n            prefix += x;\n            best = Math.max(best, prefix - minPrefix);\n            minPrefix = Math.min(minPrefix, prefix);\n        }\n        return best;\n    }\n}","Python3":"class Solution:\n    def maxSubArray(self, nums: List[int]) -> int:\n        prefix = 0\n        min_prefix = 0\n        best = nums[0]\n        for x in nums:\n            prefix += x\n            best = max(best, prefix - min_prefix)\n            min_prefix = min(min_prefix, prefix)\n        return best","Python":"class Solution(object):\n    def maxSubArray(self, nums):\n        prefix = 0\n        min_prefix = 0\n        best = nums[0]\n        for x in nums:\n            prefix += x\n            best = max(best, prefix - min_prefix)\n            min_prefix = min(min_prefix, prefix)\n        return best","JavaScript":"function maxSubArray(nums) {\n  let prefix = 0;\n  let minPrefix = 0;\n  let best = nums[0];\n  for (const x of nums) {\n    prefix += x;\n    best = Math.max(best, prefix - minPrefix);\n    minPrefix = Math.min(minPrefix, prefix);\n  }\n  return best;\n}","TypeScript":"function maxSubArray(nums: number[]): number {\n  let prefix = 0;\n  let minPrefix = 0;\n  let best = nums[0];\n  for (const x of nums) {\n    prefix += x;\n    best = Math.max(best, prefix - minPrefix);\n    minPrefix = Math.min(minPrefix, prefix);\n  }\n  return best;\n}","C#":"using System;\n\npublic class Solution {\n    public int MaxSubArray(int[] nums) {\n        int prefix = 0, minPrefix = 0, best = nums[0];\n        foreach (int x in nums) {\n            prefix += x;\n            best = Math.Max(best, prefix - minPrefix);\n            minPrefix = Math.Min(minPrefix, prefix);\n        }\n        return best;\n    }\n}","PHP":"class Solution {\n    function maxSubArray($nums) {\n        $prefix = 0;\n        $minPrefix = 0;\n        $best = $nums[0];\n        foreach ($nums as $x) {\n            $prefix += $x;\n            $best = max($best, $prefix - $minPrefix);\n            $minPrefix = min($minPrefix, $prefix);\n        }\n        return $best;\n    }\n}"}},{"id":"divide-and-conquer","name":"Divide and Conquer","recommended":false,"coreIdeaSummary":"Split at mid and take max(leftBest, rightBest, bestCrossingMid).","coreIdea":"Recursively split the array into left and right halves. The best subarray lies entirely in the left half, entirely in the right half, or crosses the midpoint.","steps":["Base case: if left == right, return nums[left].","Recursively compute leftBest on [left..mid] and rightBest on [mid+1..right].","Scan left from mid down to left to find maxLeftSuffix; scan right from mid+1 up to right to find maxRightPrefix.","Return max(leftBest, rightBest, maxLeftSuffix + maxRightPrefix)."],"whyItWorks":"Every subarray in [left..right] either skips the boundary between mid and mid+1 or spans across it, and the best crossing slice must combine the best suffix ending at mid with the best prefix starting at mid+1.","whenToUse":"Required if a follow-up asks for a divide-and-conquer solution or when extending to Segment Tree range-max-subarray queries.","complexity":{"time":"O(n log n)","space":"O(log n)","variables":"n = length of nums (recursion stack depth is log2 n)","boundType":"Worst-case"},"code":{"Java":"class Solution {\n    public int maxSubArray(int[] nums) {\n        return solve(nums, 0, nums.length - 1);\n    }\n    private int solve(int[] nums, int left, int right) {\n        if (left == right) return nums[left];\n        int mid = left + (right - left) / 2;\n        int leftBest = solve(nums, left, mid);\n        int rightBest = solve(nums, mid + 1, right);\n        int sum = 0, maxLeft = Integer.MIN_VALUE;\n        for (int i = mid; i >= left; i--) {\n            sum += nums[i];\n            if (sum > maxLeft) maxLeft = sum;\n        }\n        sum = 0; int maxRight = Integer.MIN_VALUE;\n        for (int i = mid + 1; i <= right; i++) {\n            sum += nums[i];\n            if (sum > maxRight) maxRight = sum;\n        }\n        return Math.max(Math.max(leftBest, rightBest), maxLeft + maxRight);\n    }\n}","Python3":"class Solution:\n    def maxSubArray(self, nums: List[int]) -> int:\n        def solve(left: int, right: int) -> int:\n            if left == right:\n                return nums[left]\n            mid = (left + right) // 2\n            left_best = solve(left, mid)\n            right_best = solve(mid + 1, right)\n            s = 0\n            max_left = float('-inf')\n            for i in range(mid, left - 1, -1):\n                s += nums[i]\n                max_left = max(max_left, s)\n            s = 0\n            max_right = float('-inf')\n            for i in range(mid + 1, right + 1):\n                s += nums[i]\n                max_right = max(max_right, s)\n            return max(left_best, right_best, max_left + max_right)\n        return solve(0, len(nums) - 1)","Python":"class Solution(object):\n    def maxSubArray(self, nums):\n        def solve(left, right):\n            if left == right:\n                return nums[left]\n            mid = (left + right) // 2\n            left_best = solve(left, mid)\n            right_best = solve(mid + 1, right)\n            s = 0\n            max_left = float('-inf')\n            for i in range(mid, left - 1, -1):\n                s += nums[i]\n                if s > max_left:\n                    max_left = s\n            s = 0\n            max_right = float('-inf')\n            for i in range(mid + 1, right + 1):\n                s += nums[i]\n                if s > max_right:\n                    max_right = s\n            return max(left_best, right_best, max_left + max_right)\n        return solve(0, len(nums) - 1)","JavaScript":"function maxSubArray(nums) {\n  function solve(left, right) {\n    if (left === right) return nums[left];\n    const mid = (left + right) >> 1;\n    const leftBest = solve(left, mid);\n    const rightBest = solve(mid + 1, right);\n    let s = 0;\n    let maxLeft = -Infinity;\n    for (let i = mid; i >= left; i--) {\n      s += nums[i];\n      if (s > maxLeft) maxLeft = s;\n    }\n    s = 0;\n    let maxRight = -Infinity;\n    for (let i = mid + 1; i <= right; i++) {\n      s += nums[i];\n      if (s > maxRight) maxRight = s;\n    }\n    return Math.max(leftBest, rightBest, maxLeft + maxRight);\n  }\n  return solve(0, nums.length - 1);\n}","TypeScript":"function maxSubArray(nums: number[]): number {\n  function solve(left: number, right: number): number {\n    if (left === right) return nums[left];\n    const mid = (left + right) >> 1;\n    const leftBest = solve(left, mid);\n    const rightBest = solve(mid + 1, right);\n    let s = 0;\n    let maxLeft = -Infinity;\n    for (let i = mid; i >= left; i--) {\n      s += nums[i];\n      if (s > maxLeft) maxLeft = s;\n    }\n    s = 0;\n    let maxRight = -Infinity;\n    for (let i = mid + 1; i <= right; i++) {\n      s += nums[i];\n      if (s > maxRight) maxRight = s;\n    }\n    return Math.max(leftBest, rightBest, maxLeft + maxRight);\n  }\n  return solve(0, nums.length - 1);\n}","C#":"using System;\n\npublic class Solution {\n    public int MaxSubArray(int[] nums) {\n        return Solve(nums, 0, nums.Length - 1);\n    }\n    private int Solve(int[] nums, int left, int right) {\n        if (left == right) return nums[left];\n        int mid = left + (right - left) / 2;\n        int leftBest = Solve(nums, left, mid);\n        int rightBest = Solve(nums, mid + 1, right);\n        int s = 0, maxLeft = int.MinValue;\n        for (int i = mid; i >= left; i--) {\n            s += nums[i];\n            if (s > maxLeft) maxLeft = s;\n        }\n        s = 0; int maxRight = int.MinValue;\n        for (int i = mid + 1; i <= right; i++) {\n            s += nums[i];\n            if (s > maxRight) maxRight = s;\n        }\n        return Math.Max(Math.Max(leftBest, rightBest), maxLeft + maxRight);\n    }\n}","PHP":"class Solution {\n    function maxSubArray($nums) {\n        return $this->solve($nums, 0, count($nums) - 1);\n    }\n    private function solve(&$nums, $left, $right) {\n        if ($left === $right) return $nums[$left];\n        $mid = intdiv($left + $right, 2);\n        $leftBest = $this->solve($nums, $left, $mid);\n        $rightBest = $this->solve($nums, $mid + 1, $right);\n        $s = 0; $maxLeft = PHP_INT_MIN;\n        for ($i = $mid; $i >= $left; $i--) {\n            $s += $nums[$i];\n            if ($s > $maxLeft) $maxLeft = $s;\n        }\n        $s = 0; $maxRight = PHP_INT_MIN;\n        for ($i = $mid + 1; $i <= $right; $i++) {\n            $s += $nums[$i];\n            if ($s > $maxRight) $maxRight = $s;\n        }\n        return max($leftBest, $rightBest, $maxLeft + $maxRight);\n    }\n}"}},{"id":"dp-table","name":"Tabulated Dynamic Programming (dp[i])","recommended":false,"coreIdeaSummary":"Store dp[i] = best subarray sum ending exactly at index i.","coreIdea":"Define dp[i] as the maximum subarray sum that ends at index i. Each entry depends solely on dp[i - 1] and nums[i].","steps":["Allocate dp of size n with dp[0] = nums[0] and best = dp[0].","For i from 1 to n - 1, compute dp[i] = max(nums[i], dp[i - 1] + nums[i]).","Update best = max(best, dp[i]) and return best."],"whyItWorks":"Any subarray ending at i either contains only nums[i] or appends nums[i] to a subarray ending at i - 1. Taking max(nums[i], dp[i - 1] + nums[i]) captures the optimal choice.","whenToUse":"Helpful when learning the DP recurrence before compressing dp[] into a single variable.","complexity":{"time":"O(n)","space":"O(n)","variables":"n = length of nums","boundType":"Worst-case"},"code":{"Java":"class Solution {\n    public int maxSubArray(int[] nums) {\n        int n = nums.length;\n        int[] dp = new int[n];\n        dp[0] = nums[0];\n        int best = dp[0];\n        for (int i = 1; i < n; i++) {\n            dp[i] = Math.max(nums[i], dp[i - 1] + nums[i]);\n            if (dp[i] > best) best = dp[i];\n        }\n        return best;\n    }\n}","Python3":"class Solution:\n    def maxSubArray(self, nums: List[int]) -> int:\n        dp = [0] * len(nums)\n        dp[0] = nums[0]\n        best = dp[0]\n        for i in range(1, len(nums)):\n            dp[i] = max(nums[i], dp[i - 1] + nums[i])\n            if dp[i] > best:\n                best = dp[i]\n        return best","Python":"class Solution(object):\n    def maxSubArray(self, nums):\n        dp = [0] * len(nums)\n        dp[0] = nums[0]\n        best = dp[0]\n        for i in range(1, len(nums)):\n            dp[i] = max(nums[i], dp[i - 1] + nums[i])\n            if dp[i] > best:\n                best = dp[i]\n        return best","JavaScript":"function maxSubArray(nums) {\n  const dp = new Array(nums.length);\n  dp[0] = nums[0];\n  let best = dp[0];\n  for (let i = 1; i < nums.length; i++) {\n    dp[i] = Math.max(nums[i], dp[i - 1] + nums[i]);\n    if (dp[i] > best) best = dp[i];\n  }\n  return best;\n}","TypeScript":"function maxSubArray(nums: number[]): number {\n  const dp: number[] = new Array(nums.length);\n  dp[0] = nums[0];\n  let best = dp[0];\n  for (let i = 1; i < nums.length; i++) {\n    dp[i] = Math.max(nums[i], dp[i - 1] + nums[i]);\n    if (dp[i] > best) best = dp[i];\n  }\n  return best;\n}","C#":"using System;\n\npublic class Solution {\n    public int MaxSubArray(int[] nums) {\n        int[] dp = new int[nums.Length];\n        dp[0] = nums[0];\n        int best = dp[0];\n        for (int i = 1; i < nums.Length; i++) {\n            dp[i] = Math.Max(nums[i], dp[i - 1] + nums[i]);\n            if (dp[i] > best) best = dp[i];\n        }\n        return best;\n    }\n}","PHP":"class Solution {\n    function maxSubArray($nums) {\n        $n = count($nums);\n        $dp = [$nums[0]];\n        $best = $dp[0];\n        for ($i = 1; $i < $n; $i++) {\n            $dp[$i] = max($nums[$i], $dp[$i - 1] + $nums[$i]);\n            if ($dp[$i] > $best) $best = $dp[$i];\n        }\n        return $best;\n    }\n}"}},{"id":"kadane","name":"Kadane's Algorithm (Space-Optimized DP)","recommended":true,"recommendedTradeOff":"Achieves the optimal O(n) worst-case time in one pass while compressing the DP table down to O(1) auxiliary space with zero allocations.","coreIdeaSummary":"Carry the running subarray sum only while it helps; otherwise restart at nums[i].","coreIdea":"Keep only two numbers: currentSum (best subarray ending at the current index) and bestSum (best seen anywhere). If currentSum + nums[i] < nums[i], discard the earlier negative prefix and restart at nums[i].","steps":["Initialize currentSum = nums[0] and bestSum = nums[0].","For i from 1 to n - 1, set currentSum = max(nums[i], currentSum + nums[i]).","Update bestSum = max(bestSum, currentSum).","Return bestSum."],"whyItWorks":"Since dp[i] only reads dp[i - 1], storing dp[i - 1] in currentSum preserves the exact same DP recurrence while discarding older prefixes whenever they become negative.","whenToUse":"Default optimal solution for maximum contiguous subarray sum.","complexity":{"time":"O(n)","space":"O(1)","variables":"n = length of nums","boundType":"Worst-case"},"code":{"C++":"#include <algorithm>\n#include <vector>\nusing namespace std;\n\nclass Solution {\npublic:\n    int maxSubArray(vector<int>& nums) {\n        int current = nums[0], best = nums[0];\n        for (size_t i = 1; i < nums.size(); ++i) {\n            current = max(nums[i], current + nums[i]);\n            best = max(best, current);\n        }\n        return best;\n    }\n};","Java":"class Solution {\n    public int maxSubArray(int[] nums) {\n        int current = nums[0];\n        int best = nums[0];\n        for (int i = 1; i < nums.length; i++) {\n            current = Math.max(nums[i], current + nums[i]);\n            best = Math.max(best, current);\n        }\n        return best;\n    }\n}","Python3":"class Solution:\n    def maxSubArray(self, nums: List[int]) -> int:\n        current = best = nums[0]\n        for x in nums[1:]:\n            current = max(x, current + x)\n            best = max(best, current)\n        return best","Python":"class Solution(object):\n    def maxSubArray(self, nums):\n        current = best = nums[0]\n        for x in nums[1:]:\n            current = max(x, current + x)\n            if current > best:\n                best = current\n        return best","JavaScript":"function maxSubArray(nums) {\n  let current = nums[0];\n  let best = nums[0];\n  for (let i = 1; i < nums.length; i++) {\n    current = Math.max(nums[i], current + nums[i]);\n    best = Math.max(best, current);\n  }\n  return best;\n}","TypeScript":"function maxSubArray(nums: number[]): number {\n  let current = nums[0];\n  let best = nums[0];\n  for (let i = 1; i < nums.length; i++) {\n    current = Math.max(nums[i], current + nums[i]);\n    best = Math.max(best, current);\n  }\n  return best;\n}","C#":"using System;\n\npublic class Solution {\n    public int MaxSubArray(int[] nums) {\n        int current = nums[0], best = nums[0];\n        for (int i = 1; i < nums.Length; i++) {\n            current = Math.Max(nums[i], current + nums[i]);\n            best = Math.Max(best, current);\n        }\n        return best;\n    }\n}","C":"int maxSubArray(int* nums, int numsSize) {\n    int current = nums[0], best = nums[0];\n    for (int i = 1; i < numsSize; i++) {\n        current = nums[i] > current + nums[i] ? nums[i] : current + nums[i];\n        if (current > best) best = current;\n    }\n    return best;\n}","Go":"func maxSubArray(nums []int) int {\n\tcurrent, best := nums[0], nums[0]\n\tfor _, x := range nums[1:] {\n\t\tif current+x > x {\n\t\t\tcurrent += x\n\t\t} else {\n\t\t\tcurrent = x\n\t\t}\n\t\tif current > best {\n\t\t\tbest = current\n\t\t}\n\t}\n\treturn best\n}","Kotlin":"class Solution {\n    fun maxSubArray(nums: IntArray): Int {\n        var current = nums[0]\n        var best = nums[0]\n        for (i in 1 until nums.size) {\n            current = maxOf(nums[i], current + nums[i])\n            best = maxOf(best, current)\n        }\n        return best\n    }\n}","Swift":"class Solution {\n    func maxSubArray(_ nums: [Int]) -> Int {\n        var current = nums[0]\n        var best = nums[0]\n        for x in nums.dropFirst() {\n            current = max(x, current + x)\n            best = max(best, current)\n        }\n        return best\n    }\n}","Rust":"impl Solution {\n    pub fn max_sub_array(nums: Vec<i32>) -> i32 {\n        let mut current = nums[0];\n        let mut best = nums[0];\n        for &x in &nums[1..] {\n            current = x.max(current + x);\n            best = best.max(current);\n        }\n        best\n    }\n}","Ruby":"def max_sub_array(nums)\n  current = best = nums[0]\n  nums[1..].each do |x|\n    current = [x, current + x].max\n    best = [best, current].max\n  end\n  best\nend","PHP":"class Solution {\n    function maxSubArray($nums) {\n        $current = $nums[0];\n        $best = $nums[0];\n        $n = count($nums);\n        for ($i = 1; $i < $n; $i++) {\n            $current = max($nums[$i], $current + $nums[$i]);\n            $best = max($best, $current);\n        }\n        return $best;\n    }\n}","Dart":"import 'dart:math';\n\nclass Solution {\n  int maxSubArray(List<int> nums) {\n    var current = nums[0];\n    var best = nums[0];\n    for (var i = 1; i < nums.length; i++) {\n      current = max(nums[i], current + nums[i]);\n      best = max(best, current);\n    }\n    return best;\n  }\n}","Scala":"object Solution {\n  def maxSubArray(nums: Array[Int]): Int = {\n    var current = nums(0)\n    var best = nums(0)\n    for (i <- 1 until nums.length) {\n      current = math.max(nums(i), current + nums(i))\n      best = math.max(best, current)\n    }\n    best\n  }\n}","Elixir":"defmodule Solution do\n  @spec max_sub_array(nums :: [integer]) :: integer\n  def max_sub_array([h | t]) do\n    {_cur, best} = Enum.reduce(t, {h, h}, fn x, {cur, best} ->\n      nxt = max(x, cur + x)\n      {nxt, max(best, nxt)}\n    end)\n    best\n  end\nend","Erlang":"-spec max_sub_array(Nums :: [integer()]) -> integer().\nmax_sub_array([H | T]) ->\n  max_sub_array(T, H, H).\n\nmax_sub_array([], _Cur, Best) -> Best;\nmax_sub_array([H | T], Cur, Best) ->\n  Nxt = max(H, Cur + H),\n  max_sub_array(T, Nxt, max(Best, Nxt)).","Racket":"(define/contract (max-sub-array nums)\n  (-> (listof exact-integer?) exact-integer?)\n  (let loop ([rest (cdr nums)] [cur (car nums)] [best (car nums)])\n    (if (null? rest)\n        best\n        (let* ([x (car rest)]\n               [nxt (max x (+ cur x))])\n          (loop (cdr rest) nxt (max best nxt))))))"}}],"tests":[{"name":"Example 1","args":[[-2,5,-1,4,-6,2]],"expected":8},{"name":"Example 2 (all negative)","args":[[-7,-2,-9,-4]],"expected":-2},{"name":"Single element","args":[[42]],"expected":42},{"name":"All positive","args":[[1,2,3,4]],"expected":10}],"javaDriver":"public class Main {\n  public static void main(String[] args) {\n    Solution s = new Solution();\n    if (s.maxSubArray(new int[]{-2,5,-1,4,-6,2}) != 8) throw new AssertionError(\"Ex1\");\n    if (s.maxSubArray(new int[]{-7,-2,-9,-4}) != -2) throw new AssertionError(\"Ex2\");\n    if (s.maxSubArray(new int[]{42}) != 42) throw new AssertionError(\"Single\");\n    if (s.maxSubArray(new int[]{1,2,3,4}) != 10) throw new AssertionError(\"AllPos\");\n  }\n}","phpDriver":"$s = new Solution();\n$cases = [\n  [[-2,5,-1,4,-6,2], 8],\n  [[-7,-2,-9,-4], -2],\n  [[42], 42],\n  [[1,2,3,4], 10]\n];\nforeach ($cases as $c) {\n  if ($s->maxSubArray($c[0]) !== $c[1]) { fwrite(STDERR, \"FAIL\"); exit(1); }\n}","csharpDriver":"using System;\npublic class Runner {\n  public static void Main() {\n    var s = new Solution();\n    if (s.MaxSubArray(new int[]{-2,5,-1,4,-6,2}) != 8) throw new Exception(\"Ex1\");\n    if (s.MaxSubArray(new int[]{-7,-2,-9,-4}) != -2) throw new Exception(\"Ex2\");\n    if (s.MaxSubArray(new int[]{42}) != 42) throw new Exception(\"Single\");\n    if (s.MaxSubArray(new int[]{1,2,3,4}) != 10) throw new Exception(\"AllPos\");\n  }\n}"}};
